INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  4,
  'dermatologic',
  'dermatologic',
  'pharmacotherapy',
  'Acne antibiotic stewardship',
  'vignette',
  'A 17-year-old boy has inflammatory acne on the face and trunk. He has used adapalene nightly for 8 weeks with partial improvement and still has many inflamed papules. He is not pregnant, has no tetracycline allergy, and plays outdoor sports. The clinician is choosing how to add an oral antibiotic.',
  'Which of the following is the most appropriate antibiotic plan?',
  '{"options":["Doxycycline alone, stopped only when the skin is clear for 12 months","Doxycycline plus benzoyl peroxide, with a plan to stop the antibiotic near 3 months","Oral isotretinoin started the same week as doxycycline","Topical clindamycin monotherapy continued indefinitely","Monthly azithromycin pulses without a topical agent"],"blueprintSystem":"dermatologic","taskCategory":"pharmacotherapy","blueprintTopic":"Acne antibiotic stewardship","kind":"vignette"}',
  'Doxycycline plus benzoyl peroxide, with a plan to stop the antibiotic near 3 months',
  'Doxycycline plus benzoyl peroxide, with a plan to stop the antibiotic near 3 months is correct. The 2024 AAD acne guideline strongly recommends benzoyl peroxide, topical retinoids, topical antibiotics, and oral doxycycline, and it limits systemic antibiotics. Benzoyl peroxide is paired with the antibiotic to reduce resistance, and the antibiotic course is measured in months rather than continued until some future clear year. Incorrect alternatives: Indefinite doxycycline, clindamycin alone, and azithromycin pulses without a topical partner all extend antibiotic exposure. Isotretinoin plus a tetracycline raises the risk of pseudotumor cerebri and is not how isotretinoin is started.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"Reynolds RV et al. Guidelines of care for the management of acne vulgaris. J Am Acad Dermatol 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38300170/"}]'::jsonb,
  'generated',
  'f2fe8e58d84e54b0e4aa375f77225b4df4762e08b863563158f597d08f4a4be5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  5,
  'dermatologic',
  'dermatologic',
  'pharmacotherapy',
  'Isotretinoin indications versus routine labs',
  'vignette',
  'A 20-year-old woman has nodulocystic acne with scarring after 4 months of doxycycline, tretinoin, and benzoyl peroxide. She is not pregnant, uses two contraceptive methods, and has a normal mood screen. A colleague suggests monthly complete blood counts and basic metabolic panels for the whole course because ''isotretinoin always needs them.''',
  'Which of the following best matches current acne-guideline practice for this patient?',
  '{"options":["Start isotretinoin and order baseline liver enzymes and lipids, repeating them if abnormal or if a dose change warrants it","Continue doxycycline for another year before considering isotretinoin","Start isotretinoin and a daily tetracycline together for the first 8 weeks","Defer isotretinoin because scarring alone is not an indication if some papules remain","Order a pregnancy test once at the first visit and not again"],"blueprintSystem":"dermatologic","taskCategory":"pharmacotherapy","blueprintTopic":"Isotretinoin indications versus routine labs","kind":"vignette"}',
  'Start isotretinoin and order baseline liver enzymes and lipids, repeating them if abnormal or if a dose change warrants it',
  'Start isotretinoin and order baseline liver enzymes and lipids, repeating them if abnormal or if a dose change warrants it is correct. The 2024 AAD guideline strongly recommends oral isotretinoin for acne that is severe, scarring, psychosocially burdensome, or failing standard therapy. Baseline liver enzymes and fasting lipids are obtained; routine population-wide monthly blood counts and chemistry panels are not required in otherwise healthy patients. Incorrect alternatives: Waiting another year of antibiotic after scarring has already occurred misses the indication. A tetracycline is not combined with isotretinoin. Pregnancy testing is repeated in patients who can become pregnant; one test is not the program.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"Reynolds RV et al. Guidelines of care for the management of acne vulgaris. J Am Acad Dermatol 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38300170/"}]'::jsonb,
  'generated',
  '499811ca41c00419ba1690075acde80e670a10cf793cdef9e8dcfe189b6b8623',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  4,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Perioral dermatitis after a topical steroid',
  'vignette',
  'A 28-year-old woman has 6 weeks of burning papules around the mouth and in the nasolabial folds, sparing a thin clear zone at the vermilion border. She has been applying a mid-potency topical steroid nightly, which helps for a day and then the rash returns worse. There are no comedones.',
  'Which of the following is the most appropriate first change in treatment?',
  '{"options":["Continue the steroid and add oral prednisone for 3 weeks","Stop the topical steroid and start topical metronidazole or a calcineurin inhibitor","Start oral isotretinoin the same day the steroid is stopped","Apply clobetasol to the folds for 2 weeks to break the cycle","Treat with permethrin because the distribution proves scabies"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Perioral dermatitis after a topical steroid","kind":"vignette"}',
  'Stop the topical steroid and start topical metronidazole or a calcineurin inhibitor',
  'Stop the topical steroid and start topical metronidazole or a calcineurin inhibitor is correct. Perioral dermatitis is often sustained by topical corticosteroids. Stopping the steroid and using a nonsteroid anti-inflammatory topical, sometimes with a tetracycline, is the usual first plan. Incorrect alternatives: More steroid, including clobetasol in the folds or a prednisone taper, feeds the rebound. Isotretinoin is not first-line for this limited eruption. The spared vermilion border and steroid history are not the burrows of scabies.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '8389116e98980395c33f5823e0b441026f80123e6cc945c11f0886ff4715195c',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  4,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Rosacea ocular involvement',
  'vignette',
  'A 46-year-old man has central facial erythema, telangiectasias, and papules without comedones. He also has gritty eyes, lid margin crusting, and recurrent styes. A student proposes oral isotretinoin first because the cheeks look ''phymatous,'' but there is no bulbous nasal change.',
  'Which of the following is the most appropriate initial plan?',
  '{"options":["Oral isotretinoin as the first drug for papulopustular disease without phyma","Topical metronidazole or ivermectin, lid hygiene, and ophthalmology if the eye symptoms persist","A 6-week course of oral prednisone","Topical clobetasol to the eyelids","Excision of the telangiectasias before any medical therapy"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Rosacea ocular involvement","kind":"vignette"}',
  'Topical metronidazole or ivermectin, lid hygiene, and ophthalmology if the eye symptoms persist',
  'Topical metronidazole or ivermectin, lid hygiene, and ophthalmology if the eye symptoms persist is correct. Papulopustular rosacea is treated with topical anti-inflammatory agents, and ocular disease is managed with lid care and eye referral rather than jumping to isotretinoin. Isotretinoin is reserved for more refractory or phymatous disease. Incorrect alternatives: A steroid on the lids can worsen ocular surface disease and periorificial eruptions. Prednisone and surgery are not the opening treatment for this phenotype.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '7a8935ab575a26621bcdabd08aa605acc9f80e88761b99a55986840b8bca08b6',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  5,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'AGEP versus DRESS timing',
  'vignette',
  'A 33-year-old man started amoxicillin yesterday. Today he has fever of 39 C and hundreds of pinpoint nonfollicular pustules on edematous erythema in the axillae and groin. Mucosae are intact, the skin does not shear, eosinophils are normal, and creatinine and liver enzymes are normal. He has no psoriasis history.',
  'Which of the following is the most likely diagnosis?',
  '{"options":["Drug reaction with eosinophilia and systemic symptoms","Stevens-Johnson syndrome","Acute generalized exanthematous pustulosis","Generalized pustular psoriasis","Staphylococcal scalded skin syndrome"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"AGEP versus DRESS timing","kind":"vignette"}',
  'Acute generalized exanthematous pustulosis',
  'Acute generalized exanthematous pustulosis is correct. AGEP starts within 1 to 2 days of a beta-lactam, favors flexures, and is a sterile neutrophilic pustular eruption without eosinophilia or necrolysis. Incorrect alternatives: DRESS needs a latency of weeks, eosinophilia, facial edema, and organ injury. SJS has mucosal erosions. Pustular psoriasis is not timed to one dose of a new antibiotic. Staphylococcal scalded skin is a tender superficial peel, usually in a child, not flexural pustules.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'a6babc388bdb791f6de62141fc7f16b667020f7f00ed3b7e658b06f870519720',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  4,
  'dermatologic',
  'dermatologic',
  'pharmacotherapy',
  'Inverse psoriasis steroid atrophy',
  'vignette',
  'A 44-year-old man with known plaque psoriasis has bright red, sharply bordered, glistening plaques in the gluteal cleft and axillae. Potassium hydroxide preparation is negative. He has been using clobetasol in the folds for 6 weeks and the skin is thinning.',
  'Which of the following is the most appropriate change?',
  '{"options":["Continue clobetasol daily for another 8 weeks","Switch to topical tacrolimus or a short course of a low-potency steroid, and stop the superpotent steroid","Start oral terbinafine for presumed tinea","Start methotrexate today because any fold plaque requires a systemic drug","Apply nystatin powder indefinitely"],"blueprintSystem":"dermatologic","taskCategory":"pharmacotherapy","blueprintTopic":"Inverse psoriasis steroid atrophy","kind":"vignette"}',
  'Switch to topical tacrolimus or a short course of a low-potency steroid, and stop the superpotent steroid',
  'Switch to topical tacrolimus or a short course of a low-potency steroid, and stop the superpotent steroid is correct. Inverse psoriasis lacks scale in moist folds. Superpotent steroids cause atrophy and striae there, so a calcineurin inhibitor or a brief low-potency steroid is preferred. Incorrect alternatives: A negative potassium hydroxide preparation and the psoriasis history make tinea and candida unlikely, so terbinafine or endless nystatin is the wrong turn. A limited fold plaque does not by itself require methotrexate.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'fcdda597e193e6fe1b7591fa7d834b0fa8e02c3d3ee917e1e1df963d95927a46',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Tinea capitis before empiric minoxidil',
  'vignette',
  'A 7-year-old Black boy has a 6-week patch of scale and broken hairs with occipital lymphadenopathy. A sibling has a similar patch. A caregiver has been using minoxidil foam because an online post called it alopecia areata.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Continue minoxidil for 6 months before any test","Potent topical steroid monotherapy","Potassium hydroxide or fungal culture, then oral terbinafine or griseofulvin","Intralesional triamcinolone today","Topical ketoconazole shampoo as the only treatment"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Tinea capitis before empiric minoxidil","kind":"vignette"}',
  'Potassium hydroxide or fungal culture, then oral terbinafine or griseofulvin',
  'Potassium hydroxide or fungal culture, then oral terbinafine or griseofulvin is correct. Scale, broken hairs, lymphadenopathy, and a household contact point to tinea capitis, which needs an oral antifungal because topical agents do not reach the hair shaft. Incorrect alternatives: Minoxidil and intralesional steroid treat alopecia areata and will miss a spreading dermatophyte. Shampoo alone does not cure the shaft infection.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'cbba62bb71a5681de0c0e8905fe62de3547950e8fbc87fb07e30889940abba8c',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  4,
  'dermatologic',
  'dermatologic',
  'labs',
  'Confirm onychomycosis before terbinafine',
  'vignette',
  'A 61-year-old man wants oral terbinafine for three thickened yellow great toenails. He has no skin scale. He takes simvastatin and drinks little alcohol. Liver enzymes last year were normal.',
  'Which of the following is the most appropriate step before the prescription?',
  '{"options":["Start a 12-week course today based on the nail appearance","Confirm fungus with potassium hydroxide, stain, or culture, and check baseline liver enzymes","Combine oral terbinafine with daily itraconazole","Use oral ketoconazole because it needs no monitoring","Treat with topical ciclopirox for 1 week only"],"blueprintSystem":"dermatologic","taskCategory":"labs","blueprintTopic":"Confirm onychomycosis before terbinafine","kind":"vignette"}',
  'Confirm fungus with potassium hydroxide, stain, or culture, and check baseline liver enzymes',
  'Confirm fungus with potassium hydroxide, stain, or culture, and check baseline liver enzymes is correct. Many dystrophic nails are not dermatophyte. Confirmation avoids a hepatotoxic course, and a baseline liver panel is appropriate before terbinafine, especially with a statin. Incorrect alternatives: Appearance alone misclassifies psoriasis, trauma, and mold. Stacking azoles, using oral ketoconazole, or a 1-week lacquer course are not acceptable substitutes.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'd713ce663a65aa8f2ea8b7c310beeee5452458b8d57bd3581e4e21dd7f864859',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  5,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Necrotizing infection versus cellulitis',
  'vignette',
  'A 54-year-old man with diabetes has 10 hours of severe pain in the perineum out of proportion to a small dusky patch. He is toxic, heart rate is 124/min, and crepitus is palpable. Glucose is 340 mg/dL and lactate is 4.1 mmol/L.',
  'Which of the following is the most appropriate next management?',
  '{"options":["Oral cephalexin and clinic follow-up tomorrow","Immediate surgical exploration with broad intravenous antibiotics","A 48-hour trial of intravenous vancomycin alone before any surgeon is called","Incision and drainage in the clinic if fluctuance appears","Topical mupirocin and elevation"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Necrotizing infection versus cellulitis","kind":"vignette"}',
  'Immediate surgical exploration with broad intravenous antibiotics',
  'Immediate surgical exploration with broad intravenous antibiotics is correct. Pain out of proportion, systemic toxicity, crepitus, and a dusky perineal patch are Fournier gangrene until proved otherwise. Source control is surgical and cannot wait on a day of antibiotics. Incorrect alternatives: Oral cephalexin, topical mupirocin, and clinic drainage treat uncomplicated cellulitis or an abscess. Vancomycin alone misses gram-negative and anaerobic organisms in perineal necrotizing infection.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '6de19a020bc03a175132fc06952c87778984a98a812eed7143557db12c413c57',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  4,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Erythema multiforme versus SJS',
  'vignette',
  'A 19-year-old man has 3 days of target lesions on the extremities and a few oral erosions after a recurrent herpes labialis outbreak. Body surface detachment is under 10%, Nikolsky sign is negative, and he is hemodynamically stable. He started no new drug.',
  'Which of the following is the most appropriate classification and first step?',
  '{"options":["Toxic epidermal necrolysis; transfer to a burn unit and give intravenous immunoglobulin as the only therapy","Erythema multiforme, treat the herpes recurrence, and stop any unnecessary drug, without calling this SJS","DRESS; start systemic steroids for 6 weeks","Pemphigus vulgaris; start rituximab today","Staphylococcal scalded skin; start nafcillin only"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Erythema multiforme versus SJS","kind":"vignette"}',
  'Erythema multiforme, treat the herpes recurrence, and stop any unnecessary drug, without calling this SJS',
  'Erythema multiforme, treat the herpes recurrence, and stop any unnecessary drug, without calling this SJS is correct. Typical targets on acral skin after herpes, with limited mucosal erosions and no sheet-like detachment, are erythema multiforme. Herpes-associated disease is treated by addressing the virus and supportive care. Incorrect alternatives: SJS/TEN is a drug necrolysis syndrome with atypical targets and more extensive detachment. DRESS has eosinophilia and organ injury after weeks of a drug. Pemphigus and scalded skin do not follow this herpes-timed target pattern.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'd0ff4d2f776254542bd27872aa7ad4b4c98b52f365a05e2dec48ce127f76d601',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Bullous pemphigoid versus pemphigus',
  'vignette',
  'A 76-year-old man has 2 months of tense bullae on the thighs and a flexor urticarial prodrome. Nikolsky sign is negative. Oral mucosa is spared. He takes no new medicines.',
  'Which of the following is the most likely diagnosis?',
  '{"options":["Pemphigus vulgaris","Bullous pemphigoid","Dermatitis herpetiformis","Stevens-Johnson syndrome","Porphyria cutanea tarda"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Bullous pemphigoid versus pemphigus","kind":"vignette"}',
  'Bullous pemphigoid',
  'Bullous pemphigoid is correct. Tense bullae, a negative Nikolsky sign, elderly age, and spared mucosa fit subepidermal bullous pemphigoid. Incorrect alternatives: Pemphigus has flaccid bullae, a positive Nikolsky sign, and often starts in the mouth. Dermatitis herpetiformis is intensely pruritic and grouped on elbows and knees. SJS is an acute drug necrolysis. Porphyria favors dorsal hands and is associated with hepatitis or alcohol, not tense thigh bullae in this pattern.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '1605366c7bc638e07c7eef0806da7ce4575d536bf6be9684dadd05f88f4eaa97',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
