  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  5,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Secondary syphilis mimicking pityriasis rosea',
  'vignette',
  'A 27-year-old man has 10 days of oval, scaly, salmon plaques on the trunk, including the palms. He had a painless penile ulcer 6 weeks ago that healed. He is sexually active with new partners.',
  'Which of the following is the most appropriate next test?',
  '{"options":["Reassurance that a herald patch makes biopsy unnecessary","Serum RPR or treponemal testing before calling this pityriasis rosea","Potassium hydroxide preparation only","Patch testing for nickel","Antinuclear antibody as the first test"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Secondary syphilis mimicking pityriasis rosea","kind":"vignette"}',
  'Serum RPR or treponemal testing before calling this pityriasis rosea',
  'Serum RPR or treponemal testing before calling this pityriasis rosea is correct. Palm and sole involvement plus a recent chancre makes secondary syphilis the diagnosis to exclude. Pityriasis rosea spares palms and soles. Incorrect alternatives: A herald-patch story does not override palm lesions and a chancre. Fungal prep, nickel testing, and ANA do not evaluate this systemic infection.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '01d8d305561e57487845a201ae902d1ab5ac5ee796a7855f364020eb6328fe77',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  4,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Melanoma biopsy technique',
  'vignette',
  'A 49-year-old woman has a 7-mm dark brown macule on the calf that has become irregular and multicolored over 4 months. A clinician wants tissue before a wide excision.',
  'Which of the following is the most appropriate biopsy?',
  '{"options":["Superficial shave that samples only the epidermis","Narrow excisional biopsy through the subcutis, oriented along the relaxed skin lines","Punch of the lightest edge only","Curettage and electrodesiccation as diagnosis and treatment","Cryotherapy without histology"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Melanoma biopsy technique","kind":"vignette"}',
  'Narrow excisional biopsy through the subcutis, oriented along the relaxed skin lines',
  'Narrow excisional biopsy through the subcutis, oriented along the relaxed skin lines is correct. A suspected melanoma needs a full-thickness sample so Breslow depth can be measured. A narrow excision does that and still allows later wide margins. Incorrect alternatives: A superficial shave or a punch of the pale edge can miss the deepest tumor. Curettage and cryotherapy destroy the architecture and are not diagnostic.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'af63704c85b312a8dc6fae8dfffab1a94a87ea9a6ccfd32fd7f6aef051ff4c82',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
