  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Actinic keratosis versus seborrheic keratosis',
  'vignette',
  'A 72-year-old fair-skinned farmer has several rough, sandpaper-like erythematous macules on the bald scalp. They are easier to feel than to see. A nearby stuck-on brown plaque with horn cysts is asymptomatic.',
  'Which of the following is the most appropriate statement about the rough scalp lesions?',
  '{"options":["They are seborrheic keratoses and need no treatment","They are actinic keratoses, a premalignant lesion treated with cryotherapy or a field agent","They are melanoma and require sentinel-node biopsy now","They are tinea and need oral terbinafine","They are bullous pemphigoid and need prednisone"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Actinic keratosis versus seborrheic keratosis","kind":"vignette"}',
  'They are actinic keratoses, a premalignant lesion treated with cryotherapy or a field agent',
  'They are actinic keratoses, a premalignant lesion treated with cryotherapy or a field agent is correct. Gritty sun-exposed lesions are actinic keratoses and can progress to squamous cell carcinoma. The stuck-on plaque is the seborrheic keratosis, a different lesion. Incorrect alternatives: Seborrheic keratoses are waxy and stuck-on, not sandpaper macules. Melanoma, tinea, and pemphigoid do not match this texture.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '11d6f25c73d3453f45f9b99ad717a96ab960971e41b9fdeb69938e132ebc26cd',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
