  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  5,
  'dermatologic',
  'dermatologic',
  'pharmacotherapy',
  'Hidradenitis Hurley staging',
  'vignette',
  'A 29-year-old woman has recurrent boils in both axillae with sinus tracts and a scarred bridged plaque, but no systemic sepsis today. Incision of individual nodules has been done four times this year and they return. She is not pregnant.',
  'Which of the following is the most appropriate disease-modifying direction?',
  '{"options":["Repeated incision of every nodule as the only long-term plan","Stop tobacco, start an anti-inflammatory antibiotic or biologic strategy, and refer for deroofing of the sinus tracts","A 10-day course of cephalexin each month indefinitely","Topical benzoyl peroxide as the sole therapy for tract disease","Oral isotretinoin combined with a tetracycline"],"blueprintSystem":"dermatologic","taskCategory":"pharmacotherapy","blueprintTopic":"Hidradenitis Hurley staging","kind":"vignette"}',
  'Stop tobacco, start an anti-inflammatory antibiotic or biologic strategy, and refer for deroofing of the sinus tracts',
  'Stop tobacco, start an anti-inflammatory antibiotic or biologic strategy, and refer for deroofing of the sinus tracts is correct. Hurley II disease with sinus tracts is not cured by serial incision. Anti-inflammatory antibiotics, and for more extensive disease a TNF inhibitor, plus surgical deroofing, address the tunnels. Incorrect alternatives: Cephalexin pulses and benzoyl peroxide alone do not close sinus tracts. Isotretinoin plus a tetracycline is the wrong combination and is not first-line for tunnels.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '652486539be62d1a0734bd374b5e5eb565a99e2783db2035377ce0527a6c1e23',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
