  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  4,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Scabies treatment failure from contacts',
  'vignette',
  'A 35-year-old man and his partner have nocturnal pruritus and burrows in the finger webs. He used permethrin once from the neck down and washed it off at 6 hours. His partner was not treated. One week later he is still itching and has new burrows.',
  'Which of the following best explains the failure?',
  '{"options":["Permethrin never works and ivermectin is mandatory for ordinary scabies","The cream was removed too soon and the untreated partner reinfested him","The itch at one week proves treatment failure even if burrows are gone","Steroids should replace the scabicide","The rash is pityriasis rosea and permethrin was irrelevant"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Scabies treatment failure from contacts","kind":"vignette"}',
  'The cream was removed too soon and the untreated partner reinfested him',
  'The cream was removed too soon and the untreated partner reinfested him is correct. Permethrin is left on about 8 to 14 hours and repeated in a week, and close contacts are treated together. New burrows mean living mites, not just post-scabetic itch. Incorrect alternatives: Ordinary scabies does not require ivermectin first; crusted scabies does. Itch can persist after cure, but new burrows do not. Steroids and a pityriasis label ignore the burrows.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'aaafd3ca340f0e472895b0266e8fced15bfdb801c641f144c5d5115c76785e0d',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
