  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Hot-tub folliculitis',
  'vignette',
  'A 22-year-old woman has 48 hours of pruritic follicular pustules on the trunk and buttocks that began the day after sitting in a poorly chlorinated hot tub. She is afebrile and otherwise well.',
  'Which of the following is the most appropriate advice?',
  '{"options":["Incision of every pustule and intravenous vancomycin","Reassurance that Pseudomonas folliculitis is usually self-limited, and avoid the tub until it is properly treated","Oral ketoconazole for 6 weeks","Immediate isotretinoin","Permethrin for the household"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Hot-tub folliculitis","kind":"vignette"}',
  'Reassurance that Pseudomonas folliculitis is usually self-limited, and avoid the tub until it is properly treated',
  'Reassurance that Pseudomonas folliculitis is usually self-limited, and avoid the tub until it is properly treated is correct. Hot-tub folliculitis from Pseudomonas is uncomfortable but typically resolves without antibiotics in a healthy host. The exposure is the clue. Incorrect alternatives: Vancomycin, long azoles, isotretinoin, and permethrin treat other diseases and do not fix the water source.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'bbd750d7919ce9f7d0d7523cd20908c2efb6b8868c6b0a7adb325624c2ca7556',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
