  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  5,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Herpes zoster ophthalmicus',
  'vignette',
  'A 68-year-old man has a painful vesicular rash on the tip of the nose and the forehead, respecting the midline. The eye is red and he reports photophobia. Symptoms began yesterday.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Topical steroid drops from the primary clinician without an eye exam","Oral valacyclovir started now and same-day ophthalmology evaluation","Observation because Hutchinson sign is only a skin finding","Oral acyclovir started after the rash has crusted","A shingles vaccine dose today as treatment"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Herpes zoster ophthalmicus","kind":"vignette"}',
  'Oral valacyclovir started now and same-day ophthalmology evaluation',
  'Oral valacyclovir started now and same-day ophthalmology evaluation is correct. Vesicles on the nasal tip mean nasociliary involvement and a real risk of keratitis. Antiviral therapy is most useful when started early, and the cornea needs a slit lamp. Incorrect alternatives: Steroid drops without an exam can worsen herpes keratitis. Waiting for crusts misses the treatment window. Vaccine is prevention, not treatment of active zoster.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '36c17e4cedf9a1aee54a555ed9da9097cb5e2c0433794a5aea33cfa3327ec424',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
