  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Molluscum in an adult',
  'vignette',
  'A 31-year-old man has 30 umbilicated facial and groin papules that have spread for 3 months. He has had thrush once. He has never had an HIV test.',
  'Which of the following is the most appropriate next step beyond local treatment?',
  '{"options":["Reassurance that widespread adult molluscum needs no systemic evaluation","HIV antigen/antibody testing","Oral terbinafine","A skin biopsy before any counseling","Isotretinoin"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Molluscum in an adult","kind":"vignette"}',
  'HIV antigen/antibody testing',
  'HIV antigen/antibody testing is correct. Numerous facial molluscum in an adult is a marker of impaired cellular immunity until HIV is excluded. Incorrect alternatives: Local destruction can still be offered, but skipping the HIV test is the error. Terbinafine and isotretinoin do not treat poxvirus. Biopsy is optional when the umbilicated look is classic.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '4bc9e56201d585fee17a268d967c80b6c80c65daa51e37eaa8abe8d6a0aca479',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
