  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Stasis dermatitis versus cellulitis',
  'vignette',
  'A 74-year-old woman with venous insufficiency has bilateral reddish-brown, itchy, scaly skin above the medial malleoli for 2 months. Both legs are involved equally. She is afebrile, and there is no unilateral expanding warmth.',
  'Which of the following is the most appropriate treatment?',
  '{"options":["Intravenous vancomycin for bilateral cellulitis","Compression and a topical corticosteroid for stasis dermatitis","Oral terbinafine for 12 weeks","Systemic prednisone for bullous pemphigoid","Incision of the pigmented skin"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Stasis dermatitis versus cellulitis","kind":"vignette"}',
  'Compression and a topical corticosteroid for stasis dermatitis',
  'Compression and a topical corticosteroid for stasis dermatitis is correct. Chronic bilateral medial-malleolar ochre dermatitis is venous stasis, not infection. Compression addresses the edema and a mild steroid settles the itch. Incorrect alternatives: Cellulitis is almost never bilateral and symmetric. Antifungals, pemphigoid therapy, and incision do not treat venous hypertension.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '160ae3dd173ed3a101d42c038858ec609f2e2c9273879093ece8d958b9c9ced2',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'intervention',
  'Burn referral depth',
  'vignette',
  'A 40-year-old man spilled hot oil on the dorsum of his dominant hand 2 hours ago. The area is white, dry, and insensate, about 2% of body surface, with surrounding moist blisters that blanch slowly. He has no inhalation injury.',
  'Which of the following is the most appropriate disposition for the white insensate area?',
  '{"options":["Outpatient silicone dressing only, because any hand burn under 5% can stay home","Burn-center referral because a full-thickness burn of the hand needs specialty care","Immediate split-thickness skin graft in the clinic","Topical silver and a 2-week wait before any referral decision","Oral cephalexin as the main treatment"],"blueprintSystem":"dermatologic","taskCategory":"intervention","blueprintTopic":"Burn referral depth","kind":"vignette"}',
  'Burn-center referral because a full-thickness burn of the hand needs specialty care',
  'Burn-center referral because a full-thickness burn of the hand needs specialty care is correct. A white, dry, insensate burn is full thickness. Hand burns, even when small, are a standard reason for burn-center referral. Incorrect alternatives: Size under 5% does not override location and depth. Clinic grafting and a 2-week delay are not the primary-care plan. Antibiotics do not treat the depth.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '7375a08d3a89b3f72443670713fe347baf0bc3e8deecbe7d09a53dc0f26cf8cd',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Pressure injury staging',
  'vignette',
  'A 82-year-old man who has been bedbound has a sacral wound with full-thickness skin loss. Subcutaneous fat is visible, but bone, tendon, and muscle are not. Slough is minimal and there is no purple intact skin.',
  'Which of the following is the correct stage?',
  '{"options":["Stage 1","Stage 2","Stage 3","Stage 4","Deep-tissue pressure injury"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Pressure injury staging","kind":"vignette"}',
  'Stage 3',
  'Stage 3 is correct. Stage 3 is full-thickness skin loss that may show fat but not bone, tendon, or muscle. Incorrect alternatives: Stage 1 is intact nonblanchable erythema. Stage 2 stops at the dermis. Stage 4 exposes bone, tendon, or muscle. Deep-tissue injury is persistent purple or maroon intact skin or a blood blister.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '58f43ffb3157ff88273a3b4c68a5573d950d1ac97dac85079fd10c07c17fcbe5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Acanthosis and insulin resistance',
  'vignette',
  'A 16-year-old boy with a BMI of 36 kg/m2 has velvety hyperpigmented plaques on the neck and axillae. He has no diarrhea or cancer symptoms. Fasting glucose is 112 mg/dL.',
  'Which of the following is the most appropriate next evaluation?',
  '{"options":["Upper endoscopy for gastric cancer","Assessment for insulin resistance and type 2 diabetes","Skin biopsy before any laboratory test","Oral ketoconazole","Reassurance that the finding is only cosmetic and needs no metabolic test"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Acanthosis and insulin resistance","kind":"vignette"}',
  'Assessment for insulin resistance and type 2 diabetes',
  'Assessment for insulin resistance and type 2 diabetes is correct. Acanthosis nigricans in an adolescent with obesity is a skin sign of insulin resistance. An impaired fasting glucose already supports that evaluation. Incorrect alternatives: Malignant acanthosis is rare and usually sudden in an older adult with weight loss. Biopsy and antifungals are not the first step, and calling it purely cosmetic skips the glucose problem.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '6c2c5a6a8d1e13d8af0db993c6e3cd16de8a98d13dea985e896c70c869b21167',
