INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'pharmacotherapy',
  'Doxycycline phototoxicity',
  'vignette',
  'A 19-year-old woman started doxycycline for acne 5 days ago and spent a day at the beach. She now has burning erythema on the nose, forearms, and dorsal hands in a sharp swimsuit pattern, with nail-area tenderness. She has no mucosal erosions.',
  'Which of the following is the most likely explanation?',
  '{"options":["Stevens-Johnson syndrome from the first doses","Doxycycline phototoxicity","Allergic contact dermatitis to the ocean","Porphyria cutanea tarda","Lupus malar rash"],"blueprintSystem":"dermatologic","taskCategory":"pharmacotherapy","blueprintTopic":"Doxycycline phototoxicity","kind":"vignette"}',
  'Doxycycline phototoxicity',
  'Doxycycline phototoxicity is correct. Tetracyclines cause exaggerated sunburn in exposed skin, often within days of starting the drug. Incorrect alternatives: SJS has mucosal necrolysis and targetoid detachment, not a swimsuit sunburn. Contact allergy is not limited to the sun-exposed edge of a new tetracycline. Porphyria and acute cutaneous lupus have different chronic contexts.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'fb32d4317e0026da415c6576c4e3fbd54484954450fa13dd0730cbe6fd1c8972',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
