  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Urticaria and anaphylaxis epinephrine',
  'vignette',
  'A 25-year-old woman has 20 minutes of generalized hives, lip swelling, wheeze, and a blood pressure of 86/50 mm Hg after a bee sting. She is still talking.',
  'Which of the following is the most appropriate immediate drug?',
  '{"options":["Diphenhydramine intramuscularly as the only drug","Epinephrine intramuscularly in the mid-anterolateral thigh","Oral prednisone before any other drug","Ranitidine intravenously as first-line therapy","A topical steroid to the hives"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Urticaria and anaphylaxis epinephrine","kind":"vignette"}',
  'Epinephrine intramuscularly in the mid-anterolateral thigh',
  'Epinephrine intramuscularly in the mid-anterolateral thigh is correct. Hypotension with wheeze and hives is anaphylaxis. Intramuscular epinephrine is the first drug and should not be delayed for antihistamines or steroids. Incorrect alternatives: Antihistamines and steroids do not reverse airway edema or shock. A topical steroid does nothing for this emergency.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '30d2f6ea5fe753b3a92f92fcf210d3dbc7fe22d959c5089f9ace0a4c24d62b3b',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
