  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Lichen planus and hepatitis C',
  'vignette',
  'A 47-year-old man has intensely pruritic, polygonal, purple, flat-topped papules on the wrists with white lacy lines on the buccal mucosa. He has no new drugs.',
  'Which of the following associated test is most appropriate?',
  '{"options":["Hepatitis C antibody","Rapid plasma reagin as the only test, because Wickham striae are syphilitic","Skin scraping for scabies as the first and only test","Colonoscopy for a juvenile polyp syndrome","Serum tryptase"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Lichen planus and hepatitis C","kind":"vignette"}',
  'Hepatitis C antibody',
  'Hepatitis C antibody is correct. The purple polygonal papules and Wickham striae are lichen planus, which is associated with hepatitis C and should prompt that test. Incorrect alternatives: Secondary syphilis can mimic many rashes but does not own this classic lichen-planus morphology. Scabies has burrows. Tryptase evaluates mast-cell disease. Colonoscopy is unrelated.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '56f9168dce1ecf12996376237baf8f1885850228877ab8a2ad5daf3c221924f2',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'diagnosis',
  'Erythema toxicum versus infection',
  'vignette',
  'A 2-day-old term infant, feeding well and afebrile, has blotchy erythematous macules with tiny central pustules on the trunk. Palms and soles are spared. The rash was absent at birth. Wright stain of a pustule shows many eosinophils.',
  'Which of the following is the most appropriate management?',
  '{"options":["Intravenous acyclovir","Reassurance that erythema toxicum neonatorum resolves without treatment","Oral fluconazole","Isolation for congenital candidiasis","A full sepsis evaluation because every neonatal pustule is infection"],"blueprintSystem":"dermatologic","taskCategory":"diagnosis","blueprintTopic":"Erythema toxicum versus infection","kind":"vignette"}',
  'Reassurance that erythema toxicum neonatorum resolves without treatment',
  'Reassurance that erythema toxicum neonatorum resolves without treatment is correct. Erythema toxicum appears after birth in a well term infant, spares palms and soles, and the pustules are eosinophilic. Incorrect alternatives: Herpes and candida are not eosinophilic and the infant is well. Congenital infections more often present at birth and involve palms or soles. A sepsis workup is not required for this classic picture.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '5178f4d343bc0943f2e2de12f3e0d4b068bc43615e9c1c97bc1c52b171b87cc3',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
