  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'dermatologic',
  3,
  'dermatologic',
  'dermatologic',
  'pharmacotherapy',
  'Impetigo limited disease',
  'vignette',
  'A 5-year-old girl has three honey-colored crusted patches on the chin. She is afebrile, and there is no cellulitis. She has no drug allergies.',
  'Which of the following is the most appropriate treatment?',
  '{"options":["Topical mupirocin","Intravenous vancomycin","Oral terbinafine","Permethrin","A superpotent steroid"],"blueprintSystem":"dermatologic","taskCategory":"pharmacotherapy","blueprintTopic":"Impetigo limited disease","kind":"vignette"}',
  'Topical mupirocin',
  'Topical mupirocin is correct. Limited nonbullous impetigo in a well child is treated with topical mupirocin. Oral antibiotics are for numerous lesions or when topical therapy is impractical. Incorrect alternatives: Intravenous vancomycin is for severe resistant infection. Terbinafine, permethrin, and steroids treat fungus, scabies, and dermatitis, not streptococcal or staphylococcal crusts.',
  '["pance","PANCE-2025","dermatologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '351ee7551ec860065e5e14c8e58178a94ee8a33e33c5fadedc4ff230aed33085',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'labs',
  'Microhematuria definition',
  'vignette',
  'A 44-year-old woman has a urine dipstick that reads ''trace blood'' at a wellness visit. She has no pain, no visible blood, and no urinary symptoms. Microscopy was not done. A colleague wants to book cystoscopy because the dipstick was positive.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Cystoscopy and CT urography this week","Microscopic urinalysis; do not diagnose microhematuria from the dipstick alone","Start nitrofurantoin for 5 days","Reassure her that trace blood never needs microscopy","Schedule a renal biopsy"],"blueprintSystem":"genitourinary","taskCategory":"labs","blueprintTopic":"Microhematuria definition","kind":"vignette"}',
  'Microscopic urinalysis; do not diagnose microhematuria from the dipstick alone',
  'Microscopic urinalysis; do not diagnose microhematuria from the dipstick alone is correct. The 2025 AUA/SUFU guideline defines microhematuria as more than 3 red cells per high-power field on microscopy of a properly collected specimen. A positive dipstick only triggers that microscopy. Incorrect alternatives: Cystoscopy and CT are not the response to an unconfirmed dipstick. Antibiotics and renal biopsy have no target here. Skipping microscopy leaves the dipstick uninterpreted.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Barocas DA et al. Updates to Microhematuria: AUA/SUFU Guideline (2025). J Urol 2025","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000004490"}]'::jsonb,
  'generated',
  'deaca81936e1c6b93555a4d80e3b1f5ad56a1d04b23d664e6385f95fefc660e7',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  5,
  'genitourinary',
  'genitourinary',
  'labs',
  'Low-risk microhematuria 2025',
  'vignette',
  'A 36-year-old woman, never a smoker, has 6 red cells per high-power field on one microscopic urinalysis. Blood pressure and creatinine are normal. She has no gross hematuria, no irritative symptoms, and no occupational or family urothelial risk. The dipstick finding was confirmed on microscopy.',
  'Which of the following is the most appropriate urologic plan?',
  '{"options":["Immediate cystoscopy and CT urography","Repeat urinalysis within 6 months, not immediate cystoscopy or imaging","Cystoscopy and renal ultrasound now","Urine cytology every 3 months for 2 years","Start an alpha blocker and recheck in a year"],"blueprintSystem":"genitourinary","taskCategory":"labs","blueprintTopic":"Low-risk microhematuria 2025","kind":"vignette"}',
  'Repeat urinalysis within 6 months, not immediate cystoscopy or imaging',
  'Repeat urinalysis within 6 months, not immediate cystoscopy or imaging is correct. She meets every 2025 low/negligible criterion: woman under 60, 3 to 10 red cells, never smoker, and no extra risk factor. That group gets a repeat urinalysis within 6 months rather than an immediate scope or scan. Incorrect alternatives: Immediate cystoscopy with CT is the high-risk path. Cystoscopy plus ultrasound is the intermediate path. Cytology surveillance and an alpha blocker do not evaluate this finding.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Barocas DA et al. Updates to Microhematuria: AUA/SUFU Guideline (2025). J Urol 2025","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000004490"}]'::jsonb,
  'generated',
  'd90fcb20d8715c083ccac6660a893d0b8aaadf61640d46054efe2d93a6c7a72d',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  5,
  'genitourinary',
  'genitourinary',
  'labs',
  'Woman not high-risk by age alone',
  'vignette',
  'A 64-year-old woman has 8 red cells per high-power field. She has never smoked, has no gross hematuria, and has no other urothelial risk factor. Creatinine is normal. A partner trained on the 2020 table wants CT urography because ''any woman over 60 is high risk.''',
  'Which of the following is the most appropriate evaluation?',
  '{"options":["Cystoscopy and CT urography, because age alone makes her high risk","Cystoscopy and renal ultrasound; age alone does not place a woman in the high-risk group","Repeat urinalysis in 6 months with no imaging, because 8 red cells is always low risk","No further testing after a single sample","Renal biopsy"],"blueprintSystem":"genitourinary","taskCategory":"labs","blueprintTopic":"Woman not high-risk by age alone","kind":"vignette"}',
  'Cystoscopy and renal ultrasound; age alone does not place a woman in the high-risk group',
  'Cystoscopy and renal ultrasound; age alone does not place a woman in the high-risk group is correct. In the 2025 amendment, women are not high risk from age alone. Age 60 or older with 3 to 10 red cells and no high-risk feature is intermediate risk, which is cystoscopy plus renal ultrasound. Incorrect alternatives: CT urography is for high-risk features such as more than 25 red cells, prior gross hematuria, or heavy smoking. Eight red cells at age 64 is not the low-risk pattern, so a 6-month delay without a scope is too little. One sample and a biopsy are not the pathway.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Barocas DA et al. Updates to Microhematuria: AUA/SUFU Guideline (2025). J Urol 2025","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000004490"}]'::jsonb,
  'generated',
  'b72b9d0072c9d9f2357011e4e47b36cd645c7cd4c5f2307d89d9dc0384e8e9a2',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'labs',
  'High-risk microhematuria',
  'vignette',
  'A 71-year-old man has 12 red cells per high-power field. He smoked 40 pack-years and quit 2 years ago. He has no flank pain. Creatinine is 1.0 mg/dL. He takes aspirin 81 mg.',
  'Which of the following is the most appropriate evaluation?',
  '{"options":["Stop aspirin and repeat the urinalysis before any workup","Cystoscopy and axial upper-tract imaging","Repeat urinalysis in 6 months only","Renal ultrasound without cystoscopy","Empiric ciprofloxacin for 7 days"],"blueprintSystem":"genitourinary","taskCategory":"labs","blueprintTopic":"High-risk microhematuria","kind":"vignette"}',
  'Cystoscopy and axial upper-tract imaging',
  'Cystoscopy and axial upper-tract imaging is correct. Age 60 or older in a man, and a greater than 30 pack-year smoking history, are high-risk features. High-risk microhematuria is evaluated with cystoscopy and axial upper-tract imaging. Aspirin does not cancel that evaluation. Incorrect alternatives: Holding aspirin and waiting, ultrasound without a scope, a 6-month delay, and antibiotics all under-evaluate a high-risk bladder and upper tract.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Barocas DA et al. Updates to Microhematuria: AUA/SUFU Guideline (2025). J Urol 2025","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000004490"}]'::jsonb,
  'generated',
  '913a8bd6273647477892039f6d6a0ccd5a636f2da9ab6459e6035c9a3257f4a9',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'labs',
  'Hematuria after a treated UTI',
  'vignette',
  'A 29-year-old woman had culture-proven cystitis with visible blood. She completed nitrofurantoin and is now asymptomatic. A colleague wants cystoscopy tomorrow because the first specimen had too many red cells to count.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Cystoscopy and CT urography before a follow-up urinalysis","Repeat urinalysis with microscopy after the infection has been treated","A 6-week course of ciprofloxacin","Renal biopsy","Start tamsulosin"],"blueprintSystem":"genitourinary","taskCategory":"labs","blueprintTopic":"Hematuria after a treated UTI","kind":"vignette"}',
  'Repeat urinalysis with microscopy after the infection has been treated',
  'Repeat urinalysis with microscopy after the infection has been treated is correct. Hematuria blamed on a urinary infection is rechecked after treatment. Persistent microhematuria is then risk-stratified. The bloody specimen during infection is not itself the staging sample. Incorrect alternatives: Immediate cystoscopy, a long quinolone course, biopsy, and an alpha blocker skip that confirmation.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Barocas DA et al. Updates to Microhematuria: AUA/SUFU Guideline (2025). J Urol 2025","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000004490"}]'::jsonb,
  'generated',
  '30c06ce7fe08c75280d1a741dd49db5f5b1778997d0551e2e0105c56abbce158',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'pharmacotherapy',
  'Asymptomatic bacteriuria',
  'vignette',
  'A 78-year-old woman in a clinic has a urine culture with 100,000 CFU/mL of E. coli sent because the urine looked cloudy. She has no dysuria, frequency, fever, or flank pain. She is not pregnant and has no planned urologic procedure.',
  'Which of the following is the most appropriate treatment?',
  '{"options":["Nitrofurantoin for 5 days","No antibiotics","Ciprofloxacin for 7 days","Intravenous ceftriaxone once","A 14-day course of trimethoprim-sulfamethoxazole"],"blueprintSystem":"genitourinary","taskCategory":"pharmacotherapy","blueprintTopic":"Asymptomatic bacteriuria","kind":"vignette"}',
  'No antibiotics',
  'No antibiotics is correct. The 2019 IDSA guideline recommends against treating asymptomatic bacteriuria in nonpregnant older adults. Cloudiness is not a symptom. Incorrect alternatives: Every listed antibiotic course treats a diagnosis she does not have and adds resistance and adverse effects.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Nicolle LE et al. Clinical Practice Guideline for the Management of Asymptomatic Bacteriuria: 2019 Update by IDSA. Clin Infect Dis 2019","url":"https://pubmed.ncbi.nlm.nih.gov/30895288/"}]'::jsonb,
  'generated',
  '69f30dc469d7815f5aa881ed07133ab2c55d3cf9f1e6dda1b6c2d8b98e7f64ce',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'pharmacotherapy',
  'Asymptomatic bacteriuria in pregnancy',
  'vignette',
  'A 26-year-old woman at 12 weeks'' gestation has a screening urine culture with 100,000 CFU/mL of pan-sensitive E. coli. She has no urinary symptoms. She has a penicillin allergy limited to a childhood rash she cannot describe.',
  'Which of the following is the most appropriate plan?',
  '{"options":["No antibiotics until she develops dysuria","Treat the bacteriuria with an agent safe in pregnancy and prove the culture clears","Ciprofloxacin for 3 days","Delay treatment until the third trimester","Weekly nitrofurantoin through delivery without a test of cure"],"blueprintSystem":"genitourinary","taskCategory":"pharmacotherapy","blueprintTopic":"Asymptomatic bacteriuria in pregnancy","kind":"vignette"}',
  'Treat the bacteriuria with an agent safe in pregnancy and prove the culture clears',
  'Treat the bacteriuria with an agent safe in pregnancy and prove the culture clears is correct. Pregnancy is an exception to the ''do not treat asymptomatic bacteriuria'' rule because untreated bacteriuria raises the risk of pyelonephritis and adverse pregnancy outcomes. A test of cure follows treatment. Incorrect alternatives: Waiting for symptoms, using a fluoroquinolone, delaying until the third trimester, and an unmonitored drug through delivery are not the guideline approach.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Nicolle LE et al. Clinical Practice Guideline for the Management of Asymptomatic Bacteriuria: 2019 Update by IDSA. Clin Infect Dis 2019","url":"https://pubmed.ncbi.nlm.nih.gov/30895288/"}]'::jsonb,
  'generated',
  '6e6ffeabe5af1537bccc9f373f5b63fea07ec1a77838466d15b8c0e43859130b',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
