  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  5,
  'genitourinary',
  'genitourinary',
  'diagnosis',
  'Infected obstructing stone',
  'vignette',
  'A 52-year-old woman has fever of 39.2 C, a heart rate of 118/min, and left flank pain. CT shows a 6-mm left proximal ureteral stone with hydronephrosis. Creatinine is 1.6 mg/dL. Urinalysis has white cells and nitrites. Antibiotics have just been started.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Medical expulsive therapy with tamsulosin and outpatient follow-up","Urgent decompression of the collecting system plus antibiotics","Extracorporeal shock-wave lithotripsy in the clinic today","Potassium citrate and a 24-hour urine collection before any procedure","Observation until the fever breaks, then schedule ureteroscopy next week"],"blueprintSystem":"genitourinary","taskCategory":"diagnosis","blueprintTopic":"Infected obstructing stone","kind":"vignette"}',
  'Urgent decompression of the collecting system plus antibiotics',
  'Urgent decompression of the collecting system plus antibiotics is correct. An obstructing stone with sepsis is a drainage emergency. Antibiotics do not reach a closed space reliably, and expulsive therapy is for the stable patient. Incorrect alternatives: Tamsulosin, delayed ureteroscopy, clinic lithotripsy, and a metabolic workup do not decompress the infected kidney.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"American Urological Association. Medical Management of Kidney Stones: AUA Guideline (2026). J Urol 2026","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000005227"}]'::jsonb,
  'generated',
  '9afbea08e51aa11017a9804d41334211e17ae544e3138e8a0d2cf32e65be14ba',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
