  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'pharmacotherapy',
  'Dietary calcium and calcium stones',
  'vignette',
  'A 40-year-old man passed a calcium oxalate stone. A 24-hour urine shows high urinary calcium and normal oxalate. He has already been told to reach a high urine volume. He asks if he should stop all dairy.',
  'Which of the following is the most appropriate diet advice?',
  '{"options":["A low-calcium diet to starve the stone of calcium","Keep normal dietary calcium, limit sodium, and do not restrict calcium-containing foods","A high-oxalate diet to bind calcium","Stop fluids overnight so urine stays concentrated","Start allopurinol before any diet change"],"blueprintSystem":"genitourinary","taskCategory":"pharmacotherapy","blueprintTopic":"Dietary calcium and calcium stones","kind":"vignette"}',
  'Keep normal dietary calcium, limit sodium, and do not restrict calcium-containing foods',
  'Keep normal dietary calcium, limit sodium, and do not restrict calcium-containing foods is correct. Low dietary calcium can raise oxalate absorption and does not prevent calcium stones. Normal calcium intake with sodium restriction is the dietary pattern, along with enough fluid to dilute the urine. Incorrect alternatives: A high-oxalate diet and overnight fluid restriction worsen risk. Allopurinol is for selected hyperuricosuria, not the first answer to a dairy question.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"American Urological Association. Medical Management of Kidney Stones: AUA Guideline (2026). J Urol 2026","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000005227"}]'::jsonb,
  'generated',
  '5ca790aba2d45404df825b5d368c2f0876ee636b48e90a8a67436314f1bc9393',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
