  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'pharmacotherapy',
  'Potassium citrate for hypocitraturia',
  'vignette',
  'A 37-year-old woman has had three calcium oxalate stones. Her 24-hour urine shows low citrate and normal calcium, oxalate, and uric acid. She has no urinary infection with a urease-splitting organism. Serum potassium and creatinine are normal.',
  'Which of the following is the most appropriate medication?',
  '{"options":["Allopurinol","Potassium citrate","Hydrochlorothiazide as the only drug, despite normal urine calcium","Sodium bicarbonate tablets taken only on stone days","Acetazolamide"],"blueprintSystem":"genitourinary","taskCategory":"pharmacotherapy","blueprintTopic":"Potassium citrate for hypocitraturia","kind":"vignette"}',
  'Potassium citrate',
  'Potassium citrate is correct. Recurrent calcium stones with low urinary citrate are treated with alkali, and potassium citrate is the usual agent. It raises citrate and urinary pH without a sodium load. Incorrect alternatives: Allopurinol targets hyperuricosuria. A thiazide is for high urine calcium. Sodium alkali adds a sodium load. Acetazolamide lowers citrate and can cause stones.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"American Urological Association. Medical Management of Kidney Stones: AUA Guideline (2026). J Urol 2026","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000005227"}]'::jsonb,
  'generated',
  'efd8969e474ac749b83725f7914317830eed79056487dc69f31c13bcbb5dcf2c',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
