  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  5,
  'genitourinary',
  'genitourinary',
  'diagnosis',
  'Testicular torsion timing',
  'vignette',
  'A 15-year-old boy woke with 3 hours of severe left testicular pain and vomiting. The left testis is high and horizontal, and the cremasteric reflex is absent. The emergency department can obtain a scrotal ultrasound in about 90 minutes. A urologist is in the hospital.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Wait for Doppler ultrasound before calling urology","Immediate urologic exploration rather than delaying for imaging","Oral levofloxacin and recheck tomorrow","Elevation of the testis and discharge if the pain eases","Antibiotics for epididymitis because pain that eases with elevation excludes torsion"],"blueprintSystem":"genitourinary","taskCategory":"diagnosis","blueprintTopic":"Testicular torsion timing","kind":"vignette"}',
  'Immediate urologic exploration rather than delaying for imaging',
  'Immediate urologic exploration rather than delaying for imaging is correct. A classic torsion presentation is a surgical diagnosis. Imaging is for uncertain cases and must not delay the operating room when the story and examination already fit. Incorrect alternatives: Antibiotics, next-day review, and the Prehn sign do not salvage a torsed testis. Relief with elevation is not specific enough to send him home.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'db02767ae4706ac3bbeff86c576d9906fc9fe1ee86ebf9289591dcbac0144ed8',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
