  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'pharmacotherapy',
  'Epididymitis by age',
  'vignette',
  'A 22-year-old man has 2 days of gradual left scrotal pain and dysuria. He is sexually active. The testis is not high-riding, the cremasteric reflex is present, and Doppler ultrasound shows increased flow. He has no drug allergies.',
  'Which of the following is the most appropriate treatment?',
  '{"options":["Ceftriaxone plus doxycycline","Ciprofloxacin alone","Supportive care only","Immediate surgical exploration tonight","Trimethoprim-sulfamethoxazole for 3 days"],"blueprintSystem":"genitourinary","taskCategory":"pharmacotherapy","blueprintTopic":"Epididymitis by age","kind":"vignette"}',
  'Ceftriaxone plus doxycycline',
  'Ceftriaxone plus doxycycline is correct. Epididymitis in a sexually active man under 35 is treated for gonorrhea and chlamydia. Preserved flow and a present cremasteric reflex make torsion unlikely. Incorrect alternatives: A fluoroquinolone alone misses gonorrhea. Three days of trimethoprim is not the STI regimen. Surgery is for torsion, and supportive care leaves the infection untreated.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Workowski KA et al. Sexually Transmitted Infections Treatment Guidelines, 2021. MMWR Recomm Rep 2021","url":"https://www.cdc.gov/std/treatment-guidelines/epididymitis.htm"}]'::jsonb,
  'generated',
  '3b76586553bc0279b08051ab0fb6e9a406fa633ae16232304b17f1d8454a4fbe',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
