  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'pharmacotherapy',
  'Enteric epididymitis',
  'vignette',
  'A 67-year-old man who has sex with women only has 3 days of gradual scrotal pain, fever, and dysuria. Ultrasound shows epididymitis and normal testicular flow. He has no cephalosporin or sulfa allergy. Prostate examination is very tender.',
  'Which of the following is the most appropriate empiric coverage?',
  '{"options":["Ceftriaxone plus doxycycline for 7 days only","A fluoroquinolone or trimethoprim-sulfamethoxazole aimed at enteric organisms, after STI risk is considered","Penicillin for syphilis","Observation","Surgical detorsion"],"blueprintSystem":"genitourinary","taskCategory":"pharmacotherapy","blueprintTopic":"Enteric epididymitis","kind":"vignette"}',
  'A fluoroquinolone or trimethoprim-sulfamethoxazole aimed at enteric organisms, after STI risk is considered',
  'A fluoroquinolone or trimethoprim-sulfamethoxazole aimed at enteric organisms, after STI risk is considered is correct. Epididymitis in older men is usually enteric, often with prostatitis, so coverage targets gram-negative bowel flora. STI therapy alone is the regimen for younger sexually active patients. Incorrect alternatives: Penicillin, observation, and detorsion do not treat this infection. The young-adult STI pair is the wrong age match when enteric organisms predominate.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Workowski KA et al. Sexually Transmitted Infections Treatment Guidelines, 2021. MMWR Recomm Rep 2021","url":"https://www.cdc.gov/std/treatment-guidelines/epididymitis.htm"}]'::jsonb,
  'generated',
  'f1984a6060780ca02ed9d8b9f71a34f80ee19eb5bd4874eaf18a5e234fbb3335',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
