  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'intervention',
  'Paraphimosis',
  'vignette',
  'A 70-year-old man with an indwelling catheter has a swollen, painful glans and a tight ring of foreskin behind the corona. The glans is dusky. He had the foreskin retracted for cleaning and it was not replaced.',
  'Which of the following is the most appropriate immediate action?',
  '{"options":["Elective circumcision in 3 months with no reduction today","Manual reduction of the foreskin after compression, with urgent dorsal slit if reduction fails","Topical clotrimazole","Oral doxycycline","Observation because a retracted foreskin is the same as phimosis"],"blueprintSystem":"genitourinary","taskCategory":"intervention","blueprintTopic":"Paraphimosis","kind":"vignette"}',
  'Manual reduction of the foreskin after compression, with urgent dorsal slit if reduction fails',
  'Manual reduction of the foreskin after compression, with urgent dorsal slit if reduction fails is correct. Paraphimosis is a trapped foreskin that can strangulate the glans. Reduce it now. Phimosis is a foreskin that will not retract and is not this emergency. Incorrect alternatives: Waiting months, antifungal cream, and antibiotics do not restore blood flow.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '865eaae25d6ffd43f71b002afc90d15b795036ffa8bb3b14b90ffcfd91442960',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
