  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  5,
  'genitourinary',
  'genitourinary',
  'pharmacotherapy',
  'Ischemic priapism',
  'vignette',
  'A 28-year-old man has a painful erection for 6 hours after injecting alprostadil. The corpora are rigid and tender. Aspiration of the corpus returns dark blood.',
  'Which of the following is the most appropriate next treatment?',
  '{"options":["Ice packs and discharge with a 24-hour recheck","Corporal aspiration and irrigation, then intracavernosal phenylephrine if needed","Intracavernosal alprostadil","Oral sildenafil","Observation because drug-induced erections always resolve by 8 hours"],"blueprintSystem":"genitourinary","taskCategory":"pharmacotherapy","blueprintTopic":"Ischemic priapism","kind":"vignette"}',
  'Corporal aspiration and irrigation, then intracavernosal phenylephrine if needed',
  'Corporal aspiration and irrigation, then intracavernosal phenylephrine if needed is correct. A painful, prolonged erection with dark corporal blood is ischemic priapism. Aspiration and a sympathomimetic are the emergency treatment. More vasodilator or a PDE-5 inhibitor worsens it. Incorrect alternatives: Ice and waiting past several hours risk permanent erectile tissue injury.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'd026c3a3a7d2a3e7d17e0176a508c9f4255c9e2061175cd79be0ce61ed9d124f',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
