  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'diagnosis',
  'Varicocele that does not decompress',
  'vignette',
  'A 46-year-old man has a new right-sided scrotal ''bag of worms'' that does not get smaller when he lies down. The left side is normal. He has no fever.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Reassurance that a right varicocele never needs imaging","Imaging of the retroperitoneum for a venous-obstructing mass","Ceftriaxone and doxycycline","Immediate scrotal exploration for torsion","A trial of scrotal support for 6 months before any test"],"blueprintSystem":"genitourinary","taskCategory":"diagnosis","blueprintTopic":"Varicocele that does not decompress","kind":"vignette"}',
  'Imaging of the retroperitoneum for a venous-obstructing mass',
  'Imaging of the retroperitoneum for a venous-obstructing mass is correct. An isolated right varicocele, or one that does not collapse when supine, can be caused by venous obstruction from a retroperitoneal mass. That pattern is imaged. Incorrect alternatives: Antibiotics, torsion surgery, and a long delay do not look for obstruction. A classic left varicocele that decompresses is the benign pattern, and this is not that pattern.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '383c7653f446b470a5c4166e31b37203d8fa5ebc191e70b584cd1c0c26229440',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
