  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  3,
  'genitourinary',
  'genitourinary',
  'prevention',
  'Cryptorchidism timing',
  'vignette',
  'A 9-month-old boy has a right testis that has never been felt in the scrotum. It is palpable in the inguinal canal. He was born at term. The left testis is descended. A parent asks about waiting until school age.',
  'Which of the following is the most appropriate plan?',
  '{"options":["Hormone injections as first-line therapy and surgery only after puberty","Orchiopexy well before 18 months of age","Observation until age 8 because descent is still likely","Removal of the normal left testis","Antibiotics for 10 days"],"blueprintSystem":"genitourinary","taskCategory":"prevention","blueprintTopic":"Cryptorchidism timing","kind":"vignette"}',
  'Orchiopexy well before 18 months of age',
  'Orchiopexy well before 18 months of age is correct. A testis still undescended at this age is unlikely to arrive on its own. Orchiopexy is done in infancy, generally by 18 months, to protect fertility and allow later examination for cancer risk. Incorrect alternatives: Waiting until school age, hormones as the standard first step, removing the normal testis, and antibiotics are not the plan.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '9ea9c6ca086b9990c9ddaae81e586ae8d319909e973c8f43ade152f49cbe33a5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'pharmacotherapy',
  'BPH and urinary retention',
  'vignette',
  'A 69-year-old man has a first episode of acute urinary retention. A catheter drains 900 mL. He has a large prostate on examination and no fever. He can be sent home with the catheter.',
  'Which of the following is the most appropriate medication to start before a voiding trial?',
  '{"options":["Oxybutynin","An alpha blocker","Nitrofurantoin for 14 days","Finasteride as the only drug, with the voiding trial tomorrow morning","A PDE-5 inhibitor as emergency decompression"],"blueprintSystem":"genitourinary","taskCategory":"pharmacotherapy","blueprintTopic":"BPH and urinary retention","kind":"vignette"}',
  'An alpha blocker',
  'An alpha blocker is correct. An alpha blocker started at the time of catheter drainage improves the chance of a successful voiding trial. It works within days. Incorrect alternatives: An anticholinergic can worsen retention. Finasteride shrinks the prostate over months and is not the drug that gets him through this week. Antibiotics and a PDE-5 inhibitor do not empty the bladder.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Sandhu JS et al. Management of Lower Urinary Tract Symptoms Attributed to Benign Prostatic Hyperplasia: AUA Guideline Amendment 2023. J Urol 2023","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000003698"}]'::jsonb,
  'generated',
  '2177fc2499cf37683036f03ee2237f3421f5a5cd3056b9acc3a2c047363862b3',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  5,
  'genitourinary',
  'genitourinary',
  'pharmacotherapy',
  'Overactive bladder with a high residual',
  'vignette',
  'A 74-year-old man with frequency and urgency has a post-void residual of 280 mL and a weak stream. A clinician wants to start solifenacin alone.',
  'Which of the following is the most appropriate concern about that plan?',
  '{"options":["Solifenacin is first-line and the residual can be ignored","An antimuscarinic alone may precipitate retention when the residual is already high; treat the outlet and reassess","He needs antibiotics for 6 weeks instead","Mirabegron is contraindicated in every man with urgency","The residual proves interstitial cystitis"],"blueprintSystem":"genitourinary","taskCategory":"pharmacotherapy","blueprintTopic":"Overactive bladder with a high residual","kind":"vignette"}',
  'An antimuscarinic alone may precipitate retention when the residual is already high; treat the outlet and reassess',
  'An antimuscarinic alone may precipitate retention when the residual is already high; treat the outlet and reassess is correct. Urgency with a large residual and a weak stream is often bladder-outlet obstruction. Blocking detrusor contraction before addressing the outlet can cause retention. Incorrect alternatives: Ignoring 280 mL, a long antibiotic course, a blanket ban on beta-3 agonists, and an interstitial-cystitis label do not match this examination.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Sandhu JS et al. Management of Lower Urinary Tract Symptoms Attributed to Benign Prostatic Hyperplasia: AUA Guideline Amendment 2023. J Urol 2023","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000003698"}]'::jsonb,
  'generated',
  '4193b314b5679113ee2e5db211e6f85b7cd7d7ea70faea29c78deb484602977e',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
