  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  3,
  'genitourinary',
  'genitourinary',
  'prevention',
  'PSA shared decision at 62',
  'vignette',
  'A 62-year-old man with no urinary symptoms asks for ''the prostate blood test'' at a physical. He has not heard the tradeoffs. He is otherwise well and expects to live many more years.',
  'Which of the following is the most appropriate approach?',
  '{"options":["Draw a PSA today without discussion because he is over 50","Discuss benefits and harms and order PSA only if he wants screening","Tell him screening is mandatory at 62","Tell him no man should ever discuss PSA","Biopsy the prostate first"],"blueprintSystem":"genitourinary","taskCategory":"prevention","blueprintTopic":"PSA shared decision at 62","kind":"vignette"}',
  'Discuss benefits and harms and order PSA only if he wants screening',
  'Discuss benefits and harms and order PSA only if he wants screening is correct. For men 55 to 69, USPSTF recommends an individual decision after a discussion of a small mortality benefit versus false positives, biopsy, and treatment harms. Do not screen someone who does not want it. Incorrect alternatives: Mandatory testing, a refusal to discuss it, and a biopsy before any conversation are not the recommendation.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"US Preventive Services Task Force. Screening for Prostate Cancer: US Preventive Services Task Force Recommendation Statement. JAMA 2018","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/prostate-cancer-screening"}]'::jsonb,
  'generated',
  'a62ef96c77eba435a3d0b4b7b7d8f9f8ecc3a03cb9bfb5784eeaf857ea645813',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'prevention',
  'PSA after 70',
  'vignette',
  'A 76-year-old man with severe heart failure and a limited life expectancy asks for a routine PSA. He has no symptoms and had a normal PSA 2 years ago. He wants whatever is ''recommended for everyone his age.''',
  'Which of the following is the most appropriate recommendation?',
  '{"options":["Annual PSA is recommended for all men over 70","Do not perform routine PSA screening","Go directly to prostate biopsy","Start finasteride to lower the PSA","Order a PSA every 3 months"],"blueprintSystem":"genitourinary","taskCategory":"prevention","blueprintTopic":"PSA after 70","kind":"vignette"}',
  'Do not perform routine PSA screening',
  'Do not perform routine PSA screening is correct. USPSTF recommends against PSA screening at age 70 and older because harms outweigh benefits, especially when life expectancy is limited. Incorrect alternatives: Annual or quarterly testing, empiric finasteride, and an upfront biopsy are not screening recommendations for him.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"US Preventive Services Task Force. Screening for Prostate Cancer: US Preventive Services Task Force Recommendation Statement. JAMA 2018","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/prostate-cancer-screening"}]'::jsonb,
  'generated',
  '8f7f94afd7caa764b12702ac8ca522a9d4aec2202530f5b63dbefbcb97ea39c4',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
