  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  4,
  'genitourinary',
  'genitourinary',
  'diagnosis',
  'Gross hematuria is not microhematuria',
  'vignette',
  'A 66-year-old man on apixaban for atrial fibrillation passed visible blood in the urine once yesterday. The urine is now yellow. CT was ordered by a colleague ''only if he is not anticoagulated.''',
  'Which of the following is the most appropriate statement?',
  '{"options":["Visible blood on an anticoagulant needs no urologic evaluation","Gross hematuria is evaluated, including cystoscopy and upper-tract imaging, whether or not he takes an anticoagulant","A single dipstick in 6 months is enough","Stop apixaban forever and skip cystoscopy","Treat with nitrofurantoin"],"blueprintSystem":"genitourinary","taskCategory":"diagnosis","blueprintTopic":"Gross hematuria is not microhematuria","kind":"vignette"}',
  'Gross hematuria is evaluated, including cystoscopy and upper-tract imaging, whether or not he takes an anticoagulant',
  'Gross hematuria is evaluated, including cystoscopy and upper-tract imaging, whether or not he takes an anticoagulant is correct. Anticoagulation may unmask a tumor; it does not explain the blood away. Gross hematuria is a high-risk feature and is not followed like low-risk microhematuria. Incorrect alternatives: A delayed dipstick, permanently stopping anticoagulation without a workup, and an antibiotic do not find a bladder tumor.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"Barocas DA et al. Updates to Microhematuria: AUA/SUFU Guideline (2025). J Urol 2025","url":"https://www.auajournals.org/doi/10.1097/JU.0000000000004490"}]'::jsonb,
  'generated',
  '8f9e2ca8ae084af57e7798c17a71abd8d661f1151b72b48350bbec62be556b08',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
