  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'genitourinary',
  3,
  'genitourinary',
  'genitourinary',
  'diagnosis',
  'Stress versus urge incontinence',
  'vignette',
  'A 58-year-old woman leaks a small amount of urine when she coughs or lifts. She does not have urgency, nocturia, or dysuria. Pelvic examination shows no fistula. Post-void residual is 20 mL.',
  'Which of the following is the most appropriate initial treatment?',
  '{"options":["Oxybutynin","Pelvic floor muscle training","An indwelling catheter","Daily nitrofurantoin","Tamsulosin"],"blueprintSystem":"genitourinary","taskCategory":"diagnosis","blueprintTopic":"Stress versus urge incontinence","kind":"vignette"}',
  'Pelvic floor muscle training',
  'Pelvic floor muscle training is correct. Leakage with cough and lift, without urgency, is stress incontinence. Pelvic floor training is the initial treatment. Incorrect alternatives: An antimuscarinic treats urge incontinence. A catheter, prophylaxis, and an alpha blocker do not retrain the sphincter mechanism.',
  '["pance","PANCE-2025","genitourinary","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '834ff65dc9273c5c812af8823871142f79942179fad1b8301b83f00514bfd41c',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  5,
  'renal',
  'renal',
  'pharmacotherapy',
  'SGLT2 inhibitor eGFR threshold',
  'vignette',
  'A 63-year-old man with type 2 diabetes has an eGFR of 28 mL/min/1.73 m2 and a urine albumin-creatinine ratio of 480 mg/g. He takes losartan. Hemoglobin A1c is 7.4%. Potassium is 4.4 mEq/L. A colleague says an SGLT2 inhibitor cannot be started below an eGFR of 45.',
  'Which of the following is the most appropriate medication change?',
  '{"options":["Do not start an SGLT2 inhibitor until the eGFR is above 45","Start an SGLT2 inhibitor with proven kidney benefit","Stop losartan before any SGLT2 inhibitor","Start a sulfonylurea instead because the eGFR is under 30","Start dual ACE-inhibitor and ARB therapy"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"SGLT2 inhibitor eGFR threshold","kind":"vignette"}',
  'Start an SGLT2 inhibitor with proven kidney benefit',
  'Start an SGLT2 inhibitor with proven kidney benefit is correct. KDIGO 2024 and the ADA 2026 standards recommend an SGLT2 inhibitor for type 2 diabetes and CKD when the eGFR is at least 20, not 45. Kidney benefit is independent of the glucose effect. Incorrect alternatives: Waiting for an eGFR of 45 withholds a drug that slows progression. Stopping the ARB, adding a second renin-angiotensin drug, or substituting a sulfonylurea misses the kidney indication.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"},{"label":"American Diabetes Association. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://doi.org/10.2337/dc26-s011"}]'::jsonb,
  'generated',
  'd15a923e1ea4d0e0842e6ed2400ca17c966524a8a369186699f56111d76ccf9a',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  5,
  'renal',
  'renal',
  'pharmacotherapy',
  'Do not stop an SGLT2 inhibitor for the expected dip',
  'vignette',
  'A 70-year-old woman with type 2 diabetes and albuminuria started dapagliflozin 2 weeks ago. Her eGFR fell from 48 to 42 mL/min/1.73 m2. She is eating normally, potassium is 4.6 mEq/L, and she has no volume depletion. A covering clinician wants it stopped because ''the kidneys worsened.''',
  'Which of the following is the most appropriate action?',
  '{"options":["Stop the SGLT2 inhibitor permanently","Continue it; an early eGFR dip is expected and is not a reason to stop","Add an NSAID for the creatinine change","Switch to glyburide","Start dialysis planning because the eGFR fell by 6"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"Do not stop an SGLT2 inhibitor for the expected dip","kind":"vignette"}',
  'Continue it; an early eGFR dip is expected and is not a reason to stop',
  'Continue it; an early eGFR dip is expected and is not a reason to stop is correct. KDIGO notes that the early hemodynamic drop in eGFR after an SGLT2 inhibitor is generally not a reason to discontinue the drug, and monitoring frequency does not have to change just because it was started. Incorrect alternatives: Permanent cessation, an NSAID, a sulfonylurea swap, and dialysis planning treat a hemodynamic dip as kidney failure.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  '085251f3c0df101b3e830e4931f735bef24032431488a43554539db5f31e376b',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  5,
  'renal',
  'renal',
  'pharmacotherapy',
  'Continue SGLT2 inhibitor below an eGFR of 20',
  'vignette',
  'A 74-year-old man with type 2 diabetes has been stable on empagliflozin. His eGFR has drifted from 24 to 18 mL/min/1.73 m2. He is not on dialysis, he tolerates the drug, and he has no ketosis. He is about to undergo an elective colonoscopy with a full bowel prep next month.',
  'Which of the following is the most appropriate plan for the SGLT2 inhibitor?',
  '{"options":["Stop it forever because the eGFR is now under 20","Continue it day to day, and hold it for the prolonged fast around the procedure","Double the dose because the eGFR is lower","Replace it with metformin at an eGFR of 18","Add a second SGLT2 inhibitor"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"Continue SGLT2 inhibitor below an eGFR of 20","kind":"vignette"}',
  'Continue it day to day, and hold it for the prolonged fast around the procedure',
  'Continue it day to day, and hold it for the prolonged fast around the procedure is correct. Once started, an SGLT2 inhibitor may be continued if the eGFR falls below 20, until kidney replacement or intolerance. It is held for prolonged fasting, surgery, or critical illness because of ketosis risk. Incorrect alternatives: Stopping forever at an eGFR of 18, doubling the dose, adding metformin below 30, or stacking two agents are not the recommendations.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"},{"label":"American Diabetes Association. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://doi.org/10.2337/dc26-s011"}]'::jsonb,
  'generated',
  '996615592e0a92528cb8fc75fc1ba583acf1a29e9ecd574f433c54733e9e8ff2',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'pharmacotherapy',
  'ACE inhibitor creatinine rise',
  'vignette',
  'A 58-year-old man with diabetes and albuminuria started lisinopril 3 weeks ago. Creatinine rose from 1.2 to 1.4 mg/dL (about 17%). Potassium is 4.7 mEq/L and blood pressure is 128/76 mm Hg. He is volume replete.',
  'Which of the following is the most appropriate action?',
  '{"options":["Stop lisinopril because any creatinine rise is toxicity","Continue lisinopril; a rise under 30% is acceptable","Add losartan to the lisinopril","Start spironolactone today without a potassium plan","Replace the ACE inhibitor with ibuprofen"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"ACE inhibitor creatinine rise","kind":"vignette"}',
  'Continue lisinopril; a rise under 30% is acceptable',
  'Continue lisinopril; a rise under 30% is acceptable is correct. KDIGO says to continue ACE-inhibitor or ARB therapy unless creatinine rises by more than 30% within 4 weeks. A 17% rise with a safe potassium is the expected hemodynamic effect. Incorrect alternatives: Stopping at 17%, combining ACE inhibitor with ARB, adding a mineralocorticoid antagonist without a potassium check, and substituting an NSAID are harmful turns.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  '8bbd7d3f80a6bbd113413f90c26e69a4f4398cb0aeedce7237f42359f8c64195',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  5,
  'renal',
  'renal',
  'pharmacotherapy',
  'Stop the ACE inhibitor when the rise exceeds 30%',
  'vignette',
  'A 66-year-old woman started ramipril 2 weeks ago for proteinuric CKD. Creatinine rose from 1.5 to 2.2 mg/dL (about 47%). Potassium is 5.6 mEq/L. She has been taking ibuprofen for knee pain.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Continue ramipril and add ibuprofen standing doses","Hold the ACE inhibitor, stop the NSAID, and reassess volume and renal artery perfusion","Add a second ACE inhibitor","Start metformin","Ignore the change until the next annual lab"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"Stop the ACE inhibitor when the rise exceeds 30%","kind":"vignette"}',
  'Hold the ACE inhibitor, stop the NSAID, and reassess volume and renal artery perfusion',
  'Hold the ACE inhibitor, stop the NSAID, and reassess volume and renal artery perfusion is correct. A creatinine rise above 30% is a reason to hold the renin-angiotensin drug and look for volume depletion, NSAID use, or bilateral renal-artery stenosis. The potassium of 5.6 reinforces that hold. Incorrect alternatives: Continuing through a 47% rise, stacking ACE inhibitors, starting metformin in this setting, and waiting a year leave a reversible injury in place.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  'e9b0237c8877a601dd008d746ebba219c370caa828744f8d95aae08e36c78233',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'pharmacotherapy',
  'Metformin at an eGFR of 38',
  'vignette',
  'A 67-year-old woman with type 2 diabetes takes metformin 1000 mg twice daily. The eGFR is now 38 mL/min/1.73 m2. She has no acidosis, hypoxia, or decompensated heart failure. Hemoglobin A1c is 7.1%.',
  'Which of the following is the most appropriate metformin plan?',
  '{"options":["Continue 2000 mg daily because lactic acidosis is rare","Reduce the total daily dose to 1000 mg and monitor kidney function","Stop metformin and start glyburide","Increase metformin because the eGFR fell","Stop all glucose-lowering drugs"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"Metformin at an eGFR of 38","kind":"vignette"}',
  'Reduce the total daily dose to 1000 mg and monitor kidney function',
  'Reduce the total daily dose to 1000 mg and monitor kidney function is correct. At an eGFR of 30 to 44, metformin is not started, and if it is already in use the dose is reduced, commonly to 1000 mg daily, with closer monitoring. It is stopped below 30. Incorrect alternatives: Full dose at an eGFR of 38, a sulfonylurea substitution as the only option, a dose increase, and stopping all therapy overshoot the recommendation.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"American Diabetes Association. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://doi.org/10.2337/dc26-s011"}]'::jsonb,
  'generated',
  'f1104296f4dcffd5c0d0d1ba28d0527d8db7dad8eb294af46c94223d35c6ec50',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  5,
  'renal',
  'renal',
  'pharmacotherapy',
  'Nonsteroidal MRA and potassium',
  'vignette',
  'A 60-year-old man with type 2 diabetes, eGFR 42 mL/min/1.73 m2, and urine albumin-creatinine ratio 600 mg/g is on lisinopril and dapagliflozin. Potassium has been 4.3 and 4.5 mEq/L. A colleague suggests finerenone.',
  'Which of the following is the most appropriate use of finerenone here?',
  '{"options":["Add it, and recheck potassium, because he is already on an ACE inhibitor and an SGLT2 inhibitor with a normal potassium","Do not use it unless the potassium is above 5.5","Stop the SGLT2 inhibitor before any finerenone can be considered","Use it as a substitute for the ACE inhibitor","Start it at an eGFR of 12"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"Nonsteroidal MRA and potassium","kind":"vignette"}',
  'Add it, and recheck potassium, because he is already on an ACE inhibitor and an SGLT2 inhibitor with a normal potassium',
  'Add it, and recheck potassium, because he is already on an ACE inhibitor and an SGLT2 inhibitor with a normal potassium is correct. KDIGO allows a nonsteroidal mineralocorticoid antagonist to be added to a renin-angiotensin inhibitor and an SGLT2 inhibitor in type 2 diabetes with CKD when potassium is consistently normal, with potassium checked after the start. Incorrect alternatives: Waiting until potassium is already high, stopping the SGLT2 inhibitor, replacing the ACE inhibitor, or starting at an eGFR of 12 are not the selection rules.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
