  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'pharmacotherapy',
  'Alkali for CKD acidosis',
  'vignette',
  'A 72-year-old man with CKD stage G4 has a venous bicarbonate of 16 mEq/L on two checks. He is euvolemic, potassium is 4.2 mEq/L, and he is not having diarrhea.',
  'Which of the following is the most appropriate treatment of the acidosis?',
  '{"options":["No treatment unless bicarbonate is under 10","Oral alkali to raise bicarbonate, with monitoring so it is not driven too high","Acetazolamide","A high-protein diet","Daily normal-saline boluses at home"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"Alkali for CKD acidosis","kind":"vignette"}',
  'Oral alkali to raise bicarbonate, with monitoring so it is not driven too high',
  'Oral alkali to raise bicarbonate, with monitoring so it is not driven too high is correct. KDIGO suggests treating metabolic acidosis in adults with CKD when bicarbonate is under about 18 mmol/L, and monitoring so treatment does not overshoot. Incorrect alternatives: Waiting for a bicarbonate of 10 leaves chronic bone and muscle effects. Acetazolamide, extra protein, and saline boluses worsen acid-base or volume balance.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  'f40010c8c9cb9ff4285668b94dad089911e0f1ac7f74ac4cf1eb25652bc51c03',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'diagnosis',
  'Prerenal azotemia versus ATN',
  'vignette',
  'A 68-year-old man has 2 days of vomiting. Creatinine rose from 0.9 to 2.1 mg/dL. Blood pressure is 92/60 mm Hg. Urine sodium is 8 mEq/L, fractional excretion of sodium is 0.4%, and the sediment has hyaline casts only.',
  'Which of the following is the most likely mechanism?',
  '{"options":["Acute tubular necrosis","Prerenal azotemia from volume loss","Postrenal obstruction","Acute interstitial nephritis","Cholesterol emboli"],"blueprintSystem":"renal","taskCategory":"diagnosis","blueprintTopic":"Prerenal azotemia versus ATN","kind":"vignette"}',
  'Prerenal azotemia from volume loss',
  'Prerenal azotemia from volume loss is correct. A bland sediment, urine sodium under 20, and fractional excretion of sodium under 1% in a volume-depleted patient is prerenal physiology. The tubules are still conserving sodium. Incorrect alternatives: ATN has muddy-brown casts and a fractional excretion of sodium usually above 2%. Obstruction needs imaging clues. Interstitial nephritis has white cells, white-cell casts, and often a drug latency. Cholesterol emboli follow a procedure and show livedo or eosinophilia.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  '82f1f429f893b0d91597a88416394753f093eab27b52fa9aebb18c18f17c9e42',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
