  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'diagnosis',
  'Acute tubular necrosis sediment',
  'vignette',
  'A 75-year-old man was hypotensive during a gastrointestinal bleed yesterday. Today creatinine is 3.4 mg/dL, urine sodium is 46 mEq/L, and the sediment shows muddy-brown granular casts. He is now normotensive after transfusion.',
  'Which of the following is the most likely diagnosis?',
  '{"options":["Prerenal azotemia that still needs more saline","Acute tubular necrosis","Bladder outlet obstruction","Minimal-change disease","Isolated prerenal state from heart failure"],"blueprintSystem":"renal","taskCategory":"diagnosis","blueprintTopic":"Acute tubular necrosis sediment","kind":"vignette"}',
  'Acute tubular necrosis',
  'Acute tubular necrosis is correct. Muddy-brown casts and a high urine sodium after a documented ischemic insult are the sediment of tubular injury, not ongoing prerenal conservation. Incorrect alternatives: More saline after he is resuscitated does not reverse established tubular injury. Obstruction, minimal-change disease, and heart-failure physiology have different examinations and sediments.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  'd7a2649d16794cde11169cb3a8d51aa0404c96d6fbd1d1f4b5bf2df0fda245c5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  5,
  'renal',
  'renal',
  'diagnosis',
  'Acute interstitial nephritis',
  'vignette',
  'A 62-year-old woman started pantoprazole 10 days ago and now has a creatinine of 2.8 mg/dL from a baseline of 0.8. She has a maculopapular rash and eosinophilia. Urine shows white cells and white-cell casts. Antibiotics were not given.',
  'Which of the following is the most appropriate first action?',
  '{"options":["Increase the pantoprazole dose","Stop pantoprazole","Start empiric cyclophosphamide","Begin dialysis immediately because of the rash","Add an NSAID for the rash"],"blueprintSystem":"renal","taskCategory":"diagnosis","blueprintTopic":"Acute interstitial nephritis","kind":"vignette"}',
  'Stop pantoprazole',
  'Stop pantoprazole is correct. A proton-pump inhibitor is a classic cause of acute interstitial nephritis. The rash, eosinophilia, white cells, and white-cell casts after a new drug point to that diagnosis, and the drug is stopped. Incorrect alternatives: Raising the dose, adding an NSAID, or jumping to cyclophosphamide or dialysis before withdrawal treats the wrong step.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  'c2f9469e3f416fc011af0eded2ec7f5cecae1539b6dd28cfdd5d60a9530a8b88',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'diagnosis',
  'Postrenal failure in a man',
  'vignette',
  'A 80-year-old man has lower abdominal pain and no urine for 14 hours. Creatinine is 3.1 mg/dL. A bladder scan shows 700 mL. Kidneys were normal 2 months ago.',
  'Which of the following is the most appropriate next step?',
  '{"options":["High-dose furosemide","Urethral catheter drainage","Oral sodium bicarbonate only","Renal biopsy","Start an SGLT2 inhibitor"],"blueprintSystem":"renal","taskCategory":"diagnosis","blueprintTopic":"Postrenal failure in a man","kind":"vignette"}',
  'Urethral catheter drainage',
  'Urethral catheter drainage is correct. Anuria with a full bladder is postrenal obstruction until drained. Relief of the outlet comes before diuretics or disease-modifying CKD drugs. Incorrect alternatives: Furosemide, alkali, biopsy, and an SGLT2 inhibitor do not empty an obstructed bladder.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  '72696ac90a656ba2a30332f52d7e702ee0d8ca3e02d5303aa8447a4d1261075e',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'diagnosis',
  'CKD is three months, not one lab',
  'vignette',
  'A 55-year-old man has a creatinine of 1.6 mg/dL today. Six weeks ago it was 0.9 during an illness, and he has no older results. Urine albumin-creatinine ratio is 12 mg/g. He feels well now.',
  'Which of the following is the most appropriate label today?',
  '{"options":["CKD stage G3a A1, start an SGLT2 inhibitor today","Possible acute or subacute kidney change; repeat the creatinine before diagnosing CKD","End-stage kidney disease","Nephrotic syndrome","No follow-up is needed"],"blueprintSystem":"renal","taskCategory":"diagnosis","blueprintTopic":"CKD is three months, not one lab","kind":"vignette"}',
  'Possible acute or subacute kidney change; repeat the creatinine before diagnosing CKD',
  'Possible acute or subacute kidney change; repeat the creatinine before diagnosing CKD is correct. CKD requires kidney abnormalities for at least 3 months. One elevated creatinine after a recent normal value is not yet CKD, and albuminuria is absent. Incorrect alternatives: Staging him G3 and starting long-term therapy, calling it end-stage or nephrotic disease, or dropping follow-up all misread a single lab.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  'e7063119dc4de54ac8b9ee561ca8abf79b1336458885d948853e82df7144d2a4',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
