  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'labs',
  'Albuminuria category changes the risk',
  'vignette',
  'Two patients both have an eGFR of 52 mL/min/1.73 m2. One has a urine albumin-creatinine ratio of 18 mg/g. The other has a ratio of 420 mg/g. Both have diabetes.',
  'Which of the following is the most important difference?',
  '{"options":["They have the same KDIGO risk because the eGFR matches","The patient with the ratio of 420 is in a higher albuminuria category and a higher risk cell","Only the patient with the ratio of 18 needs an ACE inhibitor","Albuminuria is ignored once the eGFR is above 45","The ratio of 420 is normal"],"blueprintSystem":"renal","taskCategory":"labs","blueprintTopic":"Albuminuria category changes the risk","kind":"vignette"}',
  'The patient with the ratio of 420 is in a higher albuminuria category and a higher risk cell',
  'The patient with the ratio of 420 is in a higher albuminuria category and a higher risk cell is correct. KDIGO classifies CKD by cause, GFR category, and albuminuria category. An eGFR of 52 is G3a, but 420 mg/g is A3 and 18 mg/g is A1, so the risk is not the same. Incorrect alternatives: Matching eGFR does not match risk. The higher albuminuria, not the lower one, is the ACE-inhibitor indication. A ratio of 420 is not normal.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  'a266b2b40d612b998e475b7c31df872956b8d294bb017d857c84fb9ad3193fce',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  5,
  'renal',
  'renal',
  'pharmacotherapy',
  'NSAID and ACE inhibitor and diuretic',
  'vignette',
  'A 77-year-old woman on lisinopril and chlorthalidone starts ibuprofen three times daily for osteoarthritis. Three days later creatinine has doubled and potassium is 5.8 mEq/L. She is still making urine.',
  'Which of the following best explains the injury?',
  '{"options":["A single-drug allergy to chlorthalidone","Loss of prostaglandin dilation of the afferent arteriole on top of efferent dilation blockade and volume loss","Cholesterol emboli from the ibuprofen tablet","Minimal-change disease from the diuretic","An expected 10% creatinine change that should be ignored"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"NSAID and ACE inhibitor and diuretic","kind":"vignette"}',
  'Loss of prostaglandin dilation of the afferent arteriole on top of efferent dilation blockade and volume loss',
  'Loss of prostaglandin dilation of the afferent arteriole on top of efferent dilation blockade and volume loss is correct. The ''triple whammy'' is an NSAID plus a renin-angiotensin blocker plus a diuretic. The NSAID constricts the afferent arteriole while the ACE inhibitor dilates the efferent arteriole and the diuretic contracts volume. Incorrect alternatives: This is not an allergy, an embolus, or minimal-change disease, and a doubled creatinine is not a trivial dip.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  '45724db368b8a1bb1a183317b63cb963fabeff6f5b50a33533de2de533c58f3b',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'intervention',
  'Indications for urgent dialysis',
  'vignette',
  'A 59-year-old man with CKD has a potassium of 7.1 mEq/L, peaked T waves, and a widening QRS. Calcium gluconate and insulin-glucose have been given. He is anuric and potassium is still 6.8 mEq/L an hour later. Bicarbonate is 12 mEq/L and he is somnolent.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Another dose of ibuprofen","Urgent dialysis","Oral kayexalate as the only further treatment","Observation overnight","A 2-liter saline bolus"],"blueprintSystem":"renal","taskCategory":"intervention","blueprintTopic":"Indications for urgent dialysis","kind":"vignette"}',
  'Urgent dialysis',
  'Urgent dialysis is correct. Refractory hyperkalemia with QRS widening, anuria, acidosis, and altered mentation is an indication for urgent kidney replacement. Temporizing drugs have already been used. Incorrect alternatives: An NSAID, saline in an anuric patient, overnight observation, and a resin as the only step do not treat membrane toxicity that is not resolving.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  '7c484ae5db977e5cbcafb4af72d53ff62ea3aa10d7cdbaf8c83f9a09f59fcc20',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'pharmacotherapy',
  'Hyperkalemia membrane stabilization',
  'vignette',
  'A 70-year-old man with CKD has a potassium of 6.9 mEq/L. The ECG shows sine-wave QRS widening. He has intravenous access.',
  'Which of the following is the most appropriate immediate drug?',
  '{"options":["Oral sodium polystyrene sulfonate","Intravenous calcium","Furosemide by mouth","Hemodialysis scheduled for tomorrow morning","A beta blocker"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"Hyperkalemia membrane stabilization","kind":"vignette"}',
  'Intravenous calcium',
  'Intravenous calcium is correct. Calcium stabilizes the cardiac membrane within minutes when the ECG is already wide. It does not lower the potassium, so shifting and removal follow, but it is the first drug. Incorrect alternatives: A resin, oral furosemide, and next-day dialysis are too slow for a sine wave. A beta blocker does not protect the membrane.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  '72e93d093a8fbe9db79a594a2c0be1aa86dd2c6d78542191a6c227ec03446ff3',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'diagnosis',
  'Rhabdomyolysis kidney injury',
  'vignette',
  'A 28-year-old man was found after lying on a floor for 12 hours. The urine is dark and dipstick-positive for blood, but microscopy shows no red cells. Creatine kinase is 48,000 U/L and creatinine is 2.4 mg/dL. Potassium is 5.9 mEq/L.',
  'Which of the following is the most appropriate initial fluid plan?',
  '{"options":["Fluid restriction","Vigorous isotonic saline, with monitoring of urine output and potassium","A loop diuretic before any fluid","An NSAID for muscle pain","Immediate renal biopsy"],"blueprintSystem":"renal","taskCategory":"diagnosis","blueprintTopic":"Rhabdomyolysis kidney injury","kind":"vignette"}',
  'Vigorous isotonic saline, with monitoring of urine output and potassium',
  'Vigorous isotonic saline, with monitoring of urine output and potassium is correct. Dipstick blood without red cells plus a very high creatine kinase is rhabdomyolysis. Early volume resuscitation limits pigment injury. Potassium is already high, so fluids are given with a plan for that. Incorrect alternatives: Restriction, a diuretic first, an NSAID, and a biopsy delay or worsen the injury.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  'c70b441a32f9664485d9b692bed512fcd2b5d85cbfc49e88ca78190d60391c7e',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  3,
  'renal',
  'renal',
  'diagnosis',
  'Nephrotic edema mechanism',
  'vignette',
  'A 24-year-old man has periorbital and leg edema. Urine protein is 6 g/day, albumin is 2.1 g/dL, and cholesterol is 340 mg/dL. Creatinine is 0.8 mg/dL.',
  'Which of the following is the most likely urinary finding that defines this syndrome?',
  '{"options":["Muddy-brown casts","Protein excretion above 3.5 g/day","Red-cell casts as the defining feature","White-cell casts","A post-void residual over 400 mL"],"blueprintSystem":"renal","taskCategory":"diagnosis","blueprintTopic":"Nephrotic edema mechanism","kind":"vignette"}',
  'Protein excretion above 3.5 g/day',
  'Protein excretion above 3.5 g/day is correct. Nephrotic syndrome is heavy proteinuria, hypoalbuminemia, edema, and often hyperlipidemia. The defining urinary number is protein above about 3.5 g/day. Incorrect alternatives: Muddy-brown casts are tubular injury. Red-cell casts suggest glomerulonephritis. White-cell casts suggest interstitial nephritis or pyelonephritis. A residual is obstruction.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  '6683c7a63c366778846fd22b470298bfb59b4fb3a822517cbe123ed73d6fb6da',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
