  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'diagnosis',
  'Nephritic sediment',
  'vignette',
  'A 19-year-old man has tea-colored urine 2 weeks after a sore throat. Blood pressure is 162/98 mm Hg. Creatinine is 1.8 mg/dL. Urine shows red-cell casts and protein of 1.2 g/day.',
  'Which of the following syndromes best fits?',
  '{"options":["Nephrotic syndrome","Nephritic syndrome","Isolated prerenal azotemia","Chronic urinary retention","Myoglobinuria"],"blueprintSystem":"renal","taskCategory":"diagnosis","blueprintTopic":"Nephritic sediment","kind":"vignette"}',
  'Nephritic syndrome',
  'Nephritic syndrome is correct. Hypertension, a rising creatinine, cola urine, and red-cell casts with subnephrotic protein are the nephritic pattern, here in the window after pharyngitis. Incorrect alternatives: Nephrotic syndrome is heavier protein and edema without this active sediment. Prerenal labs, retention, and myoglobin do not produce red-cell casts.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  '8404020d9bc933341d2940c0e7a635b4af7a0bec45d78c75d8775aeb0c585f77',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
