  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'pharmacotherapy',
  'Contrast exposure and volume',
  'vignette',
  'A 73-year-old man with an eGFR of 32 mL/min/1.73 m2 needs a contrasted CT. He takes lisinopril. He is euvolemic and not in heart failure. A student asks for acetylcysteine because a blog called it protective.',
  'Which of the following is the most appropriate prevention step?',
  '{"options":["Oral acetylcysteine as the proven preventive drug","Isotonic volume expansion around the contrast exposure, and avoid other nephrotoxins that day","No precautions because contrast never affects the kidney","Start ibuprofen the morning of the scan","Dialysis for every patient with an eGFR under 45 after contrast"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"Contrast exposure and volume","kind":"vignette"}',
  'Isotonic volume expansion around the contrast exposure, and avoid other nephrotoxins that day',
  'Isotonic volume expansion around the contrast exposure, and avoid other nephrotoxins that day is correct. Volume expansion is the prevention step with the best support. Acetylcysteine has not been shown to prevent contrast-associated injury in large trials and is not the plan. Incorrect alternatives: Ignoring risk, adding an NSAID, and dialyzing every stage G3 patient are not appropriate.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  'e243843f6f19152eb4b99a0500d64f1e4e710470fcb95f1fe1ad2b7e2e7b7927',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
