  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  3,
  'renal',
  'renal',
  'diagnosis',
  'Horseshoe kidney infection risk',
  'vignette',
  'A 30-year-old woman has recurrent pyelonephritis. Ultrasound shows a horseshoe kidney with a stone in the isthmus. She is pregnant and afebrile today, and this visit is for counseling.',
  'Which of the following is the most appropriate counseling point?',
  '{"options":["A horseshoe kidney has no association with stones or infection","The abnormal drainage raises the risk of stones and infection, so new fever and flank pain need prompt evaluation","The kidney should be removed before any further pregnancy planning","Antibiotics are never used","The finding is a tumor until proved otherwise"],"blueprintSystem":"renal","taskCategory":"diagnosis","blueprintTopic":"Horseshoe kidney infection risk","kind":"vignette"}',
  'The abnormal drainage raises the risk of stones and infection, so new fever and flank pain need prompt evaluation',
  'The abnormal drainage raises the risk of stones and infection, so new fever and flank pain need prompt evaluation is correct. Fusion and malrotation impair drainage, so stones and infection are more common. She needs a plan for symptoms, not automatic nephrectomy. Incorrect alternatives: Denying the association, removing the kidney as a first step, forbidding antibiotics, and calling it a tumor are incorrect.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"KDIGO CKD Work Group. KDIGO 2024 Clinical Practice Guideline for CKD. Kidney Int 2024","url":"https://pubmed.ncbi.nlm.nih.gov/38490803/"}]'::jsonb,
  'generated',
  'd446ce5d5386538fad4059b0fbc392b8a361f537be2f44f1aabe44e92262d22b',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
