  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'renal',
  4,
  'renal',
  'renal',
  'pharmacotherapy',
  'Glyburide is a poor CKD choice',
  'vignette',
  'A 69-year-old man with an eGFR of 24 mL/min/1.73 m2 and type 2 diabetes has hypoglycemia to 48 mg/dL on glyburide. He is not on insulin. Meals are irregular.',
  'Which of the following is the most appropriate change?',
  '{"options":["Increase glyburide","Stop glyburide; it accumulates in low GFR and causes prolonged hypoglycemia","Add a second sulfonylurea","Start metformin at this eGFR","No change because 48 mg/dL is an acceptable fasting value"],"blueprintSystem":"renal","taskCategory":"pharmacotherapy","blueprintTopic":"Glyburide is a poor CKD choice","kind":"vignette"}',
  'Stop glyburide; it accumulates in low GFR and causes prolonged hypoglycemia',
  'Stop glyburide; it accumulates in low GFR and causes prolonged hypoglycemia is correct. Glyburide has active metabolites cleared by the kidney and is avoided in advanced CKD. A glucose of 48 is drug toxicity, not a target. Incorrect alternatives: Raising the dose, stacking sulfonylureas, or starting metformin below an eGFR of 30 adds harm.',
  '["pance","PANCE-2025","renal","pance-200-20261108-v1"]',
  '[{"label":"American Diabetes Association. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://doi.org/10.2337/dc26-s011"}]'::jsonb,
  'generated',
  '3289aa7db4809c406cbdc61989a0ac7292f5d2ed80c669bf63bf650fe28309ab',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  5,
  'cardiovascular',
  'cardiovascular',
  'pharmacotherapy',
  'HFrEF foundational therapy',
  'vignette',
  'A 61-year-old man with newly confirmed heart failure has an ejection fraction of 30%, NYHA class II symptoms, eGFR 62 mL/min/1.73 m2, and potassium 4.3 mEq/L. He is euvolemic. Blood pressure is 128/74 mm Hg. He takes no heart-failure drugs yet.',
  'Which of the following is the most appropriate disease-modifying plan?',
  '{"options":["Lisinopril and metoprolol tartrate only, with no mineralocorticoid antagonist or SGLT2 inhibitor","An ARNI or ACE inhibitor, evidence-based beta blocker, mineralocorticoid antagonist, and SGLT2 inhibitor","Amlodipine and hydrochlorothiazide as the four pillars","Diltiazem for rate control of sinus rhythm","Digoxin monotherapy"],"blueprintSystem":"cardiovascular","taskCategory":"pharmacotherapy","blueprintTopic":"HFrEF foundational therapy","kind":"vignette"}',
  'An ARNI or ACE inhibitor, evidence-based beta blocker, mineralocorticoid antagonist, and SGLT2 inhibitor',
  'An ARNI or ACE inhibitor, evidence-based beta blocker, mineralocorticoid antagonist, and SGLT2 inhibitor is correct. The 2022 heart-failure guideline uses four drug classes for HFrEF: renin-angiotensin system inhibition (ARNI preferred), an evidence-based beta blocker, a mineralocorticoid antagonist, and an SGLT2 inhibitor. He meets potassium and kidney thresholds and is not volume overloaded. Incorrect alternatives: Two-drug therapy from the older era, dihydropyridine-plus-thiazide as ''pillars,'' a non-dihydropyridine calcium blocker, and digoxin alone are not foundational therapy.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Heidenreich PA et al. 2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure. Circulation 2022","url":"https://pubmed.ncbi.nlm.nih.gov/35363499/"}]'::jsonb,
  'generated',
  'c5cc93c6ee5745a20a74961a053982c01ddd827385f3bbcf29b63f433751f3ff',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
