  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  5,
  'cardiovascular',
  'cardiovascular',
  'pharmacotherapy',
  'Beta blocker in a wet, shocked patient',
  'vignette',
  'A 58-year-old man with known HFrEF arrives in pulmonary edema. Blood pressure is 82/50 mm Hg, he is cold and clammy, and lactate is 4.2 mmol/L. He has not been taking his carvedilol for 2 days. A student wants the home dose restarted now.',
  'Which of the following is the most appropriate beta-blocker decision?',
  '{"options":["Give the full home dose of carvedilol intravenously now","Do not start a beta blocker during cardiogenic shock; stabilize perfusion first","Substitute atenolol","Add diltiazem instead","Start a beta blocker and a calcium blocker together"],"blueprintSystem":"cardiovascular","taskCategory":"pharmacotherapy","blueprintTopic":"Beta blocker in a wet, shocked patient","kind":"vignette"}',
  'Do not start a beta blocker during cardiogenic shock; stabilize perfusion first',
  'Do not start a beta blocker during cardiogenic shock; stabilize perfusion first is correct. Evidence-based beta blockers save lives in stable HFrEF, but they are not started in a hypotensive, hypoperfused patient. Perfusion is restored first. Incorrect alternatives: An intravenous full dose, atenolol, diltiazem, and a calcium-blocker combination worsen shock or are the wrong drug class.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Heidenreich PA et al. 2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure. Circulation 2022","url":"https://pubmed.ncbi.nlm.nih.gov/35363499/"}]'::jsonb,
  'generated',
  '88712fbbe23034585de08a798602c31539fbd46a07d06ca350271c7f7d521ae9',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
