  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  4,
  'cardiovascular',
  'cardiovascular',
  'pharmacotherapy',
  'Avoid diltiazem in HFrEF',
  'vignette',
  'A 66-year-old woman with an ejection fraction of 25% has new atrial fibrillation with a rate of 130/min. Blood pressure is 118/70 mm Hg and she is warm and mentating. A colleague suggests intravenous diltiazem.',
  'Which of the following is the most appropriate rate-control choice?',
  '{"options":["Intravenous diltiazem","A beta blocker such as metoprolol, avoiding a non-dihydropyridine calcium blocker","Verapamil","Immediate procainamide because every HFrEF patient has WPW","No rate control is ever used in heart failure"],"blueprintSystem":"cardiovascular","taskCategory":"pharmacotherapy","blueprintTopic":"Avoid diltiazem in HFrEF","kind":"vignette"}',
  'A beta blocker such as metoprolol, avoiding a non-dihydropyridine calcium blocker',
  'A beta blocker such as metoprolol, avoiding a non-dihydropyridine calcium blocker is correct. Diltiazem and verapamil are negative inotropes and are avoided in HFrEF. A beta blocker can slow the rate when the patient is perfusing. Incorrect alternatives: Verapamil has the same problem. Procainamide is for pre-excited atrial fibrillation, which is not described. Leaving a rate of 130 untreated is not the alternative.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Heidenreich PA et al. 2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure. Circulation 2022","url":"https://pubmed.ncbi.nlm.nih.gov/35363499/"}]'::jsonb,
  'generated',
  'bcfcaa9a222ee974f1f622dc98a7951fc870a8e57c337c759117d53a8cf6fef9',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  4,
  'cardiovascular',
  'cardiovascular',
  'pharmacotherapy',
  'Mineralocorticoid antagonist potassium limit',
  'vignette',
  'A 70-year-old man with HFrEF has an eGFR of 48 mL/min/1.73 m2 and a potassium of 5.3 mEq/L. He is already on sacubitril-valsartan, carvedilol, and dapagliflozin. Someone orders spironolactone 25 mg.',
  'Which of the following is the most appropriate action?',
  '{"options":["Start spironolactone and recheck potassium in 6 months","Do not start spironolactone at a potassium of 5.3 mEq/L","Double the dose because the eGFR is under 60","Add ibuprofen to lower potassium","Stop the SGLT2 inhibitor so the spironolactone can be started"],"blueprintSystem":"cardiovascular","taskCategory":"pharmacotherapy","blueprintTopic":"Mineralocorticoid antagonist potassium limit","kind":"vignette"}',
  'Do not start spironolactone at a potassium of 5.3 mEq/L',
  'Do not start spironolactone at a potassium of 5.3 mEq/L is correct. Mineralocorticoid antagonists are for HFrEF when potassium is under about 5.0 mEq/L and eGFR is above 30. A potassium of 5.3 is already above that start threshold. Incorrect alternatives: Starting and waiting 6 months, raising the dose, adding an NSAID, or stopping the SGLT2 inhibitor to ''make room'' are unsafe.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Heidenreich PA et al. 2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure. Circulation 2022","url":"https://pubmed.ncbi.nlm.nih.gov/35363499/"}]'::jsonb,
  'generated',
  '3a0928104fea1c4b4a11d2a711c99fc8d31bc62b8e37be255b95e143c6c5bc55',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  5,
  'cardiovascular',
  'cardiovascular',
  'intervention',
  'Primary-prevention ICD timing',
  'vignette',
  'A 54-year-old man was diagnosed with nonischemic dilated cardiomyopathy 3 weeks ago. Ejection fraction is 25% on guideline-directed therapy that was just started. He has never had syncope or ventricular tachycardia. He is NYHA class II and euvolemic.',
  'Which of the following is the most appropriate device plan?',
  '{"options":["Implant a primary-prevention ICD this week","Optimize medical therapy and reassess the ejection fraction after about 3 months before a primary-prevention ICD","Implant a pacemaker for sinus rhythm at 70/min","Start amiodarone indefinitely instead of any reassessment","No medical therapy is needed if a device is planned"],"blueprintSystem":"cardiovascular","taskCategory":"intervention","blueprintTopic":"Primary-prevention ICD timing","kind":"vignette"}',
  'Optimize medical therapy and reassess the ejection fraction after about 3 months before a primary-prevention ICD',
  'Optimize medical therapy and reassess the ejection fraction after about 3 months before a primary-prevention ICD is correct. Primary-prevention ICD decisions wait until reversible causes are treated and guideline-directed therapy has had time to improve the ejection fraction, generally on the order of 3 months, in a patient with a reasonable survival expectation. Incorrect alternatives: Implanting this week, pacing a normal rhythm, empiric amiodarone, and skipping drugs all skip that reassessment.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Heidenreich PA et al. 2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure. Circulation 2022","url":"https://pubmed.ncbi.nlm.nih.gov/35363499/"}]'::jsonb,
  'generated',
  '89853b609c6265ace616a03c59974513e497a7a53721d7d49253913fbbe4b50e',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  5,
  'cardiovascular',
  'cardiovascular',
  'diagnosis',
  'Pre-excited atrial fibrillation',
  'vignette',
  'A 27-year-old man has palpitations. Blood pressure is 110/70 mm Hg. The ECG shows an irregular wide-complex tachycardia at 180/min with beat-to-beat changes in QRS shape. He has a known accessory pathway. He is mentating.',
  'Which of the following is the drug to avoid?',
  '{"options":["Procainamide","Ibutilide","AV-nodal blockers such as diltiazem, verapamil, adenosine, or digoxin","Synchronized cardioversion if he becomes unstable","Expert consultation for ablation after the acute episode"],"blueprintSystem":"cardiovascular","taskCategory":"diagnosis","blueprintTopic":"Pre-excited atrial fibrillation","kind":"vignette"}',
  'AV-nodal blockers such as diltiazem, verapamil, adenosine, or digoxin',
  'AV-nodal blockers such as diltiazem, verapamil, adenosine, or digoxin is correct. In pre-excited atrial fibrillation, blocking the AV node can send all conduction down the accessory pathway and accelerate the ventricular rate into fibrillation. Procainamide or ibutilide, or shock if unstable, are the acute options. Incorrect alternatives: Those other choices are appropriate, which is why the node-blocking drugs are the ones that are incorrect here.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Page RL et al. 2015 ACC/AHA/HRS Guideline for the Management of Adult Patients With Supraventricular Tachycardia. Circulation 2016","url":"https://pubmed.ncbi.nlm.nih.gov/26399663/"}]'::jsonb,
  'generated',
  'a00e2c380c10a9eb76ca92e8edeb25b2c21b9feb1c13042a16292e6154b90a6a',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  4,
  'cardiovascular',
  'cardiovascular',
  'pharmacotherapy',
  'Severe symptomatic aortic stenosis',
  'vignette',
  'An 82-year-old man has exertional syncope. Echo shows a valve area of 0.8 cm2, a mean gradient of 44 mm Hg, and an ejection fraction of 60%. Blood pressure is 138/70 mm Hg. A student wants to ''unload'' him with a standing dose of hydralazine.',
  'Which of the following is the most appropriate direction?',
  '{"options":["Oral hydralazine as definitive therapy","Refer for aortic valve replacement; do not treat severe symptomatic stenosis with vasodilation as the plan","Watch until the ejection fraction falls below 30%","Start a beta blocker to slow the heart to 40/min","Balloon valvuloplasty as a cure"],"blueprintSystem":"cardiovascular","taskCategory":"pharmacotherapy","blueprintTopic":"Severe symptomatic aortic stenosis","kind":"vignette"}',
  'Refer for aortic valve replacement; do not treat severe symptomatic stenosis with vasodilation as the plan',
  'Refer for aortic valve replacement; do not treat severe symptomatic stenosis with vasodilation as the plan is correct. Syncope with severe high-gradient aortic stenosis is a replacement indication. Afterload reduction does not fix a fixed obstruction and can drop coronary perfusion. Incorrect alternatives: Waiting for the ejection fraction to collapse, extreme bradycardia, and valvuloplasty as destination therapy are not the guideline plan.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Otto CM et al. 2020 ACC/AHA Guideline for the Management of Patients With Valvular Heart Disease. Circulation 2021","url":"https://pubmed.ncbi.nlm.nih.gov/33332150/"}]'::jsonb,
  'generated',
  '89f2d98e74446fbfec5f760bd1a520997bb60dfa570210518285b6ef27be2dbc',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  5,
  'cardiovascular',
  'cardiovascular',
  'pharmacotherapy',
  'Mechanical mitral valve anticoagulation',
  'vignette',
  'A 44-year-old woman with a mechanical mitral valve and atrial fibrillation has an INR of 2.2 on warfarin. She asks to switch to apixaban so she can stop checks. She is not pregnant.',
  'Which of the following is the most appropriate plan?',
  '{"options":["Switch to apixaban 5 mg twice daily","Continue warfarin and raise the INR target to 2.5 to 3.5","Aspirin alone","Stop anticoagulation 1 year after valve placement","Dabigatran 150 mg twice daily"],"blueprintSystem":"cardiovascular","taskCategory":"pharmacotherapy","blueprintTopic":"Mechanical mitral valve anticoagulation","kind":"vignette"}',
  'Continue warfarin and raise the INR target to 2.5 to 3.5',
  'Continue warfarin and raise the INR target to 2.5 to 3.5 is correct. A mechanical mitral valve is a warfarin valve. Direct oral anticoagulants are not used. With atrial fibrillation or a mitral prosthesis the INR target is 3, range 2.5 to 3.5, which is higher than her current 2.2. Incorrect alternatives: Apixaban, dabigatran, aspirin alone, and stopping therapy leave the valve unprotected.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Otto CM et al. 2020 ACC/AHA Guideline for the Management of Patients With Valvular Heart Disease. Circulation 2021","url":"https://pubmed.ncbi.nlm.nih.gov/33332150/"}]'::jsonb,
  'generated',
