INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  4,
  'cardiovascular',
  'cardiovascular',
  'pharmacotherapy',
  'Pregnancy and an ACE inhibitor',
  'vignette',
  'A 33-year-old woman at 9 weeks'' gestation was switched from lisinopril to losartan a week ago at an urgent care visit after a positive pregnancy test. Blood pressure today is 126/76 mm Hg. Potassium and creatinine are normal. She was told an ARB was the safe substitute.',
  'Which of the following is the most appropriate change?',
  '{"options":["Continue losartan because it is not an ACE inhibitor","Stop losartan and use labetalol or nifedipine if treatment is still needed","Add spironolactone to losartan","Switch to aliskiren","Restart lisinopril at half the old dose"],"blueprintSystem":"cardiovascular","taskCategory":"pharmacotherapy","blueprintTopic":"Pregnancy and an ACE inhibitor","kind":"vignette"}',
  'Stop losartan and use labetalol or nifedipine if treatment is still needed',
  'Stop losartan and use labetalol or nifedipine if treatment is still needed is correct. ARBs are fetotoxic in the same way ACE inhibitors are. Substituting losartan does not make the renin-angiotensin block safe in pregnancy. Labetalol or nifedipine is used if medication is still required. Incorrect alternatives: Continuing the ARB, adding spironolactone, switching to aliskiren, or restarting the ACE inhibitor all keep a drug class that is stopped once pregnancy is known.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Jones DW et al. 2025 AHA/ACC Guideline for the Management of High Blood Pressure in Adults. J Am Coll Cardiol 2025","url":"https://pubmed.ncbi.nlm.nih.gov/40815242/"}]'::jsonb,
  'generated',
  'e34926ce440a8739942158dd2d93ccb7488bc0ba52340a66fa53c125bd864b22',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
