) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  4,
  'cardiovascular',
  'cardiovascular',
  'prevention',
  'Abdominal aortic aneurysm screening',
  'vignette',
  'A 67-year-old man smoked a pack a day from age 20 to 40 and quit. He has never been screened for an abdominal aortic aneurysm. He has no abdominal symptoms. A one-time ultrasound is being considered.',
  'Which of the following is the most appropriate recommendation?',
  '{"options":["No screening because he quit","One-time abdominal ultrasound","Annual CT angiography for life","Screening only if he is over 85","Immediate open repair of an unmeasured aorta"],"blueprintSystem":"cardiovascular","taskCategory":"prevention","blueprintTopic":"Abdominal aortic aneurysm screening","kind":"vignette"}',
  'One-time abdominal ultrasound',
  'One-time abdominal ultrasound is correct. USPSTF recommends one-time ultrasound screening for abdominal aortic aneurysm in men 65 to 75 who have ever smoked. Quitting does not remove the indication. Incorrect alternatives: Skipping him, yearly CT, waiting past 85, and operating without a measurement are not the recommendation.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"US Preventive Services Task Force. Screening for Abdominal Aortic Aneurysm. JAMA 2019","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/abdominal-aortic-aneurysm-screening"}]'::jsonb,
  'generated',
  'd1f8d2edf953fd3d8ac55c853a0e61509e86d9a67cdb56148de4c6693e6cb585',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
