  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  4,
  'cardiovascular',
  'cardiovascular',
  'pharmacotherapy',
  'Cilostazol and heart failure',
  'vignette',
  'A 72-year-old man with claudication at 1 block has an ejection fraction of 30%. He already takes aspirin, a statin, and a beta blocker. A brochure suggests cilostazol for the walking distance.',
  'Which of the following is the most appropriate statement?',
  '{"options":["Cilostazol is safe and preferred in HFrEF","Do not use cilostazol; it is contraindicated in heart failure. Supervised exercise and risk-factor therapy remain the plan","Stop the statin and use cilostazol instead","Start warfarin for claudication","No walking program is allowed"],"blueprintSystem":"cardiovascular","taskCategory":"pharmacotherapy","blueprintTopic":"Cilostazol and heart failure","kind":"vignette"}',
  'Do not use cilostazol; it is contraindicated in heart failure. Supervised exercise and risk-factor therapy remain the plan',
  'Do not use cilostazol; it is contraindicated in heart failure. Supervised exercise and risk-factor therapy remain the plan is correct. Cilostazol is a phosphodiesterase inhibitor labeled as contraindicated in heart failure. Claudication care is exercise, statin, antiplatelet, and smoking cessation. Incorrect alternatives: Using it in HFrEF, swapping out the statin, anticoagulating routine claudication, and banning walking are wrong.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Heidenreich PA et al. 2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure. Circulation 2022","url":"https://pubmed.ncbi.nlm.nih.gov/35363499/"}]'::jsonb,
  'generated',
  '575493f428e434a868e4aebc75e2505a14f19ed37ecafa6653cc1ce80ea6a796',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
