  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  5,
  'cardiovascular',
  'cardiovascular',
  'diagnosis',
  'Isolated distal DVT',
  'vignette',
  'A 40-year-old woman has calf pain 4 days after a sprained ankle. She is not pregnant, has no cancer, and bleeding risk is not high. Ultrasound shows a thrombus in one posterior tibial vein and no popliteal or femoral thrombus. Symptoms are mild.',
  'Which of the following is an acceptable CHEST-consistent plan?',
  '{"options":["A vena cava filter as first line","Serial duplex ultrasound over 2 weeks, and anticoagulate if it extends","Lifelong warfarin with an INR target of 3.5","Thrombolysis through a catheter today","Aspirin 325 mg as the only proven treatment"],"blueprintSystem":"cardiovascular","taskCategory":"diagnosis","blueprintTopic":"Isolated distal DVT","kind":"vignette"}',
  'Serial duplex ultrasound over 2 weeks, and anticoagulate if it extends',
  'Serial duplex ultrasound over 2 weeks, and anticoagulate if it extends is correct. For isolated distal DVT without severe symptoms or high risk of extension, CHEST suggests serial imaging rather than immediate anticoagulation. Extension, especially into a proximal vein, changes that plan. Incorrect alternatives: A filter, an INR of 3.5 for life, catheter thrombolysis, and aspirin monotherapy are not the suggestion for this low-risk distal clot.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Stevens SM et al. Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline. Chest 2021","url":"https://journal.chestnet.org/article/S0012-3692(21)01506-3/fulltext"}]'::jsonb,
  'generated',
  'e7fefe3db4ca92b80f0a916a9a49c4b9b1bf9a1ac5bd9fca954a61f5675dc009',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
