  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  4,
  'cardiovascular',
  'cardiovascular',
  'pharmacotherapy',
  'Proximal DVT treatment length',
  'vignette',
  'A 52-year-old man has a first femoral-vein DVT after a 10-hour flight and a short-leg cast. The cast is off and he is walking. Bleeding risk is low. Cancer screening history is unremarkable and the clot is clearly provoked by the transient risks.',
  'Which of the following is the most appropriate anticoagulation duration?',
  '{"options":["Three days","Three months, not indefinite therapy, for a first proximal DVT provoked by a transient risk","Indefinite therapy because every DVT is lifelong","A vena cava filter instead of any anticoagulant","Aspirin alone"],"blueprintSystem":"cardiovascular","taskCategory":"pharmacotherapy","blueprintTopic":"Proximal DVT treatment length","kind":"vignette"}',
  'Three months, not indefinite therapy, for a first proximal DVT provoked by a transient risk',
  'Three months, not indefinite therapy, for a first proximal DVT provoked by a transient risk is correct. A proximal DVT needs treatment, and a clearly transient provocation such as recent travel plus immobilization is managed with a finite course, typically 3 months, rather than lifelong anticoagulation. Incorrect alternatives: Three days is too short. Indefinite therapy is for unprovoked or ongoing-risk clots. A filter and aspirin do not replace anticoagulation in a patient who can take it.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Stevens SM et al. Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline. Chest 2021","url":"https://journal.chestnet.org/article/S0012-3692(21)01506-3/fulltext"}]'::jsonb,
  'generated',
  '13e4f76d96ddea1a60a5790e11c8dbeec9049b0ba95b3bc63afa4da69a8d7ff9',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
