  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  4,
  'cardiovascular',
  'cardiovascular',
  'diagnosis',
  'Aortic dissection blood pressure',
  'vignette',
  'A 63-year-old man has sudden tearing chest pain to the back. Blood pressure is 188/100 mm Hg in the right arm and 140/80 mm Hg in the left. CT angiography shows a type B dissection without malperfusion. He is mentating and not in shock.',
  'Which of the following is the most appropriate initial medical sequence?',
  '{"options":["Hydralazine alone","Heart-rate control with an intravenous beta blocker before a vasodilator","Immediate thrombolysis","Aspirin, heparin, and a P2Y12 inhibitor","No blood-pressure treatment because it is type B"],"blueprintSystem":"cardiovascular","taskCategory":"diagnosis","blueprintTopic":"Aortic dissection blood pressure","kind":"vignette"}',
  'Heart-rate control with an intravenous beta blocker before a vasodilator',
  'Heart-rate control with an intravenous beta blocker before a vasodilator is correct. Dissection management lowers shear stress. Rate is controlled first so vasodilation does not cause reflex tachycardia. Type B without complications is medical at the start. Incorrect alternatives: Hydralazine alone raises heart rate. Thrombolysis and an acute coronary cocktail treat a different emergency. Ignoring the pressure leaves the flap stressed.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Jones DW et al. 2025 AHA/ACC Guideline for the Management of High Blood Pressure in Adults. J Am Coll Cardiol 2025","url":"https://pubmed.ncbi.nlm.nih.gov/40815242/"}]'::jsonb,
  'generated',
  'eb45437c8ffb92633850a88e55dbf3545b778ec98dcf5e0906c27c500c78ae5c',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
