  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  4,
  'cardiovascular',
  'cardiovascular',
  'pharmacotherapy',
  'Statin intensity after a coronary stent',
  'vignette',
  'A 59-year-old man had a drug-eluting stent yesterday for a non-ST-elevation myocardial infarction. LDL cholesterol is 96 mg/dL. He has no statin intolerance.',
  'Which of the following is the most appropriate lipid drug?',
  '{"options":["No statin because the LDL is under 100","High-intensity statin","Gemfibrozil monotherapy","Niacin as the only agent","A low-intensity statin because he is under 75"],"blueprintSystem":"cardiovascular","taskCategory":"pharmacotherapy","blueprintTopic":"Statin intensity after a coronary stent","kind":"vignette"}',
  'High-intensity statin',
  'High-intensity statin is correct. Clinical atherosclerotic disease is a high-intensity statin indication regardless of an LDL already under 100. The goal is further risk reduction, not a single threshold that cancels treatment. Incorrect alternatives: Fibrate or niacin monotherapy, or a low-intensity dose because of age under 75, is not secondary prevention.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Heidenreich PA et al. 2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure. Circulation 2022","url":"https://pubmed.ncbi.nlm.nih.gov/35363499/"}]'::jsonb,
  'generated',
  '47e33dd64e497c7a9b0b52957b864b762a2e774b4634affaed13422ba433a83d',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
