  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'cardiovascular',
  3,
  'cardiovascular',
  'cardiovascular',
  'diagnosis',
  'Tamponade pulsus paradoxus',
  'vignette',
  'A 45-year-old woman with breast cancer has dyspnea. Blood pressure is 88/70 mm Hg and falls by 18 mm Hg on inspiration. Jugular veins are distended and heart sounds are faint. The lungs are clear.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Intravenous fluid restriction and a beta blocker","Urgent echocardiography and pericardial drainage for tamponade","Thrombolysis for presumed pulmonary embolism without imaging","Oral furosemide as the only treatment","Discharge with a 1-week clinic visit"],"blueprintSystem":"cardiovascular","taskCategory":"diagnosis","blueprintTopic":"Tamponade pulsus paradoxus","kind":"vignette"}',
  'Urgent echocardiography and pericardial drainage for tamponade',
  'Urgent echocardiography and pericardial drainage for tamponade is correct. Hypotension, elevated jugular pressure, clear lungs, faint sounds, and an inspiratory systolic drop are tamponade, especially with cancer. Drainage is the treatment. Incorrect alternatives: A beta blocker, blind thrombolysis, diuresis, and discharge worsen or miss obstructive shock.',
  '["pance","PANCE-2025","cardiovascular","pance-200-20261108-v1"]',
  '[{"label":"Otto CM et al. 2020 ACC/AHA Guideline for the Management of Patients With Valvular Heart Disease. Circulation 2021","url":"https://pubmed.ncbi.nlm.nih.gov/33332150/"}]'::jsonb,
  'generated',
  '4c00309066902d386bddc2c94dac48d731e4305cc2341a46d7653bfd8bef59ec',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
