  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  4,
  'pulmonary',
  'pulmonary',
  'pharmacotherapy',
  'COPD initial inhalers',
  'vignette',
  'A 66-year-old former smoker has COPD with an FEV1 of 55% predicted, a modified MRC dyspnea score of 3, and no exacerbations in the past year. Eosinophils are 80/mm3. He uses only a short-acting bronchodilator.',
  'Which of the following is the most appropriate controller?',
  '{"options":["Inhaled corticosteroid monotherapy","A long-acting muscarinic antagonist plus a long-acting beta agonist","Continuous oral prednisone","Theophylline as the only controller","No long-acting inhaler until FEV1 is under 30%"],"blueprintSystem":"pulmonary","taskCategory":"pharmacotherapy","blueprintTopic":"COPD initial inhalers","kind":"vignette"}',
  'A long-acting muscarinic antagonist plus a long-acting beta agonist',
  'A long-acting muscarinic antagonist plus a long-acting beta agonist is correct. High symptom burden with few exacerbations and a low eosinophil count is treated with dual long-acting bronchodilation. An inhaled corticosteroid is not monotherapy and is less useful when eosinophils are low and exacerbations are absent. Incorrect alternatives: Daily prednisone, theophylline alone, and waiting for very severe obstruction are not the initial controller strategy.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 report. Lancet Respir Med 2025","url":"https://pubmed.ncbi.nlm.nih.gov/41317736/"}]'::jsonb,
  'generated',
  '68e4a99744de984051d30af8976590f5c4f6f5b08a0f8cbd3c9f54b4b073c5ca',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  4,
  'pulmonary',
  'pulmonary',
  'pharmacotherapy',
  'COPD exacerbation antibiotics',
  'vignette',
  'A 70-year-old man with COPD has increased dyspnea, increased sputum volume, and newly purulent sputum for 2 days. He is not in respiratory failure. Oxygen saturation is 93% on his baseline 2 L. He has no pneumonia on chest radiograph.',
  'Which of the following is the most appropriate addition to bronchodilators and a short steroid course?',
  '{"options":["No antibiotic, because purulence does not matter","An antibiotic, because he has the three cardinal symptoms including purulence","A 6-week fluoroquinolone","Vancomycin and piperacillin for 14 days","Isoniazid"],"blueprintSystem":"pulmonary","taskCategory":"pharmacotherapy","blueprintTopic":"COPD exacerbation antibiotics","kind":"vignette"}',
  'An antibiotic, because he has the three cardinal symptoms including purulence',
  'An antibiotic, because he has the three cardinal symptoms including purulence is correct. Antibiotics are used for COPD exacerbations when sputum is purulent along with increased dyspnea and volume, or when ventilation is required. A short course is enough in the absence of pneumonia. Incorrect alternatives: Ignoring purulence, a 6-week quinolone, broad intravenous therapy, and tuberculosis drugs do not match this outpatient exacerbation.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 report. Lancet Respir Med 2025","url":"https://pubmed.ncbi.nlm.nih.gov/41317736/"}]'::jsonb,
  'generated',
  '355395adc5fc8a9b142f2e06e2cd82ef4935a2305879aa431a0a182862343708',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  4,
  'pulmonary',
  'pulmonary',
  'pharmacotherapy',
  'Oxygen criteria',
  'vignette',
  'A 73-year-old woman with COPD has a resting oxygen saturation of 86% and a PaO2 of 54 mm Hg on room air, repeated after she is stable. She does not currently use oxygen. She is not dyspneic at rest today but qualifies on the gas.',
  'Which of the following is the most appropriate prescription?',
  '{"options":["Oxygen only with exercise, because rest saturation is irrelevant","Long-term oxygen sufficient to raise the resting saturation above 90%","No oxygen unless PaO2 is under 40 mm Hg","Continuous oral morphine instead of oxygen","An inhaled corticosteroid as a substitute for oxygen"],"blueprintSystem":"pulmonary","taskCategory":"pharmacotherapy","blueprintTopic":"Oxygen criteria","kind":"vignette"}',
  'Long-term oxygen sufficient to raise the resting saturation above 90%',
  'Long-term oxygen sufficient to raise the resting saturation above 90% is correct. Resting hypoxemia at this level is an indication for long-term oxygen, which is one of the few COPD treatments shown to improve survival in that group. Incorrect alternatives: Exercise-only oxygen, a PaO2 cutoff of 40, morphine as a substitute, and a steroid instead of oxygen miss the indication.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 report. Lancet Respir Med 2025","url":"https://pubmed.ncbi.nlm.nih.gov/41317736/"}]'::jsonb,
  'generated',
  '8c8eb1e31002d6652ffb17444b3a3ce267e9e4184d3fd6d62b6ceb25473d4993',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  5,
  'pulmonary',
  'pulmonary',
  'intervention',
  'Noninvasive ventilation in acidosis',
  'vignette',
  'A 68-year-old man with COPD is drowsy, using accessory muscles, with a respiratory rate of 32/min. Arterial pH is 7.26 and PaCO2 is 68 mm Hg. He is protecting his airway and has no vomiting. Oxygen saturation is 90% on a controlled oxygen device.',
  'Which of the following is the most appropriate ventilatory step?',
  '{"options":["High-flow oxygen at 15 L by reservoir mask","Noninvasive ventilation, and do not delay it for a normal pH","Immediate intubation because noninvasive ventilation is contraindicated under pH 7.35","Sedation with a benzodiazepine","Bicarbonate infusion as the only support"],"blueprintSystem":"pulmonary","taskCategory":"intervention","blueprintTopic":"Noninvasive ventilation in acidosis","kind":"vignette"}',
  'Noninvasive ventilation, and do not delay it for a normal pH',
  'Noninvasive ventilation, and do not delay it for a normal pH is correct. Respiratory acidosis with distress in an exacerbation is a reason to start noninvasive ventilation now, before the patient tires into a tube. He still protects his airway. Incorrect alternatives: Uncontrolled oxygen, mandatory intubation at pH 7.26, benzodiazepines, and bicarbonate alone worsen CO2 retention or skip the proven support.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 report. Lancet Respir Med 2025","url":"https://pubmed.ncbi.nlm.nih.gov/41317736/"}]'::jsonb,
  'generated',
  '2205a21f35201473d3d5adc9e627bd662c9b16b539c8e91ec7af962ae10b902e',
  'pance-200-20261108-v1',
  'pending',
  false,
