  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  3,
  'pulmonary',
  'pulmonary',
  'pharmacotherapy',
  'Outpatient community-acquired pneumonia',
  'vignette',
  'A 45-year-old woman has 2 days of fever, cough, and a focal infiltrate. She is not hypoxic, has no comorbidities, has not used antibiotics recently, and lives at home. CURB-65 is 0. She has no drug allergies.',
  'Which of the following is appropriate empiric therapy?',
  '{"options":["Piperacillin-tazobactam and vancomycin","Amoxicillin or doxycycline","Ciprofloxacin alone","Oseltamivir as the only drug in July with no influenza testing","Observation without antibiotics"],"blueprintSystem":"pulmonary","taskCategory":"pharmacotherapy","blueprintTopic":"Outpatient community-acquired pneumonia","kind":"vignette"}',
  'Amoxicillin or doxycycline',
  'Amoxicillin or doxycycline is correct. The 2019 ATS/IDSA guideline treats healthy outpatients without recent antibiotics with amoxicillin, doxycycline, or a macrolide only where pneumococcal resistance is low. She does not need MRSA or Pseudomonas coverage. Incorrect alternatives: Antipseudomonal and MRSA drugs, ciprofloxacin monotherapy, influenza treatment without a reason, and no antibiotic for a confirmed infiltrate are mismatches.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Metlay JP et al. Diagnosis and Treatment of Adults with Community-acquired Pneumonia. ATS/IDSA Guideline. Am J Respir Crit Care Med 2019","url":"https://pubmed.ncbi.nlm.nih.gov/31573350/"}]'::jsonb,
  'generated',
  'dad44fb065b4fbb32f3f7c1fcb062b9ba5ce6281544d6c552253ae21e94eb480',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
