  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  4,
  'pulmonary',
  'pulmonary',
  'pharmacotherapy',
  'CAP with comorbidities',
  'vignette',
  'A 67-year-old man with diabetes and CKD has community-acquired pneumonia. He is well enough for oral therapy. He has no MRSA or Pseudomonas risk factors and no severe penicillin allergy.',
  'Which of the following is an appropriate oral regimen?',
  '{"options":["Amoxicillin alone","A beta-lactam plus a macrolide, or a respiratory fluoroquinolone","Vancomycin monotherapy","Metronidazole","Acyclovir"],"blueprintSystem":"pulmonary","taskCategory":"pharmacotherapy","blueprintTopic":"CAP with comorbidities","kind":"vignette"}',
  'A beta-lactam plus a macrolide, or a respiratory fluoroquinolone',
  'A beta-lactam plus a macrolide, or a respiratory fluoroquinolone is correct. Outpatients with comorbidities get broader coverage than healthy adults: combination therapy with a beta-lactam plus macrolide, or monotherapy with a respiratory fluoroquinolone. Incorrect alternatives: Amoxicillin alone is the healthy-adult option. Vancomycin, metronidazole, and acyclovir do not cover typical and atypical respiratory pathogens in this pattern.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Metlay JP et al. Diagnosis and Treatment of Adults with Community-acquired Pneumonia. ATS/IDSA Guideline. Am J Respir Crit Care Med 2019","url":"https://pubmed.ncbi.nlm.nih.gov/31573350/"}]'::jsonb,
  'generated',
  '404238109dd7175e20038fce66f4cd9bb3f46f81962b99594b304e13207dc965',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
