  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  5,
  'pulmonary',
  'pulmonary',
  'pharmacotherapy',
  'When to cover MRSA pneumonia',
  'vignette',
  'A 58-year-old man with influenza last week now has cavitary pneumonia, a respiratory rate of 32/min, and a new oxygen need. He had MRSA in the blood 2 months ago. He is being admitted.',
  'Which of the following is the most appropriate addition while cultures are pending?',
  '{"options":["No additional coverage beyond ceftriaxone and azithromycin","Add MRSA coverage such as vancomycin or linezolid","Daptomycin for the lung","Stop all antibiotics until the culture returns","Oral cephalexin only"],"blueprintSystem":"pulmonary","taskCategory":"pharmacotherapy","blueprintTopic":"When to cover MRSA pneumonia","kind":"vignette"}',
  'Add MRSA coverage such as vancomycin or linezolid',
  'Add MRSA coverage such as vancomycin or linezolid is correct. Prior MRSA and a cavitary post-influenza pneumonia are reasons to cover MRSA empirically, then de-escalate if cultures are negative. Linezolid or vancomycin is used; daptomycin is inactivated in the lung. Incorrect alternatives: Standard ceftriaxone-azithromycin, daptomycin, waiting with no drug, and cephalexin under-treat or miss the site.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Metlay JP et al. Diagnosis and Treatment of Adults with Community-acquired Pneumonia. ATS/IDSA Guideline. Am J Respir Crit Care Med 2019","url":"https://pubmed.ncbi.nlm.nih.gov/31573350/"}]'::jsonb,
  'generated',
  'a290f345a4cefd50284b2e8bc976e9764f812b07212814530a82bd55054ff796',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
