  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  4,
  'pulmonary',
  'pulmonary',
  'diagnosis',
  'Light criteria for pleural fluid',
  'vignette',
  'A 60-year-old man has a unilateral effusion. Pleural fluid protein is 4.2 g/dL with serum protein 6.0 g/dL. Fluid LDH is 400 U/L with a serum upper limit of normal of 200 U/L. Fluid glucose is 70 mg/dL.',
  'Which of the following does this fluid represent?',
  '{"options":["A transudate by Light criteria","An exudate, because protein ratio and LDH ratio are both high","Normal saline from a lab error, so no further thought","Empyema, because glucose is 70","A transudate because glucose is normal"],"blueprintSystem":"pulmonary","taskCategory":"diagnosis","blueprintTopic":"Light criteria for pleural fluid","kind":"vignette"}',
  'An exudate, because protein ratio and LDH ratio are both high',
  'An exudate, because protein ratio and LDH ratio are both high is correct. Light criteria call fluid an exudate if protein ratio exceeds 0.5, LDH ratio exceeds 0.6, or fluid LDH exceeds two-thirds of the serum upper limit. His protein ratio is 0.7 and LDH ratio is 2. Incorrect alternatives: It is not a transudate. Glucose of 70 does not define empyema. A normal glucose does not reclassify an exudate.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Metlay JP et al. Diagnosis and Treatment of Adults with Community-acquired Pneumonia. ATS/IDSA Guideline. Am J Respir Crit Care Med 2019","url":"https://pubmed.ncbi.nlm.nih.gov/31573350/"}]'::jsonb,
  'generated',
  '704ea57f19f959597528bd462cbba026c7c5f958c7ccb0c6d24c9c1bdcc41890',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
