  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  5,
  'pulmonary',
  'pulmonary',
  'intervention',
  'Complicated parapneumonic effusion',
  'vignette',
  'A 55-year-old man with pneumonia has a free-flowing effusion. Thoracentesis returns pH 7.05, glucose 30 mg/dL, and LDH 1,800 U/L. Gram stain shows organisms. He is on antibiotics.',
  'Which of the following is required in addition to antibiotics?',
  '{"options":["Observation of the fluid","Drainage of the pleural space","A second antibiotic only","Diuresis","Inhaled corticosteroid"],"blueprintSystem":"pulmonary","taskCategory":"intervention","blueprintTopic":"Complicated parapneumonic effusion","kind":"vignette"}',
  'Drainage of the pleural space',
  'Drainage of the pleural space is correct. A low pH, low glucose, and organisms define a complicated parapneumonic effusion or empyema. Antibiotics do not replace drainage. Incorrect alternatives: Watching it, adding another drug alone, diuresis, and an inhaler leave pus in the chest.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Metlay JP et al. Diagnosis and Treatment of Adults with Community-acquired Pneumonia. ATS/IDSA Guideline. Am J Respir Crit Care Med 2019","url":"https://pubmed.ncbi.nlm.nih.gov/31573350/"}]'::jsonb,
  'generated',
  '9a9d2aac949b5be064278af4e1fd057edadfdcc00628e1d08b2729acc4aef1bb',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
