) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  4,
  'pulmonary',
  'pulmonary',
  'diagnosis',
  'Pulmonary embolism Wells and age-adjusted D-dimer',
  'vignette',
  'A 70-year-old man has pleuritic pain. He has no hemoptysis, no leg swelling, no immobilization, no prior clot, and an alternative diagnosis of pneumonia is more likely. Heart rate is 80/min. A D-dimer is 560 ng/mL FEU (threshold 500).',
  'Which of the following is the best interpretation?',
  '{"options":["CT pulmonary angiography is mandatory because 560 exceeds 500","His pretest probability is low, and an age-adjusted D-dimer cutoff of about 700 makes 560 non-diagnostic of clot","Start heparin without imaging","The D-dimer proves pulmonary embolism","Thrombolysis now"],"blueprintSystem":"pulmonary","taskCategory":"diagnosis","blueprintTopic":"Pulmonary embolism Wells and age-adjusted D-dimer","kind":"vignette"}',
  'His pretest probability is low, and an age-adjusted D-dimer cutoff of about 700 makes 560 non-diagnostic of clot',
  'His pretest probability is low, and an age-adjusted D-dimer cutoff of about 700 makes 560 non-diagnostic of clot is correct. Wells score here is low. For patients over 50, an age-adjusted D-dimer cutoff (age times 10 ng/mL) is used in low or intermediate probability. At age 70 that cutoff is about 700, so 560 does not force a CT. Incorrect alternatives: Treating 560 as proof, starting heparin, or giving thrombolysis skips probability.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Stevens SM et al. Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline. Chest 2021","url":"https://journal.chestnet.org/article/S0012-3692(21)01506-3/fulltext"}]'::jsonb,
  'generated',
  'f652199b768a9073c7b088d8fa4c019c49f2e4621a76fc295079b92377b8a7e5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
