) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  4,
  'pulmonary',
  'pulmonary',
  'pharmacotherapy',
  'Asthma step with a history of intubation',
  'vignette',
  'A 24-year-old woman has asthma and was intubated 8 months ago. She uses albuterol daily and wakes at night twice a week. She is on no controller. Eosinophils are not needed to see that this is uncontrolled and high risk.',
  'Which of the following is the most appropriate controller direction?',
  '{"options":["Albuterol only, because she is between attacks","Start an inhaled corticosteroid-containing controller and do not rely on a short-acting beta agonist alone","Daily oral prednisone forever as the first controller","A long-acting beta agonist without an inhaled corticosteroid","Antibiotics for 14 days"],"blueprintSystem":"pulmonary","taskCategory":"pharmacotherapy","blueprintTopic":"Asthma step with a history of intubation","kind":"vignette"}',
  'Start an inhaled corticosteroid-containing controller and do not rely on a short-acting beta agonist alone',
  'Start an inhaled corticosteroid-containing controller and do not rely on a short-acting beta agonist alone is correct. A prior intubation marks high-risk asthma. A short-acting beta agonist alone is not a controller, and a long-acting beta agonist is never used without an inhaled corticosteroid. Incorrect alternatives: Endless prednisone as the first step, monotherapy with a long-acting beta agonist, and antibiotics are not asthma control.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Global Initiative for Asthma. Global Strategy for Asthma Management and Prevention, 2025","url":"https://ginasthma.org/"}]'::jsonb,
  'generated',
  '60fc904d38fe0137311486d447474193c42cae6a844e713d70233fe4fa194b57',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
