) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  3,
  'pulmonary',
  'pulmonary',
  'diagnosis',
  'Solitary pulmonary nodule follow-up',
  'vignette',
  'A 45-year-old never-smoker has a smooth 4-mm solid nodule found on a CT done for a kidney stone. There is no comparison film. She has no cancer history.',
  'Which of the following is the most appropriate statement?',
  '{"options":["Resect it this week","A 4-mm solid nodule in a low-risk patient does not need short-interval PET or resection","PET-CT tomorrow","Empiric antifungals for a year","Bronchoscopy today"],"blueprintSystem":"pulmonary","taskCategory":"diagnosis","blueprintTopic":"Solitary pulmonary nodule follow-up","kind":"vignette"}',
  'A 4-mm solid nodule in a low-risk patient does not need short-interval PET or resection',
  'A 4-mm solid nodule in a low-risk patient does not need short-interval PET or resection is correct. Tiny smooth solid nodules in low-risk patients are overwhelmingly benign. Fleischner-style follow-up does not jump to PET, bronchoscopy, or resection at 4 mm. Incorrect alternatives: Those invasive steps are for larger or higher-risk lesions.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Metlay JP et al. Diagnosis and Treatment of Adults with Community-acquired Pneumonia. ATS/IDSA Guideline. Am J Respir Crit Care Med 2019","url":"https://pubmed.ncbi.nlm.nih.gov/31573350/"}]'::jsonb,
  'generated',
  'e31f9c734fb62ee33f7b94b960c961c723c6790cde3464dc6578bb956a3fcae7',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
