  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  3,
  'pulmonary',
  'pulmonary',
  'diagnosis',
  'Tension pneumothorax',
  'vignette',
  'A 22-year-old man is short of breath after central-line placement. Blood pressure is 78/50 mm Hg, neck veins are distended, breath sounds are absent on the right, and the trachea is deviated to the left.',
  'Which of the following is the most appropriate next action?',
  '{"options":["CT scan before any procedure","Needle decompression or finger thoracostomy of the right chest now","A fluid bolus as the only treatment","Albuterol","Antibiotics and observation"],"blueprintSystem":"pulmonary","taskCategory":"diagnosis","blueprintTopic":"Tension pneumothorax","kind":"vignette"}',
  'Needle decompression or finger thoracostomy of the right chest now',
  'Needle decompression or finger thoracostomy of the right chest now is correct. Hypotension, absent sounds, and tracheal deviation away from the silent side are tension pneumothorax. Decompress before imaging. Incorrect alternatives: A CT, fluids alone, a bronchodilator, and antibiotics delay a mechanical emergency.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"Metlay JP et al. Diagnosis and Treatment of Adults with Community-acquired Pneumonia. ATS/IDSA Guideline. Am J Respir Crit Care Med 2019","url":"https://pubmed.ncbi.nlm.nih.gov/31573350/"}]'::jsonb,
  'generated',
  'a2588e523193e42a85a01544c1dfae7506a602ed40085203a55ac94595f9bc5a',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
