  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'pulmonary',
  4,
  'pulmonary',
  'pulmonary',
  'prevention',
  'Lung cancer screening eligibility',
  'vignette',
  'A 58-year-old man smoked one pack daily from age 28 to 53 (25 pack-years) and quit 5 years ago. He has no symptoms. He asks about a screening CT.',
  'Which of the following is the most appropriate answer using current USPSTF lung-cancer screening rules?',
  '{"options":["He is ineligible because he quit","Annual low-dose CT is appropriate; he is 50 to 80 with at least 20 pack-years and quit within 15 years","A chest radiograph every 6 months instead","Sputum cytology only","No screening until he has hemoptysis"],"blueprintSystem":"pulmonary","taskCategory":"prevention","blueprintTopic":"Lung cancer screening eligibility","kind":"vignette"}',
  'Annual low-dose CT is appropriate; he is 50 to 80 with at least 20 pack-years and quit within 15 years',
  'Annual low-dose CT is appropriate; he is 50 to 80 with at least 20 pack-years and quit within 15 years is correct. USPSTF lung-cancer screening is annual low-dose CT for adults 50 to 80 with a 20 pack-year history who smoke or quit within 15 years. Quitting 5 years ago does not remove him. Incorrect alternatives: A chest radiograph, sputum cytology, and waiting for hemoptysis are not the screening test.',
  '["pance","PANCE-2025","pulmonary","pance-200-20261108-v1"]',
  '[{"label":"US Preventive Services Task Force. Screening for Lung Cancer. JAMA 2021","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/lung-cancer-screening"}]'::jsonb,
  'generated',
  '8344dd0d7c0a6be650e3552214243d319171a8578d45db000082d11f73c8bdb9',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
