  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  4,
  'gastrointestinal',
  'gastrointestinal',
  'pharmacotherapy',
  'C. difficile first drug',
  'vignette',
  'A 68-year-old woman has 8 watery stools a day, 2 days after finishing ceftriaxone. She is normotensive, creatinine is at baseline, and white count is 12,000/mm3. Stool toxin is positive. She is not pregnant.',
  'Which of the following is the most appropriate initial treatment?',
  '{"options":["Oral metronidazole","Oral vancomycin or fidaxomicin","Intravenous vancomycin alone","Loperamide as monotherapy","A cholestyramine binder as the only drug"],"blueprintSystem":"gastrointestinal","taskCategory":"pharmacotherapy","blueprintTopic":"C. difficile first drug","kind":"vignette"}',
  'Oral vancomycin or fidaxomicin',
  'Oral vancomycin or fidaxomicin is correct. The 2021 IDSA/SHEA update prefers fidaxomicin, with oral vancomycin an acceptable alternative, for an initial nonfulminant episode. Metronidazole is no longer first line. Incorrect alternatives: Intravenous vancomycin does not reach the colon lumen. Antimotility or a binder alone leaves the toxin-producing infection untreated.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"IDSA and SHEA. 2021 Focused Update Guidelines on Management of Clostridioides difficile Infection in Adults. Clin Infect Dis 2021","url":"https://pubmed.ncbi.nlm.nih.gov/34164674/"}]'::jsonb,
  'generated',
  '2a714fdde74975f3ff4096bd356e088dd0afbd6c6323d785e580fd3dc8d812e3',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  5,
  'gastrointestinal',
  'gastrointestinal',
  'pharmacotherapy',
  'Fulminant C. difficile',
  'vignette',
  'A 74-year-old man with toxin-positive C. difficile has a blood pressure of 80/50 mm Hg, a white count of 32,000/mm3, and an ileus. Creatinine has doubled. Oral intake is unreliable.',
  'Which of the following is the most appropriate antibiotic plan?',
  '{"options":["Oral metronidazole alone","High-dose oral vancomycin, plus intravenous metronidazole, and rectal vancomycin if ileus blocks enteral delivery","Intravenous vancomycin alone","Fidaxomicin and loperamide","No antibiotics until a colonoscopy"],"blueprintSystem":"gastrointestinal","taskCategory":"pharmacotherapy","blueprintTopic":"Fulminant C. difficile","kind":"vignette"}',
  'High-dose oral vancomycin, plus intravenous metronidazole, and rectal vancomycin if ileus blocks enteral delivery',
  'High-dose oral vancomycin, plus intravenous metronidazole, and rectal vancomycin if ileus blocks enteral delivery is correct. Fulminant disease (shock, ileus, or megacolon) needs vancomycin delivered into the gut and intravenous metronidazole because enteral delivery may fail. Intravenous vancomycin does not treat the colon. Incorrect alternatives: Metronidazole alone, antimotility with fidaxomicin, and waiting for colonoscopy are the wrong intensity.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"IDSA and SHEA. 2021 Focused Update Guidelines on Management of Clostridioides difficile Infection in Adults. Clin Infect Dis 2021","url":"https://pubmed.ncbi.nlm.nih.gov/34164674/"}]'::jsonb,
  'generated',
  'cdf0ea4fb7592b6cbdc0bf715701529b679a9fe3dcb66ee5339f60577d9d68a7',
  'pance-200-20261108-v1',
  'pending',
  false,
