  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  4,
  'gastrointestinal',
  'gastrointestinal',
  'labs',
  'Do not test formed stool for C. difficile',
  'vignette',
  'A 60-year-old man on a medicine ward has one formed stool. A nurse sends a C. difficile test because he took a cephalosporin last month. He has no abdominal pain or leukocytosis. The laboratory asks whether to run it.',
  'Which of the following is the most appropriate decision?',
  '{"options":["Run the test and treat if positive","Do not test a formed stool in a patient without diarrhea","Start oral vancomycin before the result","Repeat the test daily for a week","Give bezlotoxumab now"],"blueprintSystem":"gastrointestinal","taskCategory":"labs","blueprintTopic":"Do not test formed stool for C. difficile","kind":"vignette"}',
  'Do not test a formed stool in a patient without diarrhea',
  'Do not test a formed stool in a patient without diarrhea is correct. C. difficile testing is for unexplained new diarrhea, generally three or more unformed stools in 24 hours. A formed stool produces false positives from colonization. Incorrect alternatives: Treating colonization, daily repeats, and bezlotoxumab without an episode are not indicated.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"IDSA and SHEA. 2021 Focused Update Guidelines on Management of Clostridioides difficile Infection in Adults. Clin Infect Dis 2021","url":"https://pubmed.ncbi.nlm.nih.gov/34164674/"}]'::jsonb,
  'generated',
  '3193b8ff4b0e1a8d39d0d3f006db65538cd4eae3d8d833dd9fb5762524b68200',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
