) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  3,
  'gastrointestinal',
  'gastrointestinal',
  'prevention',
  'Colorectal screening start age',
  'vignette',
  'A 46-year-old woman with no symptoms, no family history of colorectal cancer, and no inflammatory bowel disease asks when screening should have started.',
  'Which of the following is the USPSTF starting age for average-risk screening?',
  '{"options":["35","45","50","60","65"],"blueprintSystem":"gastrointestinal","taskCategory":"prevention","blueprintTopic":"Colorectal screening start age","kind":"vignette"}',
  '45',
  '45 is correct. USPSTF recommends starting average-risk colorectal cancer screening at age 45 and continuing through 75. Incorrect alternatives: Ages 35, 50, 60, and 65 are not the current start.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"US Preventive Services Task Force. Screening for Colorectal Cancer. JAMA 2021","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/colorectal-cancer-screening"}]'::jsonb,
  'generated',
  '26178c70890a9be92b680a3ceafa23e12dc772433a3028e009fcdf07f432fbc2',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
