  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  4,
  'gastrointestinal',
  'gastrointestinal',
  'prevention',
  'CT colonography interval',
  'vignette',
  'A 52-year-old average-risk man completes a CT colonography that shows no polyps. He asks when to repeat that test if he stays with imaging rather than colonoscopy.',
  'Which of the following is the usual rescreen interval after a normal CT colonography?',
  '{"options":["1 year","3 years","5 years","10 years","Never again"],"blueprintSystem":"gastrointestinal","taskCategory":"prevention","blueprintTopic":"CT colonography interval","kind":"vignette"}',
  '5 years',
  '5 years is correct. A normal CT colonography is repeated in 5 years. Colonoscopy after a normal study is 10 years, and stool FIT is yearly. Those intervals are not interchangeable. Incorrect alternatives: Annual imaging, a 3-year cycle, a 10-year cycle, and stopping forever mis-time this modality.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"US Preventive Services Task Force. Screening for Colorectal Cancer. JAMA 2021","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/colorectal-cancer-screening"}]'::jsonb,
  'generated',
  '769454ce04fddeefa50b6b51c7a66480c6d3587e4d1b86e0f7adec8376f51e0a',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
