  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  4,
  'gastrointestinal',
  'gastrointestinal',
  'diagnosis',
  'Food impaction and eosinophilic esophagitis',
  'vignette',
  'A 26-year-old man with asthma has had a piece of steak stuck for 4 hours. He can handle secretions. He has had two prior impactions. He is hemodynamically stable.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Meat tenderizer by mouth","Endoscopic removal within 24 hours, and biopsy because recurrent impaction suggests eosinophilic esophagitis","A barium swallow while the bolus is in place","Discharge if glucagon fails","Blind nasogastric advancement"],"blueprintSystem":"gastrointestinal","taskCategory":"diagnosis","blueprintTopic":"Food impaction and eosinophilic esophagitis","kind":"vignette"}',
  'Endoscopic removal within 24 hours, and biopsy because recurrent impaction suggests eosinophilic esophagitis',
  'Endoscopic removal within 24 hours, and biopsy because recurrent impaction suggests eosinophilic esophagitis is correct. An esophageal food bolus is removed endoscopically, urgently if he cannot handle secretions and within 24 hours otherwise. Recurrent impaction in a young atopic man is eosinophilic esophagitis until biopsies say otherwise. Incorrect alternatives: Tenderizer, barium on top of a bolus, discharge after failed glucagon, and blind pushing are unsafe.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'a2c23aade6d3d369f0ac9440aae5aeea6435c73d940d4c99e2f0f695145e4458',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
