  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  5,
  'gastrointestinal',
  'gastrointestinal',
  'pharmacotherapy',
  'Azathioprine pretreatment testing',
  'vignette',
  'A 30-year-old woman with steroid-dependent Crohn disease is about to start azathioprine. Blood counts and liver tests are normal. She takes no allopurinol.',
  'Which of the following tests should be done before the first dose?',
  '{"options":["Dihydropyrimidine dehydrogenase genotype","TPMT activity or genotype, and NUDT15 genotype","HLA-B*5701","G6PD activity only","Serum tryptase"],"blueprintSystem":"gastrointestinal","taskCategory":"pharmacotherapy","blueprintTopic":"Azathioprine pretreatment testing","kind":"vignette"}',
  'TPMT activity or genotype, and NUDT15 genotype',
  'TPMT activity or genotype, and NUDT15 genotype is correct. Low TPMT or a NUDT15 variant can cause life-threatening myelosuppression from thiopurines. Both are checked before starting, especially because NUDT15 risk is not limited to one ancestry. Incorrect alternatives: DPYD is for fluorouracil. HLA-B*5701 is for abacavir. G6PD and tryptase do not dose a thiopurine.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '464b75d8b501f611b9bde73ac4b32161e42f9b298d614c4088cd5a55843a29e5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
