  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  5,
  'gastrointestinal',
  'gastrointestinal',
  'diagnosis',
  'Mesenteric ischemia pain out of proportion',
  'vignette',
  'A 78-year-old woman with atrial fibrillation not on anticoagulation has 3 hours of severe diffuse abdominal pain. The abdomen is soft. Lactate is 5 mmol/L. Bowel sounds are present.',
  'Which of the following is the most appropriate next imaging?',
  '{"options":["Right-upper-quadrant ultrasound only","CT angiography of the abdomen","Plain films as the definitive test","A HIDA scan","Observation because the abdomen is soft"],"blueprintSystem":"gastrointestinal","taskCategory":"diagnosis","blueprintTopic":"Mesenteric ischemia pain out of proportion","kind":"vignette"}',
  'CT angiography of the abdomen',
  'CT angiography of the abdomen is correct. Pain out of proportion to a soft examination, atrial fibrillation, and a rising lactate are acute mesenteric ischemia until angiography excludes an embolus. A soft abdomen does not rule it out early. Incorrect alternatives: Ultrasound, HIDA, and plain films look for other diseases and will miss an occluded SMA. Observation wastes bowel.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '3a34a3a67e57cccc6e42de90915c8a7d7c5f9d2635a732f72d8d8b4da5dd0119',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
