) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  4,
  'gastrointestinal',
  'gastrointestinal',
  'diagnosis',
  'Gallstone pancreatitis admission',
  'vignette',
  'A 48-year-old woman has epigastric pain to the back, lipase 4 times normal, and ALT 310 U/L. She is not hypoxic, creatinine is normal, and she has no SIRS. Ultrasound shows stones and no ductal dilation.',
  'Which of the following is the most appropriate early plan?',
  '{"options":["Nothing by mouth for a week","Pain control, early oral feeding as tolerated, and a plan for cholecystectomy this admission","Immediate ERCP in the absence of cholangitis or a persistent stone","Antibiotics for 14 days","Pancreatic enzyme supplements"],"blueprintSystem":"gastrointestinal","taskCategory":"diagnosis","blueprintTopic":"Gallstone pancreatitis admission","kind":"vignette"}',
  'Pain control, early oral feeding as tolerated, and a plan for cholecystectomy this admission',
  'Pain control, early oral feeding as tolerated, and a plan for cholecystectomy this admission is correct. Mild gallstone pancreatitis is fed early and the gallbladder is removed during the same admission to prevent recurrence. ERCP is for cholangitis or a stone that is still blocking the duct. Incorrect alternatives: A week of fasting, routine ERCP, a long antibiotic course, and enzyme supplements are not the mild-disease plan.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'e681d19010f8e646264d4ab715caaf9ca669b9e8f282972668eca0ab0238a8f8',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
