  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  4,
  'gastrointestinal',
  'gastrointestinal',
  'pharmacotherapy',
  'H. pylori test of cure',
  'vignette',
  'A 40-year-old man finishes 14 days of bismuth quadruple therapy for Helicobacter pylori. He feels well. He asks if a repeat test is needed.',
  'Which of the following is the most appropriate test-of-cure plan?',
  '{"options":["No test, because symptoms resolved","Urea breath test or stool antigen at least 4 weeks after antibiotics and after holding a PPI","Serology in 1 week","A PPI the morning of a breath test","Repeat endoscopy the next day"],"blueprintSystem":"gastrointestinal","taskCategory":"pharmacotherapy","blueprintTopic":"H. pylori test of cure","kind":"vignette"}',
  'Urea breath test or stool antigen at least 4 weeks after antibiotics and after holding a PPI',
  'Urea breath test or stool antigen at least 4 weeks after antibiotics and after holding a PPI is correct. Cure should be confirmed. Serology stays positive. Antibiotics and PPIs cause false-negative breath and stool tests, so the test waits about 4 weeks off antibiotics and an appropriate PPI hold. Incorrect alternatives: Symptom resolution, early serology, testing on a PPI, and next-day endoscopy do not document eradication.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '68ed43a85cdcf9231540ef317defa89122f48ead37a0afabef1a9a59337274f5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  5,
  'gastrointestinal',
  'gastrointestinal',
  'diagnosis',
  'Spontaneous bacterial peritonitis',
  'vignette',
  'A 59-year-old man with cirrhosis and ascites has fever and new confusion. Paracentesis shows 320 neutrophils/mm3 and a gram stain with no organisms yet. He has no surgical abdomen.',
  'Which of the following is the most appropriate next treatment?',
  '{"options":["Wait for the culture before any antibiotic","Albumin consideration and a third-generation cephalosporin now","Oral metronidazole","Vancomycin only","Large-volume paracentesis without antibiotics"],"blueprintSystem":"gastrointestinal","taskCategory":"diagnosis","blueprintTopic":"Spontaneous bacterial peritonitis","kind":"vignette"}',
  'Albumin consideration and a third-generation cephalosporin now',
  'Albumin consideration and a third-generation cephalosporin now is correct. Ascitic neutrophils at or above 250 define spontaneous bacterial peritonitis and treatment starts immediately. A cephalosporin such as cefotaxime covers the usual organisms. Albumin is considered in patients at risk of kidney injury. Incorrect alternatives: Waiting on culture, metronidazole, vancomycin monotherapy, and drainage without antibiotics miss or delay the infection.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'b27e64bd449ec712323a569af5f2e5feb1536a830f4c42f4b11c7d9b55041524',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'gastrointestinal',
  3,
  'gastrointestinal',
  'gastrointestinal',
  'diagnosis',
  'Esophageal candidiasis and HIV',
  'vignette',
  'A 34-year-old man has odynophagia and oral thrush. He has never had an HIV test. He can swallow liquids.',
  'Which of the following is the most appropriate paired plan?',
  '{"options":["Oral fluconazole and an HIV test","Intravenous amphotericin as the first drug","Acid suppression only","Antibiotics for streptococcal pharyngitis","No HIV test because thrush is always local"],"blueprintSystem":"gastrointestinal","taskCategory":"diagnosis","blueprintTopic":"Esophageal candidiasis and HIV","kind":"vignette"}',
  'Oral fluconazole and an HIV test',
  'Oral fluconazole and an HIV test is correct. Odynophagia plus thrush is esophageal candidiasis until proved otherwise, and in an adult it is a reason to test for HIV. Fluconazole is first line when he can swallow. Incorrect alternatives: Amphotericin is for refractory disease. Acid suppression, bacterial antibiotics, and skipping the HIV test leave the diagnosis and the immunodeficiency unexamined.',
  '["pance","PANCE-2025","gastrointestinal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'd7ab02cb5f3ea88e8347b7052b29e3a0d5cb7cd4c3579e671a40a9b17eb34e58',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  5,
  'musculoskeletal',
  'musculoskeletal',
  'diagnosis',
  'Septic arthritis versus gout',
  'vignette',
  'A 62-year-old man with a prosthetic knee has fever and a hot swollen joint. Synovial fluid shows 70,000 white cells with 90% neutrophils. Crystals are not seen. Gram stain is negative.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Colchicine only, because a negative Gram stain excludes infection","Empiric antibiotics and orthopedic drainage; a negative Gram stain does not exclude septic arthritis","Allopurinol today","Intra-articular steroid as the only treatment","Discharge on naproxen"],"blueprintSystem":"musculoskeletal","taskCategory":"diagnosis","blueprintTopic":"Septic arthritis versus gout","kind":"vignette"}',
  'Empiric antibiotics and orthopedic drainage; a negative Gram stain does not exclude septic arthritis',
  'Empiric antibiotics and orthopedic drainage; a negative Gram stain does not exclude septic arthritis is correct. A prosthetic joint with fever and a very high synovial count is septic until cultures return. Gram stain misses many infections. Crystals, if later found, do not fully exclude co-infection in this setting. Incorrect alternatives: Colchicine, allopurinol, a steroid injection, and naproxen alone delay source control.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'f66cba167f6b1b21ed30d3393c4de9a531a6c881da438944731a4822178b49b3',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  4,
  'musculoskeletal',
  'musculoskeletal',
  'pharmacotherapy',
  'Allopurinol during a flare',
  'vignette',
  'A 55-year-old man is on day 2 of a first gout flare of the big toe. Urate is 8.4 mg/dL. He has CKD stage 3. He is not on urate-lowering therapy. The flare is being treated with low-dose colchicine.',
  'Which of the following is the most appropriate urate-lowering decision?',
  '{"options":["Start allopurinol at 300 mg today and stop colchicine","Start allopurinol at a low dose while the colchicine is continued, then titrate","Probenecid is preferred because the eGFR is reduced","Pegloticase for a first flare","No urate-lowering therapy is ever indicated after a flare"],"blueprintSystem":"musculoskeletal","taskCategory":"pharmacotherapy","blueprintTopic":"Allopurinol during a flare","kind":"vignette"}',
  'Start allopurinol at a low dose while the colchicine is continued, then titrate',
  'Start allopurinol at a low dose while the colchicine is continued, then titrate is correct. Current gout guidance allows urate-lowering therapy during a flare when anti-inflammatory coverage is already in place. The dose starts low in CKD and is titrated to the urate target. Colchicine is not stopped. Incorrect alternatives: A full 300 mg start, probenecid when the eGFR is reduced, pegloticase for a first flare, and never treating hyperuricemia are the incorrect choices.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '3e89b6a96dc1dc956cda502a4ffb4bbd3f58334e7ba23bb4138177467d5c5766',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  4,
  'musculoskeletal',
  'musculoskeletal',
  'pharmacotherapy',
  'Do not stop allopurinol during a flare',
  'vignette',
  'A 60-year-old man has been stable on allopurinol 300 mg with a urate of 5.2 mg/dL. He has a new podagra flare after a steak dinner. Kidney function is unchanged.',
  'Which of the following is the most appropriate allopurinol instruction?',
  '{"options":["Stop allopurinol until the flare ends","Continue allopurinol and treat the flare","Double allopurinol tonight","Switch to probenecid today","Add a second xanthine oxidase inhibitor"],"blueprintSystem":"musculoskeletal","taskCategory":"pharmacotherapy","blueprintTopic":"Do not stop allopurinol during a flare","kind":"vignette"}',
  'Continue allopurinol and treat the flare',
  'Continue allopurinol and treat the flare is correct. Once urate-lowering therapy is established, it is continued through a flare. Stopping it causes the urate to swing and invites more attacks. Incorrect alternatives: Doubling the dose, swapping to probenecid, or stacking two xanthine oxidase inhibitors is not how a single flare on a therapeutic urate is handled.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '9f416b49eeac13089f81e120a063b79af3792202913c1d7c78a4d03976bb4c28',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
