  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  3,
  'musculoskeletal',
  'musculoskeletal',
  'intervention',
  'Open fracture antibiotics and time',
  'vignette',
  'A 24-year-old man has a tibial fracture with bone visible through a 3-cm wound. Distal pulses are present. Tetanus status is unknown. The operating room is being set up.',
  'Which of the following is the most appropriate immediate addition?',
  '{"options":["Wait for the operating room to give the first antibiotic","A first-generation cephalosporin now, tetanus prophylaxis, and operative debridement","Oral cephalexin at home tonight","A steroid pack","Primary closure in the emergency department without debridement"],"blueprintSystem":"musculoskeletal","taskCategory":"intervention","blueprintTopic":"Open fracture antibiotics and time","kind":"vignette"}',
  'A first-generation cephalosporin now, tetanus prophylaxis, and operative debridement',
  'A first-generation cephalosporin now, tetanus prophylaxis, and operative debridement is correct. Open fractures need early antibiotics, tetanus update, and surgical debridement. The first antibiotic dose should not wait for the incision. Incorrect alternatives: Home oral therapy, steroids, and closure without a washout increase infection.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '425416012318de108c6477735dec9e982669fd2015a53e5970a33d69b75e61b0',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
