  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  5,
  'musculoskeletal',
  'musculoskeletal',
  'diagnosis',
  'Compartment syndrome',
  'vignette',
  'A 19-year-old man has a tibial fracture in a cast. He has pain out of proportion, pain on passive toe stretch, and a tense compartment. Pulses are still palpable.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Reassure him because pulses are present","Remove the cast and perform fasciotomy; do not wait for an absent pulse","Elevation above the heart and recheck in 6 hours","A nerve-conduction study tomorrow","Anticoagulation"],"blueprintSystem":"musculoskeletal","taskCategory":"diagnosis","blueprintTopic":"Compartment syndrome","kind":"vignette"}',
  'Remove the cast and perform fasciotomy; do not wait for an absent pulse',
  'Remove the cast and perform fasciotomy; do not wait for an absent pulse is correct. Compartment syndrome is a clinical diagnosis. Pulses are often preserved until late. Passive stretch pain and a tense compartment mean the compartment is opened now. Incorrect alternatives: Waiting on the pulse, elevation alone, next-day nerve studies, and anticoagulation lose muscle.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'd9fd958f1f1ecc5ad0853a1521e6cc0f57e1c5d3acc0ff56a14aa392103b30f4',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
