  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  5,
  'musculoskeletal',
  'musculoskeletal',
  'diagnosis',
  'Cauda equina',
  'vignette',
  'A 48-year-old man has severe low-back pain, bilateral leg weakness, saddle numbness, and has not voided in 10 hours. Post-void residual is 450 mL.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Six weeks of physical therapy before imaging","Emergency MRI and surgical consultation","A plain film as the definitive test","Oral prednisone and clinic follow-up","Epidural steroid tonight in the clinic"],"blueprintSystem":"musculoskeletal","taskCategory":"diagnosis","blueprintTopic":"Cauda equina","kind":"vignette"}',
  'Emergency MRI and surgical consultation',
  'Emergency MRI and surgical consultation is correct. Saddle anesthesia, bilateral deficits, and urinary retention are cauda equina until imaging and a surgeon say otherwise. Hours matter. Incorrect alternatives: Routine therapy, plain films, steroids, and a clinic injection delay decompression.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '70834ce9b63b8badd958263a174eb921fa6e2333d5297b9b2689939ff525aeb5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
