  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  4,
  'musculoskeletal',
  'musculoskeletal',
  'pharmacotherapy',
  'Osteoporosis after a hip fracture',
  'vignette',
  'A 78-year-old woman has a fragility hip fracture. Vitamin D is replete. eGFR is 62 mL/min/1.73 m2. She has no esophageal stricture. T-score is not back yet.',
  'Which of the following is the most appropriate bone plan?',
  '{"options":["Calcium alone","Start an antiresorptive agent; a fragility hip fracture is an indication even before the T-score returns","Estrogen as the first drug","Calcitonin as preferred long-term therapy","No treatment because she is over 75"],"blueprintSystem":"musculoskeletal","taskCategory":"pharmacotherapy","blueprintTopic":"Osteoporosis after a hip fracture","kind":"vignette"}',
  'Start an antiresorptive agent; a fragility hip fracture is an indication even before the T-score returns',
  'Start an antiresorptive agent; a fragility hip fracture is an indication even before the T-score returns is correct. A hip fracture from standing height is osteoporosis treatment territory. An oral bisphosphonate is reasonable with a safe esophagus and adequate GFR, after calcium and vitamin D are addressed. Incorrect alternatives: Calcium alone, estrogen first, long-term calcitonin, and age as a reason to withhold treatment are not the plan.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '71f517e11248d41cec9dbe294c86500927aaef30b9aab100b319f43bc17d9773',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  5,
  'musculoskeletal',
  'musculoskeletal',
  'pharmacotherapy',
  'Denosumab holiday warning',
  'vignette',
  'A 75-year-old woman has taken denosumab every 6 months for 3 years. She feels well and wants to ''take a year off'' with no replacement drug. Her last dose was due last week.',
  'Which of the following is the most appropriate advice?',
  '{"options":["A drug holiday is as safe as with a bisphosphonate","Do not stop denosumab without a plan; stopping is followed by rebound vertebral fractures","Stop forever because 3 years is the maximum","Switch to estrogen","Skip the dose and recheck in 2 years"],"blueprintSystem":"musculoskeletal","taskCategory":"pharmacotherapy","blueprintTopic":"Denosumab holiday warning","kind":"vignette"}',
  'Do not stop denosumab without a plan; stopping is followed by rebound vertebral fractures',
  'Do not stop denosumab without a plan; stopping is followed by rebound vertebral fractures is correct. Unlike bisphosphonates, denosumab does not stay in bone. Interrupting it without another antiresorptive can cause rapid bone loss and multiple vertebral fractures. Incorrect alternatives: A casual holiday, a hard stop at 3 years, estrogen, and a 2-year gap are unsafe.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '8ea082d1ebb5d6c71a02c28fbe9314e96a4e0994fd4ae232f152e23fdcca15bd',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
