  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  3,
  'musculoskeletal',
  'musculoskeletal',
  'diagnosis',
  'Slipped capital femoral epiphysis',
  'vignette',
  'A 12-year-old boy with a BMI of 33 kg/m2 has 3 weeks of limp and knee pain. Hip internal rotation is limited. He is afebrile. Knee films were normal.',
  'Which of the following is the most appropriate next imaging?',
  '{"options":["Repeat knee films only","Pelvis and frog-leg lateral hip films","Bone scan as the first test","Lumbar puncture","No imaging because the knee film was normal"],"blueprintSystem":"musculoskeletal","taskCategory":"diagnosis","blueprintTopic":"Slipped capital femoral epiphysis","kind":"vignette"}',
  'Pelvis and frog-leg lateral hip films',
  'Pelvis and frog-leg lateral hip films is correct. Knee pain in an adolescent with obesity and limited hip rotation is a slipped capital femoral epiphysis until the hip is filmed, including a lateral view. The slip is pinned, and the other hip is examined. Incorrect alternatives: More knee films, a bone scan first, a lumbar puncture, and no imaging miss the hip.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'a823889bc100083fe15599e1f51085119b1ed6953b6739f79de50ea265e19a33',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  4,
  'musculoskeletal',
  'musculoskeletal',
  'diagnosis',
  'Septic hip versus transient synovitis',
  'vignette',
  'A 5-year-old boy has fever of 39 C, refuses to bear weight, and holds the hip flexed and externally rotated. CRP and white count are high. Ultrasound shows an effusion.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Ibuprofen and recheck in 3 days","Urgent aspiration of the hip","A week of observation","Oral cephalexin without aspiration","Reassurance that fever excludes infection"],"blueprintSystem":"musculoskeletal","taskCategory":"diagnosis","blueprintTopic":"Septic hip versus transient synovitis","kind":"vignette"}',
  'Urgent aspiration of the hip',
  'Urgent aspiration of the hip is correct. Fever, non-weight-bearing, and an effusion are septic arthritis until the fluid is examined. Aspiration both diagnoses and starts source control. Transient synovitis is the diagnosis of exclusion in a well child. Incorrect alternatives: Delayed ibuprofen, empiric oral antibiotics without fluid, and reassurance leave a hip joint at risk.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '9bae8b294700eae6161ac5e96d632bd8385d1502c452b52e45260e7830a837f5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  3,
  'musculoskeletal',
  'musculoskeletal',
  'pharmacotherapy',
  'Bisphosphonate acute-phase reaction',
  'vignette',
  'A 70-year-old woman had her first zoledronic acid infusion yesterday. Today she has fever of 38.1 C, myalgias, and fatigue. Calcium and creatinine are unchanged. She looks well.',
  'Which of the following is the most appropriate management?',
  '{"options":["Acetaminophen and reassurance that the reaction is self-limited","Stop all future osteoporosis treatment","Blood cultures and vancomycin","Intravenous calcium","A prednisone taper as required therapy"],"blueprintSystem":"musculoskeletal","taskCategory":"pharmacotherapy","blueprintTopic":"Bisphosphonate acute-phase reaction","kind":"vignette"}',
  'Acetaminophen and reassurance that the reaction is self-limited',
  'Acetaminophen and reassurance that the reaction is self-limited is correct. A first intravenous bisphosphonate often causes a transient cytokine reaction. It is treated symptomatically and does not recur as strongly with later doses. Incorrect alternatives: Abandoning therapy, empiric vancomycin, calcium, and mandatory steroids overtreat a known reaction.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'a9481f1ea59a78fc48b8a140f8e2159f895d6dfda2151100c7a59fc41f0d7155',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'musculoskeletal',
  3,
  'musculoskeletal',
  'musculoskeletal',
  'prevention',
  'Fall prevention is exercise',
  'vignette',
  'A 76-year-old woman who lives at home fell once last year without injury. Vitamin D is normal. She asks for a pill to prevent falls.',
  'Which of the following is the intervention with the best support?',
  '{"options":["High-dose vitamin D because her level is normal","Balance and strength exercise","A bedtime benzodiazepine","Hip protectors as the only step","Bed rest"],"blueprintSystem":"musculoskeletal","taskCategory":"prevention","blueprintTopic":"Fall prevention is exercise","kind":"vignette"}',
  'Balance and strength exercise',
  'Balance and strength exercise is correct. Exercise that trains balance and strength reduces falls in community-dwelling older adults. Vitamin D does not prevent falls when the level is already normal, and sedatives increase them. Incorrect alternatives: Extra vitamin D, a benzodiazepine, hip protectors alone, and bed rest are not the effective plan.',
  '["pance","PANCE-2025","musculoskeletal","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '630648502302be81ed0bed494bfc16e0f914db96dbc4e8e5ac82b795134613f9',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'neurologic',
  5,
  'neurologic',
  'neurologic',
  'pharmacotherapy',
  'tPA exclusions that are outdated',
  'vignette',
  'A 68-year-old man has a sudden right hemiparesis that began 90 minutes ago. Glucose is 140 mg/dL. CT shows no hemorrhage. NIHSS is 8. He had a mild concussion 2 years ago and takes aspirin. Blood pressure is 170/95 mm Hg.',
  'Which of the following is the most appropriate thrombolysis decision?',
  '{"options":["Withhold alteplase because he takes aspirin","Give alteplase; aspirin use and a remote concussion are not exclusions, and the pressure can be lowered under 185/110","Withhold alteplase because the NIHSS is under 10","Give heparin instead","Observe for 24 hours before any reperfusion"],"blueprintSystem":"neurologic","taskCategory":"pharmacotherapy","blueprintTopic":"tPA exclusions that are outdated","kind":"vignette"}',
  'Give alteplase; aspirin use and a remote concussion are not exclusions, and the pressure can be lowered under 185/110',
  'Give alteplase; aspirin use and a remote concussion are not exclusions, and the pressure can be lowered under 185/110 is correct. Within 4.5 hours, a disabling deficit and a negative CT are treated with alteplase if blood pressure is brought under 185/110. Single antiplatelet therapy and old minor head trauma are not reasons to withhold. Incorrect alternatives: Heparin is not acute ischemic-stroke treatment. Waiting a day and using NIHSS under 10 as a veto miss the window.',
  '["pance","PANCE-2025","neurologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'c9563594e45a3e0bdac34630ff5a0ee42865b95ebb3656ff806a05c565cbbd9d',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'neurologic',
  5,
  'neurologic',
  'neurologic',
  'intervention',
  'Thrombectomy window is not the same as tPA',
  'vignette',
  'A 72-year-old woman was last known well 10 hours ago. She has a severe left MCA syndrome. CT angiography shows an M1 occlusion and CT perfusion shows a small core with a large penumbra. She is not an alteplase candidate because of the time.',
  'Which of the following is the most appropriate next step?',
  '{"options":["No reperfusion is possible after 4.5 hours","Urgent endovascular consultation for thrombectomy","Aspirin only, because imaging does not change the clock","Hemicraniectomy as the first step while she is still following commands","Intravenous heparin"],"blueprintSystem":"neurologic","taskCategory":"intervention","blueprintTopic":"Thrombectomy window is not the same as tPA","kind":"vignette"}',
  'Urgent endovascular consultation for thrombectomy',
  'Urgent endovascular consultation for thrombectomy is correct. Selected patients with large-vessel occlusion and favorable perfusion imaging can benefit from thrombectomy well beyond the 4.5-hour alteplase window, out toward 16 to 24 hours. The clocks are different. Incorrect alternatives: Stopping at 4.5 hours, aspirin alone, early decompression in a patient who is still a thrombectomy candidate, and heparin are the wrong sequence.',
  '["pance","PANCE-2025","neurologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '3b0e5687a66dbb37edb4f73e0f149cddabef684520c97c9ca0226b8cd6b2de3b',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'neurologic',
  4,
  'neurologic',
  'neurologic',
  'pharmacotherapy',
  'Secondary prevention after TIA',
  'vignette',
  'A 66-year-old man had a 20-minute episode of aphasia yesterday that has resolved. MRI shows a small cortical diffusion lesion. He is in sinus rhythm, vessels are not critically stenosed, and a swallow screen is fine. LDL is 110 mg/dL.',
  'Which of the following is the most appropriate long-term antithrombotic plan?',
  '{"options":["Warfarin for sinus rhythm","Antiplatelet therapy and a high-intensity statin","Alteplase now, a day later","No drug because the symptoms resolved","Dual antiplatelet therapy for life"],"blueprintSystem":"neurologic","taskCategory":"pharmacotherapy","blueprintTopic":"Secondary prevention after TIA","kind":"vignette"}',
  'Antiplatelet therapy and a high-intensity statin',
  'Antiplatelet therapy and a high-intensity statin is correct. A resolved focal deficit with a diffusion lesion is an ischemic stroke, even if the bedside deficit has cleared. Long-term care is an antiplatelet and high-intensity statin, not anticoagulation, unless atrial fibrillation or another indication appears. Incorrect alternatives: Warfarin for sinus rhythm, late thrombolysis, no treatment, and lifelong dual therapy are not the plan.',
  '["pance","PANCE-2025","neurologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '32dcc0e4ba4d123155c2042d62c90f705d25105172c703c55ccb1caa72746b0b',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
