  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'neurologic',
  5,
  'neurologic',
  'neurologic',
  'diagnosis',
  'Subarachnoid hemorrhage with a negative CT',
  'vignette',
  'A 45-year-old woman has a sudden worst-ever headache that peaked in seconds, 8 hours ago. Noncontrast CT is negative. She is alert. Neck is stiff.',
  'Which of the following is the most appropriate next test?',
  '{"options":["Discharge, because CT is 100% sensitive all day","Lumbar puncture looking for xanthochromia or red cells that do not clear","MRI of the neck only","Sumatriptan and discharge","Outpatient neurology in 2 weeks"],"blueprintSystem":"neurologic","taskCategory":"diagnosis","blueprintTopic":"Subarachnoid hemorrhage with a negative CT","kind":"vignette"}',
  'Lumbar puncture looking for xanthochromia or red cells that do not clear',
  'Lumbar puncture looking for xanthochromia or red cells that do not clear is correct. CT sensitivity for subarachnoid blood falls with time. A thunderclap headache and a negative CT still need a lumbar puncture. Xanthochromia or persistent red cells support the diagnosis. Incorrect alternatives: Discharge, a neck MRI as the only test, a triptan, and a 2-week delay miss an aneurysmal bleed.',
  '["pance","PANCE-2025","neurologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '4ef4488f5a02ed291987153305ce5637b457d87fc3bd008ebf42a3ce3e061088',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
