  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'neurologic',
  4,
  'neurologic',
  'neurologic',
  'pharmacotherapy',
  'Status epilepticus benzodiazepine first',
  'vignette',
  'A 30-year-old man has been seizing for 6 minutes in the emergency department. Glucose is 100 mg/dL. He has intravenous access. This is not a first brief seizure that has already stopped.',
  'Which of the following is the most appropriate first drug?',
  '{"options":["Phenytoin before any benzodiazepine","Intravenous lorazepam","Oral levetiracetam only","Observation until 20 minutes","A paralyzing agent without an EEG or sedative"],"blueprintSystem":"neurologic","taskCategory":"pharmacotherapy","blueprintTopic":"Status epilepticus benzodiazepine first","kind":"vignette"}',
  'Intravenous lorazepam',
  'Intravenous lorazepam is correct. Ongoing status is treated first with a benzodiazepine. A longer-acting antiseizure drug follows, but it does not replace the benzodiazepine. Incorrect alternatives: Starting with phenytoin, an oral-only drug, waiting to 20 minutes, or paralyzing without sedation hides or delays the seizure.',
  '["pance","PANCE-2025","neurologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '43e02724a9e3c70c6b2eb8c7e180bc6d32626e685731166eed172f3f7875b71f',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'neurologic',
  5,
  'neurologic',
  'neurologic',
  'diagnosis',
  'Giant-cell arteritis vision',
  'vignette',
  'A 76-year-old woman has a new temporal headache, jaw fatigue with chewing, and this morning a curtain over the right eye that has partly cleared. ESR is 80 mm/h. The right temple is tender.',
  'Which of the following is the most appropriate immediate treatment?',
  '{"options":["Schedule a biopsy and start steroids only after the result","High-dose corticosteroids now, and arrange a temporal-artery biopsy","Sumatriptan","Aspirin as the only drug","Observation because the curtain cleared"],"blueprintSystem":"neurologic","taskCategory":"diagnosis","blueprintTopic":"Giant-cell arteritis vision","kind":"vignette"}',
  'High-dose corticosteroids now, and arrange a temporal-artery biopsy',
  'High-dose corticosteroids now, and arrange a temporal-artery biopsy is correct. Transient monocular vision loss with cranial symptoms is giant-cell arteritis until proved otherwise. Steroids start immediately to protect the other eye. Biopsy follows and remains useful for days after steroids begin. Incorrect alternatives: Waiting on histology, a triptan, aspirin alone, and observation risk bilateral blindness.',
  '["pance","PANCE-2025","neurologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '898bfa4626067f1044ff83a074acf84b90be3ef01fbc9e1d6e2cca9f01960919',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
