  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'neurologic',
  3,
  'neurologic',
  'neurologic',
  'diagnosis',
  'Bell palsy versus stroke',
  'vignette',
  'A 40-year-old man woke with a droop of the entire left face, including the forehead, and cannot close the left eye. Arm strength and speech are normal. There is no rash.',
  'Which of the following is the most appropriate initial plan?',
  '{"options":["Alteplase, because every facial droop is a stroke","Eye lubrication and a short course of steroids; forehead involvement points to a peripheral seventh nerve","Antibiotics for otitis","Anticoagulation","No eye care is needed"],"blueprintSystem":"neurologic","taskCategory":"diagnosis","blueprintTopic":"Bell palsy versus stroke","kind":"vignette"}',
  'Eye lubrication and a short course of steroids; forehead involvement points to a peripheral seventh nerve',
  'Eye lubrication and a short course of steroids; forehead involvement points to a peripheral seventh nerve is correct. A stroke spares the forehead because of bilateral cortical innervation. Complete hemifacial weakness is peripheral. The cornea is protected, and steroids are started early. Incorrect alternatives: Thrombolysis, antibiotics, anticoagulation, and ignoring the eye are mismatches.',
  '["pance","PANCE-2025","neurologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'f7003c4bb6bdaa84e916e970ed65aa4d353624619bd842daf5c8907526676250',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'neurologic',
  4,
  'neurologic',
  'neurologic',
  'pharmacotherapy',
  'Migraine in vascular disease',
  'vignette',
  'A 52-year-old woman with coronary stents has monthly migraines. She asks for a triptan because a friend uses one. She has no chest pain today.',
  'Which of the following is the most appropriate advice?',
  '{"options":["A triptan is preferred because of her stents","Avoid triptans; use a nonvasoconstricting acute treatment","Ergotamine is safer than a triptan here","Daily opioids","Propranolol is contraindicated in anyone with migraine"],"blueprintSystem":"neurologic","taskCategory":"pharmacotherapy","blueprintTopic":"Migraine in vascular disease","kind":"vignette"}',
  'Avoid triptans; use a nonvasoconstricting acute treatment',
  'Avoid triptans; use a nonvasoconstricting acute treatment is correct. Triptans and ergots constrict vessels and are avoided in coronary disease. Other acute options, and prevention if attacks are frequent, do not rely on that mechanism. Incorrect alternatives: Choosing a triptan or an ergot because of stents, daily opioids, and a blanket ban on beta blockers are incorrect.',
  '["pance","PANCE-2025","neurologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '670635e37a483ee15066bf00161d7fdfc7040a0d5fc508930198982b3f3b6abe',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
