  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'neurologic',
  5,
  'neurologic',
  'neurologic',
  'diagnosis',
  'Epidural abscess risk',
  'vignette',
  'A 60-year-old man who injects drugs has fever, midline back pain, and new leg weakness. White count is 18,000/mm3.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Plain films and a week of NSAIDs","MRI of the spine and antibiotics after cultures, without waiting on the MRI if he is septic","Oral cephalexin","Physical therapy","A steroid epidural"],"blueprintSystem":"neurologic","taskCategory":"diagnosis","blueprintTopic":"Epidural abscess risk","kind":"vignette"}',
  'MRI of the spine and antibiotics after cultures, without waiting on the MRI if he is septic',
  'MRI of the spine and antibiotics after cultures, without waiting on the MRI if he is septic is correct. Fever, focal back pain, and a deficit in a person who injects drugs is a spinal epidural abscess until MRI excludes it. Antibiotics and a surgeon are not delayed for a plain film. Incorrect alternatives: NSAIDs, oral cephalexin, therapy, and an epidural injection spread or miss the abscess.',
  '["pance","PANCE-2025","neurologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'de4e263ab6c013576bb49e27879217062781bffe3ea9ff2a2beae26ed221b81e',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
