  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'neurologic',
  4,
  'neurologic',
  'neurologic',
  'pharmacotherapy',
  'Myasthenia crisis trigger',
  'vignette',
  'A 35-year-old woman with myasthenia gravis is in crisis with a negative inspiratory force that is falling. A colleague suggests gentamicin for a urinary isolate that is also sensitive to other drugs.',
  'Which of the following is the most appropriate antibiotic decision?',
  '{"options":["Use gentamicin because aminoglycosides are safe in myasthenia","Choose an agent that does not block the neuromuscular junction","Give succinylcholine electively for comfort","Add a fluoroquinolone and a macrolide together","Stop pyridostigmine forever"],"blueprintSystem":"neurologic","taskCategory":"pharmacotherapy","blueprintTopic":"Myasthenia crisis trigger","kind":"vignette"}',
  'Choose an agent that does not block the neuromuscular junction',
  'Choose an agent that does not block the neuromuscular junction is correct. Aminoglycosides, fluoroquinolones, and macrolides can worsen myasthenia. A sensitive alternative that is not on that list is chosen, and the crisis itself may need intravenous immunoglobulin or plasma exchange plus ventilatory support. Incorrect alternatives: Gentamicin, stacking two offending classes, elective succinylcholine, and stopping cholinesterase inhibition are harmful.',
  '["pance","PANCE-2025","neurologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '7a99bd59e4a7a13acc7a9906fd9c2faf66cd0c5920208fdf4bb0c7c51e70d17d',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'infectious-diseases',
  4,
  'infectious-diseases',
  'infectious-diseases',
  'pharmacotherapy',
  'Nonsevere C. difficile is not metronidazole',
  'vignette',
  'A 50-year-old woman has a first episode of nonsevere C. difficile. White count is 11,000/mm3 and creatinine is normal. She asks why she is not getting the metronidazole her brother received years ago.',
  'Which of the following is the best explanation?',
  '{"options":["Metronidazole is still first line","Fidaxomicin or oral vancomycin replaced metronidazole for initial treatment","She needs intravenous vancomycin","No antibiotic treats this organism","Bezlotoxumab replaces antibiotics"],"blueprintSystem":"infectious-diseases","taskCategory":"pharmacotherapy","blueprintTopic":"Nonsevere C. difficile is not metronidazole","kind":"vignette"}',
  'Fidaxomicin or oral vancomycin replaced metronidazole for initial treatment',
  'Fidaxomicin or oral vancomycin replaced metronidazole for initial treatment is correct. The 2021 focused update moved initial therapy to fidaxomicin or oral vancomycin. Metronidazole is reserved for when those drugs are unavailable. Incorrect alternatives: Intravenous vancomycin, no treatment, and bezlotoxumab as a substitute are incorrect.',
  '["pance","PANCE-2025","infectious-diseases","pance-200-20261108-v1"]',
  '[{"label":"IDSA and SHEA. 2021 Focused Update Guidelines on Management of Clostridioides difficile Infection in Adults. Clin Infect Dis 2021","url":"https://pubmed.ncbi.nlm.nih.gov/34164674/"}]'::jsonb,
  'generated',
  'be8228d55237fc74ea4dd8263df1b8e3fb685d30841889bda95bfd30a1b6aa25',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'infectious-diseases',
  5,
  'infectious-diseases',
  'infectious-diseases',
  'diagnosis',
  'Latent tuberculosis before a TNF inhibitor',
  'vignette',
  'A 42-year-old woman is about to start adalimumab for rheumatoid arthritis. She was born in a country with high tuberculosis prevalence. She has no cough. A chest radiograph is normal. An interferon-gamma release assay is positive.',
  'Which of the following is the most appropriate sequence?',
  '{"options":["Start adalimumab today and treat tuberculosis if fever appears","Treat latent tuberculosis and delay the TNF inhibitor until latent therapy is underway","Ignore the assay because the radiograph is normal","Give a 2-day antibiotic and start the biologic","BCG vaccine today"],"blueprintSystem":"infectious-diseases","taskCategory":"diagnosis","blueprintTopic":"Latent tuberculosis before a TNF inhibitor","kind":"vignette"}',
  'Treat latent tuberculosis and delay the TNF inhibitor until latent therapy is underway',
  'Treat latent tuberculosis and delay the TNF inhibitor until latent therapy is underway is correct. A positive interferon-gamma release assay with a normal radiograph is latent tuberculosis. TNF blockade can reactivate it, so latent treatment starts before, or at least is established before, the biologic. Incorrect alternatives: Starting the biologic first, ignoring the assay, a 2-day antibiotic, and BCG do not treat latent infection.',
  '["pance","PANCE-2025","infectious-diseases","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '67edc2fa7e8906d315320a72e3c53ef1a4e230ff5c2dabbcfc0fde71615cc84f',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'infectious-diseases',
  4,
  'infectious-diseases',
  'infectious-diseases',
  'pharmacotherapy',
  'Pyelonephritis in pregnancy',
  'vignette',
  'A 24-year-old woman at 22 weeks has fever, flank pain, and a positive nitrite test. She is vomiting. She has no penicillin allergy. The fetus is moving.',
  'Which of the following is the most appropriate setting and drug direction?',
  '{"options":["Ciprofloxacin and discharge","Admit for a pregnancy-safe intravenous beta-lactam; avoid fluoroquinolones","Nitrofurantoin for pyelonephritis","Trimethoprim-sulfamethoxazole in the first trimester as a routine","No antibiotics until delivery"],"blueprintSystem":"infectious-diseases","taskCategory":"pharmacotherapy","blueprintTopic":"Pyelonephritis in pregnancy","kind":"vignette"}',
  'Admit for a pregnancy-safe intravenous beta-lactam; avoid fluoroquinolones',
  'Admit for a pregnancy-safe intravenous beta-lactam; avoid fluoroquinolones is correct. Pyelonephritis in pregnancy is admitted and treated with a beta-lactam that is safe in pregnancy. Fluoroquinolones are avoided, and nitrofurantoin does not treat upper-tract disease. Incorrect alternatives: Discharge on ciprofloxacin, nitrofurantoin, and waiting until delivery under-treat a high-risk infection.',
  '["pance","PANCE-2025","infectious-diseases","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'b63915eab542123af91b16c6fdb7102585db797efca450175d78434e42e846b2',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'infectious-diseases',
  4,
  'infectious-diseases',
  'infectious-diseases',
  'pharmacotherapy',
  'Severe penicillin allergy and syphilis',
  'vignette',
  'A 28-year-old man has a painless chancre and a positive treponemal test. He had anaphylaxis to penicillin as a child, confirmed in the record. He has no neurologic symptoms.',
  'Which of the following is the most appropriate plan for primary syphilis?',
  '{"options":["Give benzathine penicillin without desensitization","Doxycycline for 14 days; reserve penicillin desensitization for pregnancy or neurosyphilis","A single dose of azithromycin","No treatment if the chancre is healing","Ceftriaxone ear drops"],"blueprintSystem":"infectious-diseases","taskCategory":"pharmacotherapy","blueprintTopic":"Severe penicillin allergy and syphilis","kind":"vignette"}',
  'Doxycycline for 14 days; reserve penicillin desensitization for pregnancy or neurosyphilis',
  'Doxycycline for 14 days; reserve penicillin desensitization for pregnancy or neurosyphilis is correct. Penicillin is preferred for syphilis, but a nonpregnant adult with primary syphilis and documented anaphylaxis can be treated with doxycycline 100 mg twice daily for 14 days. Desensitization is the path when penicillin is required, such as pregnancy or neurosyphilis. Incorrect alternatives: A dose of penicillin without desensitization risks anaphylaxis. Azithromycin resistance makes one dose unreliable. A healing chancre and ear drops are not treatment.',
  '["pance","PANCE-2025","infectious-diseases","pance-200-20261108-v1"]',
  '[{"label":"Workowski KA et al. Sexually Transmitted Infections Treatment Guidelines, 2021. MMWR Recomm Rep 2021","url":"https://www.cdc.gov/std/treatment-guidelines/epididymitis.htm"}]'::jsonb,
  'generated',
  '669338250a457c19339a197c6091aae0b1d8ffa74336f567dff007c43de2fdcd',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
