) VALUES (
  gen_random_uuid()::text,
  'pance',
  'infectious-diseases',
  5,
  'infectious-diseases',
  'infectious-diseases',
  'diagnosis',
  'Necrotizing fasciitis antibiotics are not enough',
  'vignette',
  'A 48-year-old man with diabetes has rapidly spreading erythema, bullae, and pain out of proportion on the thigh. He is hypotensive. Lactate is 5 mmol/L.',
  'Which of the following is required in addition to broad antibiotics and fluids?',
  '{"options":["A 24-hour antibiotic trial before any surgeon is called","Immediate surgical exploration","Oral cephalexin","Hyperbaric oxygen as the only intervention","A topical steroid"],"blueprintSystem":"infectious-diseases","taskCategory":"diagnosis","blueprintTopic":"Necrotizing fasciitis antibiotics are not enough","kind":"vignette"}',
  'Immediate surgical exploration',
  'Immediate surgical exploration is correct. Necrotizing infection is a surgical diagnosis. Antibiotics and resuscitation do not replace the operating room when pain, bullae, and shock are already present. Incorrect alternatives: A day of antibiotics, oral cephalexin, hyperbaric oxygen alone, and a steroid leave dead tissue in place.',
  '["pance","PANCE-2025","infectious-diseases","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '76831fdf9b83909c1bb552219a21d7db1ac9703c179e285b07040a38f7bdc37f',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
