) VALUES (
  gen_random_uuid()::text,
  'pance',
  'infectious-diseases',
  4,
  'infectious-diseases',
  'infectious-diseases',
  'pharmacotherapy',
  'Candidemia is not fluconazole first if unstable',
  'vignette',
  'A 70-year-old man in the ICU has a yeast in two blood cultures. He is in shock on norepinephrine. He has not had an eye exam. A central line is in place.',
  'Which of the following is the most appropriate initial antifungal?',
  '{"options":["Fluconazole, because every candidemia starts there","An echinocandin, remove the line if feasible, and do an eye exam","Nystatin swish only","Stop the line and give no drug","Amphotericin ear drops"],"blueprintSystem":"infectious-diseases","taskCategory":"pharmacotherapy","blueprintTopic":"Candidemia is not fluconazole first if unstable","kind":"vignette"}',
  'An echinocandin, remove the line if feasible, and do an eye exam',
  'An echinocandin, remove the line if feasible, and do an eye exam is correct. Unstable candidemia is started on an echinocandin, not fluconazole. The catheter is removed when possible, and the retina is examined because endophthalmitis changes the drug and the duration. Incorrect alternatives: Fluconazole first in shock, nystatin, no drug, and ear drops do not treat bloodstream Candida.',
  '["pance","PANCE-2025","infectious-diseases","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'ebb53234e221c8b7c23bd7d1bd82f518d7b38b5014349684aae0bd19333ac35c',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
