  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'infectious-diseases',
  4,
  'infectious-diseases',
  'infectious-diseases',
  'prevention',
  'HIV post-exposure prophylaxis clock',
  'vignette',
  'A nurse has a needlestick from an HIV-positive source 3 hours ago. The source has a detectable viral load. The nurse''s baseline HIV test is being drawn. She is not pregnant.',
  'Which of the following is the most appropriate timing?',
  '{"options":["Start a three-drug regimen now; do not wait for her baseline result to begin","Wait 72 hours for the baseline test before any drug","A single dose of zidovudine","No prophylaxis because 3 hours have passed","Vaccine only"],"blueprintSystem":"infectious-diseases","taskCategory":"prevention","blueprintTopic":"HIV post-exposure prophylaxis clock","kind":"vignette"}',
  'Start a three-drug regimen now; do not wait for her baseline result to begin',
  'Start a three-drug regimen now; do not wait for her baseline result to begin is correct. Occupational HIV post-exposure prophylaxis is most effective started as soon as possible, ideally within hours, and is not delayed for the baseline blood draw. It is a 28-day three-drug course. Incorrect alternatives: Waiting 72 hours, one dose of zidovudine, skipping treatment at 3 hours, and a vaccine miss the window.',
  '["pance","PANCE-2025","infectious-diseases","pance-200-20261108-v1"]',
  '[{"label":"Workowski KA et al. Sexually Transmitted Infections Treatment Guidelines, 2021. MMWR Recomm Rep 2021","url":"https://www.cdc.gov/std/treatment-guidelines/epididymitis.htm"}]'::jsonb,
  'generated',
  'cf731312b23dfe4d4efd6e67acfe9d3475ac892876bcd737964f433cd1723b7b',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
