  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'infectious-diseases',
  4,
  'infectious-diseases',
  'infectious-diseases',
  'diagnosis',
  'Malaria smear before a weekend',
  'vignette',
  'A 30-year-old man returned from West Africa 8 days ago and did not take prophylaxis. He has fever, headache, and a hematocrit of 28%. Platelets are 70,000/mm3.',
  'Which of the following is the most appropriate immediate test?',
  '{"options":["A single thick-and-thin smear now, repeated if negative","Stool culture","Monospot only","No testing until he has cyclic fever for a week","A chest radiograph as the definitive test"],"blueprintSystem":"infectious-diseases","taskCategory":"diagnosis","blueprintTopic":"Malaria smear before a weekend","kind":"vignette"}',
  'A single thick-and-thin smear now, repeated if negative',
  'A single thick-and-thin smear now, repeated if negative is correct. Fever after travel to a malaria region is malaria until smears say otherwise. One negative smear does not exclude it, so smears are repeated. Anemia and thrombocytopenia fit severe risk and he should not wait the weekend. Incorrect alternatives: Stool culture, a monospot, a delay for classic periodicity, and a chest film as the only test miss parasitemia.',
  '["pance","PANCE-2025","infectious-diseases","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '037c245e82b5e141e503ccb35a40ab38d9c9eb23b4b2a38989be5cc5c2f89c84',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'infectious-diseases',
  4,
  'infectious-diseases',
  'infectious-diseases',
  'pharmacotherapy',
  'Influenza treatment window in a high-risk adult',
  'vignette',
  'A 70-year-old woman with heart failure has had fever and cough for 36 hours. Influenza A is positive. She is hypoxic and is being admitted. Symptoms started yesterday.',
  'Which of the following is the most appropriate antiviral decision?',
  '{"options":["No antiviral, because 36 hours have passed","Start oseltamivir","Amantadine","Antibiotics only","A steroid burst instead of an antiviral"],"blueprintSystem":"infectious-diseases","taskCategory":"pharmacotherapy","blueprintTopic":"Influenza treatment window in a high-risk adult","kind":"vignette"}',
  'Start oseltamivir',
  'Start oseltamivir is correct. Hospitalized and high-risk patients are treated with a neuraminidase inhibitor even when symptoms are past 48 hours. Amantadine is not used because of resistance. Incorrect alternatives: Withholding treatment at 36 hours, amantadine, antibiotics alone, and steroids as a substitute are incorrect.',
  '["pance","PANCE-2025","infectious-diseases","pance-200-20261108-v1"]',
  '[{"label":"Metlay JP et al. Diagnosis and Treatment of Adults with Community-acquired Pneumonia. ATS/IDSA Guideline. Am J Respir Crit Care Med 2019","url":"https://pubmed.ncbi.nlm.nih.gov/31573350/"}]'::jsonb,
  'generated',
  '768506f784e4b2bc7ef875cf00778b1ad728a37fe180950be9c0d779f6ae16a5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
