  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'infectious-diseases',
  3,
  'infectious-diseases',
  'infectious-diseases',
  'prevention',
  'Asplenia vaccines',
  'vignette',
  'A 25-year-old woman had a splenectomy yesterday after trauma. She is stable. She has never received pneumococcal, meningococcal, or Haemophilus influenzae type b vaccines.',
  'Which of the following is the most appropriate prevention plan?',
  '{"options":["No vaccines are needed after trauma splenectomy","Give pneumococcal, meningococcal, and Hib vaccines, and prescribe an emergency antibiotic plan","Daily penicillin is a substitute for every vaccine","Live influenza vaccine into the wound","Only a tetanus booster"],"blueprintSystem":"infectious-diseases","taskCategory":"prevention","blueprintTopic":"Asplenia vaccines","kind":"vignette"}',
  'Give pneumococcal, meningococcal, and Hib vaccines, and prescribe an emergency antibiotic plan',
  'Give pneumococcal, meningococcal, and Hib vaccines, and prescribe an emergency antibiotic plan is correct. Asplenia creates a lifelong risk of overwhelming encapsulated-bacterial sepsis. Those vaccines and an action plan for fever are standard, timed so they actually take. Incorrect alternatives: Skipping vaccines, using penicillin as the only prevention, a wound injection of live vaccine, and tetanus alone leave the encapsulated-organism gap.',
  '["pance","PANCE-2025","infectious-diseases","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'efbbf7488c0abea573d6754202edf26cfdeeaef14a5a156adaf2289becb5371a',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
