  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'endocrine',
  5,
  'endocrine',
  'endocrine',
  'pharmacotherapy',
  'SGLT2 perioperative hold',
  'vignette',
  'A 64-year-old man with type 2 diabetes takes empagliflozin. He is scheduled for a bowel prep and colonoscopy tomorrow and will be on clear liquids today. eGFR is 55. He feels well.',
  'Which of the following is the most appropriate instruction?',
  '{"options":["Take empagliflozin the morning of the procedure","Hold the SGLT2 inhibitor for the fast and the procedure day because of euglycemic ketoacidosis","Double the dose to cover the fast","Switch to glyburide tonight","No change is ever required around surgery"],"blueprintSystem":"endocrine","taskCategory":"pharmacotherapy","blueprintTopic":"SGLT2 perioperative hold","kind":"vignette"}',
  'Hold the SGLT2 inhibitor for the fast and the procedure day because of euglycemic ketoacidosis',
  'Hold the SGLT2 inhibitor for the fast and the procedure day because of euglycemic ketoacidosis is correct. SGLT2 inhibitors are held for prolonged fasting, bowel prep, and surgery. Ketoacidosis can occur with a normal glucose, so symptoms after the procedure still need a ketone check. Incorrect alternatives: Taking or doubling the dose, a sulfonylurea swap the night before, and ignoring the fast are unsafe.',
  '["pance","PANCE-2025","endocrine","pance-200-20261108-v1"]',
  '[{"label":"American Diabetes Association. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://doi.org/10.2337/dc26-s011"}]'::jsonb,
  'generated',
  '58593b0e244d609ee3090b7192864217971102a12d632fa010e6e385ad19fbbd',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'endocrine',
  5,
  'endocrine',
  'endocrine',
  'diagnosis',
  'Euglycemic ketoacidosis',
  'vignette',
  'A 58-year-old woman on canagliflozin has nausea and tachypnea the day after a colonoscopy. Glucose is 140 mg/dL. Venous pH is 7.18 and beta-hydroxybutyrate is 5.2 mmol/L. Lactate is normal.',
  'Which of the following is the most likely diagnosis?',
  '{"options":["Hyperosmolar state, because glucose is only 140","Euglycemic diabetic ketoacidosis","Lactic acidosis from metformin, despite a normal lactate","Starvation with no treatment needed","A lab error because glucose is not 400"],"blueprintSystem":"endocrine","taskCategory":"diagnosis","blueprintTopic":"Euglycemic ketoacidosis","kind":"vignette"}',
  'Euglycemic diabetic ketoacidosis',
  'Euglycemic diabetic ketoacidosis is correct. An anion-gap acidosis with high beta-hydroxybutyrate and a glucose that is not high is the SGLT2-associated ketoacidosis pattern, often after a fast. Treatment is the same physiology as DKA: insulin, glucose, and volume, and the drug is stopped. Incorrect alternatives: Hyperosmolar state needs a very high glucose. A normal lactate is not metformin lactic acidosis. Starvation ketosis is milder. The glucose does not have to be 400.',
  '["pance","PANCE-2025","endocrine","pance-200-20261108-v1"]',
  '[{"label":"American Diabetes Association. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://doi.org/10.2337/dc26-s011"}]'::jsonb,
  'generated',
  '5549751348416e6c052fbdba6a4f932ff036c366f0888e476da1c99640d472ee',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'endocrine',
  4,
  'endocrine',
  'endocrine',
  'pharmacotherapy',
  'Insulin in DKA before potassium is known',
  'vignette',
  'A 19-year-old man with type 1 diabetes has glucose 480 mg/dL, pH 7.12, and bicarbonate 8 mEq/L. The chemistry panel has not returned. The ECG is normal.',
  'Which of the following is the most appropriate insulin decision?',
  '{"options":["Start intravenous insulin before any potassium result","Hold insulin until the potassium is known to be at least 3.3 mEq/L","Give bicarbonate as the only drug","Subcutaneous basal insulin once and discharge","No fluids"],"blueprintSystem":"endocrine","taskCategory":"pharmacotherapy","blueprintTopic":"Insulin in DKA before potassium is known","kind":"vignette"}',
  'Hold insulin until the potassium is known to be at least 3.3 mEq/L',
  'Hold insulin until the potassium is known to be at least 3.3 mEq/L is correct. Insulin shifts potassium into cells. A normal ECG does not prove the serum potassium is safe, so insulin waits until the level is known to be at least 3.3 mEq/L. Fluids can start while that lab is pending. Incorrect alternatives: Blind insulin, bicarbonate alone, one basal dose, and no fluids are not how DKA is opened.',
  '["pance","PANCE-2025","endocrine","pance-200-20261108-v1"]',
  '[{"label":"American Diabetes Association. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://doi.org/10.2337/dc26-s011"}]'::jsonb,
  'generated',
  'b672c7aacfde645f5a3218dfbe439cbfff00b23506a6eebcc77ceecd9ef579b9',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'endocrine',
  4,
  'endocrine',
  'endocrine',
  'diagnosis',
  'Primary adrenal insufficiency',
  'vignette',
  'A 32-year-old woman has fatigue, salt craving, and orthostasis. Sodium is 128 mEq/L, potassium is 5.6 mEq/L, and morning cortisol is 2 mcg/dL. ACTH is high. She has hyperpigmented palmar creases.',
  'Which of the following is the most appropriate long-term replacement?',
  '{"options":["Prednisone only, with no mineralocorticoid","Hydrocortisone and fludrocortisone","Levothyroxine before any steroid","Methimazole","Observation"],"blueprintSystem":"endocrine","taskCategory":"diagnosis","blueprintTopic":"Primary adrenal insufficiency","kind":"vignette"}',
  'Hydrocortisone and fludrocortisone',
  'Hydrocortisone and fludrocortisone is correct. High ACTH, low cortisol, hyponatremia, and hyperkalemia are primary adrenal insufficiency. She needs glucocorticoid and mineralocorticoid replacement. Pigmentation fits high ACTH. Incorrect alternatives: Glucocorticoid alone misses aldosterone. Starting levothyroxine first in coexisting autoimmune disease can precipitate crisis. Methimazole and observation do not replace cortisol.',
  '["pance","PANCE-2025","endocrine","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'f23410c9c9507f3e31f5e5169f410d8526fc32a56553f6bc24e91a75086478b0',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'endocrine',
  5,
  'endocrine',
  'endocrine',
  'pharmacotherapy',
  'Levothyroxine before steroids in hypopituitarism',
  'vignette',
  'A 40-year-old man has a pituitary macroadenoma. Morning cortisol is 3 mcg/dL and free T4 is low. Someone orders levothyroxine to start tonight and steroids ''if he looks sick later.''',
  'Which of the following is the correct sequence?',
  '{"options":["Levothyroxine first","Glucocorticoid replacement before or with thyroid hormone","Methimazole","No replacement until after surgery next month","Liothyronine only"],"blueprintSystem":"endocrine","taskCategory":"pharmacotherapy","blueprintTopic":"Levothyroxine before steroids in hypopituitarism","kind":"vignette"}',
  'Glucocorticoid replacement before or with thyroid hormone',
  'Glucocorticoid replacement before or with thyroid hormone is correct. Thyroid hormone speeds cortisol clearance. Replacing it while the patient is adrenally insufficient can cause crisis. Steroid cover comes first. Incorrect alternatives: Thyroid hormone first, methimazole, a month of delay, and T3 alone are unsafe.',
  '["pance","PANCE-2025","endocrine","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'b7039782f60c18017dd9ffb182df1c990beecd0542fab85534dc473cbf3766e9',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'endocrine',
  4,
  'endocrine',
  'endocrine',
  'diagnosis',
  'Hypoglycemia in a sulfonylurea overdose',
  'vignette',
  'A 78-year-old man took a handful of glipizide. Glucose is 38 mg/dL. He wakes after intravenous dextrose and the repeat glucose an hour later is 42 mg/dL. He wants to go home.',
  'Which of the following is the most appropriate disposition?',
  '{"options":["Discharge, because he woke up","Admit; sulfonylurea hypoglycemia recurs after dextrose","Glucagon once and discharge with no observation","Insulin infusion","Oral glyburide to stabilize him"],"blueprintSystem":"endocrine","taskCategory":"diagnosis","blueprintTopic":"Hypoglycemia in a sulfonylurea overdose","kind":"vignette"}',
  'Admit; sulfonylurea hypoglycemia recurs after dextrose',
  'Admit; sulfonylurea hypoglycemia recurs after dextrose is correct. Sulfonylureas force insulin release for many hours. Dextrose treats the moment and then glucose falls again. Octreotide is often added, and he is observed. Incorrect alternatives: Discharge, a single glucagon dose, insulin, and more sulfonylurea are dangerous.',
  '["pance","PANCE-2025","endocrine","pance-200-20261108-v1"]',
  '[{"label":"American Diabetes Association. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://doi.org/10.2337/dc26-s011"}]'::jsonb,
  'generated',
  'f43f4caa80b23a987755d6c1591c257e9e64347ddd2c4f278ba36b9413adf444',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'endocrine',
  4,
  'endocrine',
  'endocrine',
  'labs',
  'Do not use TSH alone early in thyroiditis',
  'vignette',
  'A 35-year-old woman has a tender thyroid, fever, and a free T4 that is high. TSH is 0.05. Radioactive iodine uptake is very low. She had a viral illness last week.',
  'Which of the following is the most appropriate treatment?',
  '{"options":["Methimazole","A beta blocker and an anti-inflammatory; this is thyroiditis, not Graves","Radioiodine ablation this week","Propylthiouracil","Levothyroxine now while she is thyrotoxic"],"blueprintSystem":"endocrine","taskCategory":"labs","blueprintTopic":"Do not use TSH alone early in thyroiditis","kind":"vignette"}',
  'A beta blocker and an anti-inflammatory; this is thyroiditis, not Graves',
  'A beta blocker and an anti-inflammatory; this is thyroiditis, not Graves is correct. Tender gland, a viral prodrome, and near-zero uptake are subacute thyroiditis. Hormone is leaking, not being made, so antithyroid drugs and ablation do not help. A beta blocker treats symptoms. Incorrect alternatives: Methimazole, propylthiouracil, radioiodine, and levothyroxine during the toxic phase treat the wrong physiology.',
  '["pance","PANCE-2025","endocrine","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'a36107cbe3ebf9d414e6f73104a9f0b3ed8b374c015b96973ad2e8774be00e9f',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
