  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'endocrine',
  4,
  'endocrine',
  'endocrine',
  'diagnosis',
  'Hypercalcemia of malignancy versus hyperparathyroidism',
  'vignette',
  'A 68-year-old smoker has calcium 13.8 mg/dL, suppressed PTH, and a lung mass. He is volume depleted and confused.',
  'Which of the following is the most appropriate first treatment?',
  '{"options":["Hydrochlorothiazide","Isotonic saline","Observation because PTH is suppressed","Lithium","A low-phosphate diet as the only step"],"blueprintSystem":"endocrine","taskCategory":"diagnosis","blueprintTopic":"Hypercalcemia of malignancy versus hyperparathyroidism","kind":"vignette"}',
  'Isotonic saline',
  'Isotonic saline is correct. Severe hypercalcemia is volume resuscitated first. Suppressed PTH with a lung mass is humoral hypercalcemia of malignancy, not primary hyperparathyroidism, so the cancer pathway is pursued after he is stabilized. Incorrect alternatives: A thiazide raises calcium. Observation, lithium, and diet alone do not treat a calcium of 13.8 with confusion.',
  '["pance","PANCE-2025","endocrine","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'b3b32f77a80c929d4f785e3477d79a7c0c8244107c99f1083bf99f01074dda9e',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'endocrine',
  4,
  'endocrine',
  'endocrine',
  'pharmacotherapy',
  'Metformin and contrast',
  'vignette',
  'A 66-year-old woman takes metformin. eGFR is 48 mL/min/1.73 m2. She needs a contrasted CT today and is euvolemic with no acute kidney injury.',
  'Which of the following is the most appropriate metformin plan?',
  '{"options":["Never give contrast to anyone on metformin","Hold metformin at the time of contrast because the eGFR is under 60, then restart after kidney function is rechecked","Double metformin the morning of the scan","Switch to glyburide in the scanner","Stop metformin forever because the eGFR is under 60"],"blueprintSystem":"endocrine","taskCategory":"pharmacotherapy","blueprintTopic":"Metformin and contrast","kind":"vignette"}',
  'Hold metformin at the time of contrast because the eGFR is under 60, then restart after kidney function is rechecked',
  'Hold metformin at the time of contrast because the eGFR is under 60, then restart after kidney function is rechecked is correct. Metformin is otherwise acceptable at an eGFR of 48, and contrast is not forbidden. Product labeling holds it at the time of iodinated contrast when the eGFR is under 60 and restarts it after function is confirmed stable. An eGFR under 60 is not a reason to stop it forever. Incorrect alternatives: A blanket ban on contrast, doubling the dose, a sulfonylurea swap, and permanent cessation overstate or miss the hold.',
  '["pance","PANCE-2025","endocrine","pance-200-20261108-v1"]',
  '[{"label":"American Diabetes Association. 11. Chronic Kidney Disease and Risk Management: Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://doi.org/10.2337/dc26-s011"}]'::jsonb,
  'generated',
  'c9a5800008a444743413b11b12372a1617397b9596ad785a88a93c64ad848a79',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'endocrine',
  5,
  'endocrine',
  'endocrine',
  'diagnosis',
  'Pheochromocytoma blood pressure drug order',
  'vignette',
  'A 38-year-old man has paroxysmal hypertension, headaches, and a positive plasma metanephrine. Imaging shows an adrenal mass. Surgery is planned. A student wants a beta blocker started today, before any alpha blockade.',
  'Which of the following is the correct preoperative sequence?',
  '{"options":["Beta blocker first","Alpha blockade before a beta blocker","A diuretic as the only drug","Immediate biopsy of the mass in the clinic","No blockade is needed"],"blueprintSystem":"endocrine","taskCategory":"diagnosis","blueprintTopic":"Pheochromocytoma blood pressure drug order","kind":"vignette"}',
  'Alpha blockade before a beta blocker',
  'Alpha blockade before a beta blocker is correct. Blocking beta receptors first leaves alpha constriction unopposed and can cause a crisis. Alpha blockade, volume restoration, then a beta blocker if the heart rate needs it, is the order before resection. Incorrect alternatives: A diuretic alone, a clinic biopsy, and no blockade are unsafe.',
  '["pance","PANCE-2025","endocrine","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '4464e5ac0ccd09aef9ec9a50b48fa3715a95d6dd582692cef40db021164dd113',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
