  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'eent',
  5,
  'eent',
  'eent',
  'pharmacotherapy',
  'Acute angle closure',
  'vignette',
  'A 64-year-old woman has a red eye, a mid-dilated pupil, severe pain, halos, and vomiting. The eye is rock hard. Vision is 20/200.',
  'Which of the following is the most appropriate immediate plan?',
  '{"options":["Dilating drops and a 1-week clinic visit","Pressure-lowering drops, acetazolamide, and urgent ophthalmology for laser iridotomy","Topical steroid as the only drug","Oral antibiotic","Patch the eye for 48 hours"],"blueprintSystem":"eent","taskCategory":"pharmacotherapy","blueprintTopic":"Acute angle closure","kind":"vignette"}',
  'Pressure-lowering drops, acetazolamide, and urgent ophthalmology for laser iridotomy',
  'Pressure-lowering drops, acetazolamide, and urgent ophthalmology for laser iridotomy is correct. A mid-dilated pupil, a hard globe, and halos are acute angle closure. Pressure is lowered medically and a laser iridotomy is the definitive step. Dilation makes it worse. Incorrect alternatives: A delayed clinic visit, steroid monotherapy, an antibiotic, and a patch do not open the angle.',
  '["pance","PANCE-2025","eent","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'fd55b0673aae3ff53c4eeac3a13fe449bcc7012d34551ce9d167fd2105d41858',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
