) VALUES (
  gen_random_uuid()::text,
  'pance',
  'eent',
  4,
  'eent',
  'eent',
  'pharmacotherapy',
  'Central retinal artery versus vein',
  'vignette',
  'A 70-year-old man has sudden painless vision loss in one eye an hour ago. The retina is pale with a cherry-red spot. He has no flashes.',
  'Which of the following is the most appropriate immediate action?',
  '{"options":["Routine clinic in a month","Emergency stroke-style evaluation; this is a central retinal artery occlusion","Topical antibiotic","Reassurance that a cherry-red spot is viral","A multivitamin"],"blueprintSystem":"eent","taskCategory":"pharmacotherapy","blueprintTopic":"Central retinal artery versus vein","kind":"vignette"}',
  'Emergency stroke-style evaluation; this is a central retinal artery occlusion',
  'Emergency stroke-style evaluation; this is a central retinal artery occlusion is correct. A pale retina and cherry-red spot are central retinal artery occlusion, an ocular stroke. He needs emergent eye care and a stroke workup. Time is retina. Incorrect alternatives: A month wait, an antibiotic, calling it viral, and a vitamin miss an embolic emergency.',
  '["pance","PANCE-2025","eent","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'dd8f8cc3baa89ce803be68b128bf1075a0eeaf23f93b5cd9354b0effc22e2242',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
