  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'eent',
  4,
  'eent',
  'eent',
  'diagnosis',
  'Retinal detachment flashes and a curtain',
  'vignette',
  'A 60-year-old man with myopia sees flashes and a shower of floaters, then a curtain over the top of the visual field. Central vision is still present.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Artificial tears","Same-day ophthalmology for a possible retinal detachment","A 2-week wait","Oral steroid","Antibiotics"],"blueprintSystem":"eent","taskCategory":"diagnosis","blueprintTopic":"Retinal detachment flashes and a curtain","kind":"vignette"}',
  'Same-day ophthalmology for a possible retinal detachment',
  'Same-day ophthalmology for a possible retinal detachment is correct. Flashes, a sudden shower of floaters, and a curtain are retinal detachment until the retina is examined. Central vision can still be saved if the macula is attached. Incorrect alternatives: Tears, a 2-week delay, steroids, and antibiotics do not reattach the retina.',
  '["pance","PANCE-2025","eent","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'f5f17fbc41b02cae7124926187b7264336ac6349824e16b3457509bc70f2a6ca',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
