) VALUES (
  gen_random_uuid()::text,
  'pance',
  'eent',
  4,
  'eent',
  'eent',
  'pharmacotherapy',
  'Otitis externa and a perforated drum',
  'vignette',
  'A 20-year-old swimmer has tragal tenderness and a swollen canal. You can see a perforation in the tympanic membrane. He is afebrile.',
  'Which of the following drops are appropriate?',
  '{"options":["Neomycin-polymyxin if a perforation is present","A fluoroquinolone otic drop; avoid aminoglycoside drops when the drum is open","Oral amoxicillin only, with no drops","Acetic acid and alcohol drops","Steroid drops with neomycin"],"blueprintSystem":"eent","taskCategory":"pharmacotherapy","blueprintTopic":"Otitis externa and a perforated drum","kind":"vignette"}',
  'A fluoroquinolone otic drop; avoid aminoglycoside drops when the drum is open',
  'A fluoroquinolone otic drop; avoid aminoglycoside drops when the drum is open is correct. Otitis externa is treated with topical therapy. Aminoglycosides are ototoxic if they reach the middle ear through a perforation, so a fluoroquinolone drop is chosen. Incorrect alternatives: Neomycin combinations, alcohol and acetic acid, and oral therapy alone are the wrong drop or the wrong route.',
  '["pance","PANCE-2025","eent","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '83725e54408c538d76f3710286bd2c8d1118d52e0bedab0906959263d009167b',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
