  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'eent',
  5,
  'eent',
  'eent',
  'diagnosis',
  'Malignant otitis externa',
  'vignette',
  'A 74-year-old man with poorly controlled diabetes has severe ear pain, granulation in the canal, and facial-nerve weakness. He is afebrile but looks ill.',
  'Which of the following is the most appropriate direction?',
  '{"options":["Acetic acid drops for a week","Antipseudomonal antibiotics and imaging; this is malignant otitis externa","Antihistamines","Cerumen removal only","Observation"],"blueprintSystem":"eent","taskCategory":"diagnosis","blueprintTopic":"Malignant otitis externa","kind":"vignette"}',
  'Antipseudomonal antibiotics and imaging; this is malignant otitis externa',
  'Antipseudomonal antibiotics and imaging; this is malignant otitis externa is correct. Elderly diabetes, canal granulation, and cranial-nerve involvement are skull-base osteomyelitis, usually Pseudomonas, until proved otherwise. Drops are not enough. Incorrect alternatives: A week of acetic acid, antihistamines, wax removal, and observation miss invasive disease.',
  '["pance","PANCE-2025","eent","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '59c68272fe1a2ecd87a5e0cd4345a7d5fc318665be81097e32e76726cc79b3ba',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
