  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'eent',
  3,
  'eent',
  'eent',
  'diagnosis',
  'Peritonsillar abscess',
  'vignette',
  'A 19-year-old man has fever, trismus, a muffled voice, and deviation of the uvula away from a swollen tonsil.',
  'Which of the following is the most appropriate treatment?',
  '{"options":["Amoxicillin and clinic follow-up next week","Drainage plus antibiotics","Antihistamines","A throat culture only","Steroids as the only drug"],"blueprintSystem":"eent","taskCategory":"diagnosis","blueprintTopic":"Peritonsillar abscess","kind":"vignette"}',
  'Drainage plus antibiotics',
  'Drainage plus antibiotics is correct. Uvular deviation, trismus, and a muffled voice are a peritonsillar abscess. It is drained and antibiotics cover group A streptococcus and oral anaerobes. Incorrect alternatives: A delayed oral antibiotic, antihistamines, culture without drainage, and steroids alone do not empty the collection.',
  '["pance","PANCE-2025","eent","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '649d6e9ee71b6d7b7014adb6587d7a58cdeed981718558c44b2a1dcf728b1c78',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'eent',
  5,
  'eent',
  'eent',
  'diagnosis',
  'Epiglottitis airway',
  'vignette',
  'A 45-year-old man is drooling, sitting forward, and has a fever. He becomes stridorous when examined with a tongue blade. Oxygen saturation is 94%.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Force a tongue blade to see the epiglottis","Airway specialists in a controlled setting; do not agitate the airway","Oral antibiotics and discharge","A nebulized steroid as definitive care","CT before any airway plan"],"blueprintSystem":"eent","taskCategory":"diagnosis","blueprintTopic":"Epiglottitis airway","kind":"vignette"}',
  'Airway specialists in a controlled setting; do not agitate the airway',
  'Airway specialists in a controlled setting; do not agitate the airway is correct. Drooling and tripoding in an adult are epiglottitis until the airway is secured. Instrumentation in an uncontrolled room can precipitate obstruction. Incorrect alternatives: A forced exam, discharge, a nebulizer as the cure, and a trip to CT before an airway plan are dangerous.',
  '["pance","PANCE-2025","eent","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '44b2991419f1091d1bffca2c73d47f5786a7023badc3599fe26ed51ccf13074f',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'eent',
  3,
  'eent',
  'eent',
  'pharmacotherapy',
  'Allergic rhinitis controller',
  'vignette',
  'A 16-year-old has seasonal sneezing, itchy eyes, and clear rhinorrhea. She has no polyps, asthma, or purulent drainage. She wants something better than as-needed antihistamine tablets.',
  'Which of the following is the most appropriate controller?',
  '{"options":["An oral antibiotic for 14 days","Intranasal corticosteroid","Oral prednisone for the whole season","Pseudoephedrine around the clock in a patient you have not screened for blood pressure","Antifungal tablets"],"blueprintSystem":"eent","taskCategory":"pharmacotherapy","blueprintTopic":"Allergic rhinitis controller","kind":"vignette"}',
  'Intranasal corticosteroid',
  'Intranasal corticosteroid is correct. Intranasal corticosteroids are the most effective single maintenance therapy for allergic rhinitis. Antibiotics and antifungals treat infections she does not have. Incorrect alternatives: A season of prednisone and uncritical decongestant use add harm.',
  '["pance","PANCE-2025","eent","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'bba47bb8fea124d85ee90119462093959b095f1ba9f4385e04e41c901f71cc1f',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'eent',
  4,
  'eent',
  'eent',
  'diagnosis',
  'Sudden sensorineural hearing loss',
  'vignette',
  'A 55-year-old man woke yesterday with hearing loss in the left ear. Weber lateralizes to the right. Rinne shows air greater than bone on the left, and he cannot hear a whispered voice. The canal and drum are normal.',
  'Which of the following is the most appropriate next step?',
  '{"options":["A year of observation","Urgent audiology and prompt corticosteroids for idiopathic sudden sensorineural loss","Antibiotic drops","Cerumen removal","Antihistamines for a month before any test"],"blueprintSystem":"eent","taskCategory":"diagnosis","blueprintTopic":"Sudden sensorineural hearing loss","kind":"vignette"}',
  'Urgent audiology and prompt corticosteroids for idiopathic sudden sensorineural loss',
  'Urgent audiology and prompt corticosteroids for idiopathic sudden sensorineural loss is correct. Weber to the good ear and a normal exam mean sensorineural loss. Sudden idiopathic loss is treated as an emergency with steroids; delay worsens recovery. Incorrect alternatives: A year of waiting, drops, wax removal, and antihistamines fit conductive problems he does not have.',
  '["pance","PANCE-2025","eent","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '298d4cabefdb79d89ff8575b7eb01c704b4c3af147f838f7d63863e913f43952',
