) VALUES (
  gen_random_uuid()::text,
  'pance',
  'eent',
  5,
  'eent',
  'eent',
  'diagnosis',
  'Orbital versus periorbital cellulitis',
  'vignette',
  'A 7-year-old boy has eyelid swelling, fever, pain with eye movement, and proptosis after a sinus infection. Vision is reduced.',
  'Which of the following is the most appropriate plan?',
  '{"options":["Oral cephalexin for periorbital cellulitis","Intravenous antibiotics and imaging; pain with eye movement and proptosis mean orbital involvement","Antihistamine drops","Warm compresses only","A steroid cream"],"blueprintSystem":"eent","taskCategory":"diagnosis","blueprintTopic":"Orbital versus periorbital cellulitis","kind":"vignette"}',
  'Intravenous antibiotics and imaging; pain with eye movement and proptosis mean orbital involvement',
  'Intravenous antibiotics and imaging; pain with eye movement and proptosis mean orbital involvement is correct. Periorbital cellulitis does not cause proptosis, ophthalmoplegia, or vision loss. Those findings are orbital cellulitis and need intravenous antibiotics, imaging, and often ENT or ophthalmology. Incorrect alternatives: Oral cephalexin, allergy drops, compresses, and a steroid cream under-treat an orbit.',
  '["pance","PANCE-2025","eent","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '9871b9655507c37fb7b166e16c4c0b11423a3dc5cf2c555b0ec64a19a35fe2c6',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
