) VALUES (
  gen_random_uuid()::text,
  'pance',
  'hematologic',
  4,
  'hematologic',
  'hematologic',
  'diagnosis',
  'Iron deficiency versus thalassemia trait',
  'vignette',
  'A 22-year-old woman has a hemoglobin of 10.8 g/dL and an MCV of 68 fL. Red-cell count is high for the hemoglobin. Ferritin is 80 ng/mL. Hemoglobin electrophoresis is pending.',
  'Which of the following is the more likely pattern?',
  '{"options":["Iron deficiency, because the MCV is low","Thalassemia trait, because the red-cell count is high and ferritin is not low","B12 deficiency","Acute blood loss from yesterday","Sideroblastic anemia from a factory exposure she does not have"],"blueprintSystem":"hematologic","taskCategory":"diagnosis","blueprintTopic":"Iron deficiency versus thalassemia trait","kind":"vignette"}',
  'Thalassemia trait, because the red-cell count is high and ferritin is not low',
  'Thalassemia trait, because the red-cell count is high and ferritin is not low is correct. Iron deficiency has a low ferritin and a low red-cell count. A very low MCV with a high red-cell count and a normal ferritin is thalassemia trait until electrophoresis confirms it. Incorrect alternatives: B12 deficiency is macrocytic. Acute blood loss is normocytic. Sideroblastic anemia is not the default without a toxin.',
  '["pance","PANCE-2025","hematologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '75eb82931678f3a4958b45f67c4a3e6ea7b19d828da78ca0b0758dc675b73e3d',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
