  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'hematologic',
  5,
  'hematologic',
  'hematologic',
  'pharmacotherapy',
  'Heparin-induced thrombocytopenia',
  'vignette',
  'A 66-year-old man on unfractionated heparin for 8 days has a platelet count that fell from 220,000 to 70,000/mm3. He has a new swollen leg. Ultrasound shows a femoral DVT.',
  'Which of the following is the most appropriate next anticoagulant step?',
  '{"options":["Increase the heparin","Stop heparin and start a non-heparin anticoagulant such as argatroban","Platelet transfusion as the only treatment","Switch to enoxaparin","Warfarin alone tonight with no other anticoagulant"],"blueprintSystem":"hematologic","taskCategory":"pharmacotherapy","blueprintTopic":"Heparin-induced thrombocytopenia","kind":"vignette"}',
  'Stop heparin and start a non-heparin anticoagulant such as argatroban',
  'Stop heparin and start a non-heparin anticoagulant such as argatroban is correct. A platelet fall after day 5 plus a new clot is heparin-induced thrombocytopenia until proved otherwise. All heparin stops, including flushes, and a direct thrombin inhibitor or another non-heparin drug is started. Warfarin is not started alone because of venous limb gangrene. Incorrect alternatives: More heparin, a low-molecular-weight heparin, platelets alone, and warfarin monotherapy propagate the clot.',
  '["pance","PANCE-2025","hematologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'f29a068b91c585ffc2e0213571a2d62eb37b4b71f88dd6fbd4fc4719b97c8f65',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
