  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'hematologic',
  5,
  'hematologic',
  'hematologic',
  'diagnosis',
  'TTP pentad is not required',
  'vignette',
  'A 35-year-old woman has confusion, a platelet count of 15,000/mm3, creatinine 2.1 mg/dL, and hemoglobin 8 g/dL with schistocytes. Coagulation tests are normal. She has no fever.',
  'Which of the following is the most appropriate next treatment?',
  '{"options":["Platelet transfusion and discharge","Plasma exchange for thrombotic thrombocytopenic purpura; do not wait for the full pentad","Heparin","Vitamin K","Observation because she has no fever"],"blueprintSystem":"hematologic","taskCategory":"diagnosis","blueprintTopic":"TTP pentad is not required","kind":"vignette"}',
  'Plasma exchange for thrombotic thrombocytopenic purpura; do not wait for the full pentad',
  'Plasma exchange for thrombotic thrombocytopenic purpura; do not wait for the full pentad is correct. Microangiopathic hemolysis, thrombocytopenia, and organ injury with normal coagulation tests are TTP. Fever is often absent. Plasma exchange is started urgently. Platelets are not given unless there is life-threatening bleeding. Incorrect alternatives: Heparin, vitamin K, and observation treat other bleeding disorders.',
  '["pance","PANCE-2025","hematologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'bb93c1a311de547c88fb6cec0daefc3e43c79048316df245c624d321f4fe546b',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
