) VALUES (
  gen_random_uuid()::text,
  'pance',
  'hematologic',
  4,
  'hematologic',
  'hematologic',
  'pharmacotherapy',
  'Warfarin reversal for bleeding',
  'vignette',
  'A 78-year-old man on warfarin has an INR of 8 and hematemesis. Blood pressure is 90/60 mm Hg.',
  'Which of the following is the most appropriate reversal?',
  '{"options":["Hold warfarin and recheck tomorrow","Four-factor prothrombin complex concentrate and intravenous vitamin K","Vitamin K by mouth only","Protamine","Idarucizumab"],"blueprintSystem":"hematologic","taskCategory":"pharmacotherapy","blueprintTopic":"Warfarin reversal for bleeding","kind":"vignette"}',
  'Four-factor prothrombin complex concentrate and intravenous vitamin K',
  'Four-factor prothrombin complex concentrate and intravenous vitamin K is correct. Major bleeding on warfarin is reversed with four-factor PCC plus intravenous vitamin K. Holding the dose is for an INR elevation without bleeding. Incorrect alternatives: Oral vitamin K is too slow. Protamine reverses heparin. Idarucizumab reverses dabigatran.',
  '["pance","PANCE-2025","hematologic","pance-200-20261108-v1"]',
  '[{"label":"Stevens SM et al. Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline. Chest 2021","url":"https://journal.chestnet.org/article/S0012-3692(21)01506-3/fulltext"}]'::jsonb,
  'generated',
  '0829a9041e9d910b51b326e5f2c3dd4b9647dbdbfc2c1d86a315328ac3a40461',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
