) VALUES (
  gen_random_uuid()::text,
  'pance',
  'hematologic',
  3,
  'hematologic',
  'hematologic',
  'diagnosis',
  'Transfusion reaction during the unit',
  'vignette',
  'Ten minutes into a red-cell transfusion a patient has fever, flank pain, and dark urine. Blood pressure falls.',
  'Which of the following is the most appropriate first action?',
  '{"options":["Slow the rate and give diphenhydramine","Stop the transfusion and keep the line open with saline","Give another unit faster","Antibiotics and continue the blood","Furosemide and continue"],"blueprintSystem":"hematologic","taskCategory":"diagnosis","blueprintTopic":"Transfusion reaction during the unit","kind":"vignette"}',
  'Stop the transfusion and keep the line open with saline',
  'Stop the transfusion and keep the line open with saline is correct. Fever, pain, hypotension, and hemoglobinuria during a transfusion are acute hemolysis until proved otherwise. The unit stops immediately. The line is not flushed with the remaining blood. Incorrect alternatives: Slowing the rate, a second unit, continuing through antibiotics, and a diuretic while blood still runs leave incompatible blood infusing.',
  '["pance","PANCE-2025","hematologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '85ed30a70e7a3d2dc4c542c66dd6d3693f60e92dd3350c1855fdbc47935aeb45',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
