) VALUES (
  gen_random_uuid()::text,
  'pance',
  'hematologic',
  4,
  'hematologic',
  'hematologic',
  'pharmacotherapy',
  'VTE and active cancer',
  'vignette',
  'A 60-year-old woman with metastatic cancer has a new proximal DVT. She is not bleeding. Creatinine is normal. She asks about a pill.',
  'Which of the following is an acceptable anticoagulant class?',
  '{"options":["Aspirin","A direct oral anticoagulant or low-molecular-weight heparin","Unfractionated heparin for 3 days and then nothing","Warfarin with no bridge in a patient who needs immediate coverage","A vena cava filter as the preferred first treatment"],"blueprintSystem":"hematologic","taskCategory":"pharmacotherapy","blueprintTopic":"VTE and active cancer","kind":"vignette"}',
  'A direct oral anticoagulant or low-molecular-weight heparin',
  'A direct oral anticoagulant or low-molecular-weight heparin is correct. Cancer-associated proximal DVT is treated, and a direct oral anticoagulant is now an acceptable option alongside low-molecular-weight heparin in patients without a contraindication. Incorrect alternatives: Aspirin, a 3-day course, warfarin with a gap, and a filter first are not the treatment.',
  '["pance","PANCE-2025","hematologic","pance-200-20261108-v1"]',
  '[{"label":"Stevens SM et al. Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline. Chest 2021","url":"https://journal.chestnet.org/article/S0012-3692(21)01506-3/fulltext"}]'::jsonb,
  'generated',
  '6197a8e0b7990b3147252a0210c02dab4ee7e68a1a76102cd00229275cc8a597',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
