) VALUES (
  gen_random_uuid()::text,
  'pance',
  'hematologic',
  5,
  'hematologic',
  'hematologic',
  'diagnosis',
  'Sickle acute chest',
  'vignette',
  'A 22-year-old man with hemoglobin SS has chest pain, fever, and a new infiltrate. Oxygen saturation fell from 98% to 88%. He is on incentive spirometry.',
  'Which of the following is the most appropriate additional plan?',
  '{"options":["Discharge on oral antibiotics","Admit, antibiotics, oxygen, and exchange transfusion if respiratory failure worsens","Hydroxyurea as the only acute drug","A diuretic as primary therapy","No transfusion is ever used in sickle cell disease"],"blueprintSystem":"hematologic","taskCategory":"diagnosis","blueprintTopic":"Sickle acute chest","kind":"vignette"}',
  'Admit, antibiotics, oxygen, and exchange transfusion if respiratory failure worsens',
  'Admit, antibiotics, oxygen, and exchange transfusion if respiratory failure worsens is correct. A new infiltrate, chest pain, fever, and hypoxia in sickle cell disease are acute chest syndrome. He is admitted. Simple or exchange transfusion is used for respiratory compromise. Incentive spirometry continues. Incorrect alternatives: Discharge, hydroxyurea as the sole acute drug, diuresis, and a ban on transfusion are incorrect.',
  '["pance","PANCE-2025","hematologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '21796bb167b888f2b6c32a082baf7085d3ddc5a8edfe8cf547eb68ffb520ccba',
  'pance-200-20261108-v1',
  'pending',
  false,
