  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'hematologic',
  4,
  'hematologic',
  'hematologic',
  'labs',
  'Mixing study',
  'vignette',
  'A 19-year-old man has a deep bleed into the thigh. aPTT is 68 seconds and does not correct when his plasma is mixed 1:1 with normal plasma. PT is normal. He has no heparin exposure.',
  'Which of the following does a failure to correct suggest?',
  '{"options":["Factor deficiency","An inhibitor","Thrombocytopenia","Vitamin K deficiency","A short sample"],"blueprintSystem":"hematologic","taskCategory":"labs","blueprintTopic":"Mixing study","kind":"vignette"}',
  'An inhibitor',
  'An inhibitor is correct. A mixing study that corrects implies a missing factor. A mixing study that does not correct implies an inhibitor, such as a factor VIII inhibitor or a lupus anticoagulant. His bleed plus a long aPTT fits an acquired or alloimmune inhibitor more than a lupus anticoagulant, which usually clots. Incorrect alternatives: Factor deficiency corrects. Thrombocytopenia does not prolong aPTT this way. Vitamin K deficiency prolongs the PT. A short sample is a collection problem, not this pattern.',
  '["pance","PANCE-2025","hematologic","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'a19f25c5b27548ad1c326e7a25f110154fbd928b07aa81ced16f0ae3c2fa4737',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'reproductive',
  5,
  'reproductive',
  'reproductive',
  'diagnosis',
  'Ectopic pregnancy threshold',
  'vignette',
  'A 27-year-old woman has pelvic pain and spotting. The urine pregnancy test is positive. Quantitative hCG is 2,800 mIU/mL. Transvaginal ultrasound shows an empty uterus and no adnexal mass. She is hemodynamically stable.',
  'Which of the following is the most appropriate next step?',
  '{"options":["Tell her she is not pregnant","Repeat hCG and ultrasound; do not give methotrexate on a single nondiagnostic scan","Dilation and curettage tonight as the only option","Discharge with no follow-up","Start misoprostol at home with no warning"],"blueprintSystem":"reproductive","taskCategory":"diagnosis","blueprintTopic":"Ectopic pregnancy threshold","kind":"vignette"}',
  'Repeat hCG and ultrasound; do not give methotrexate on a single nondiagnostic scan',
  'Repeat hCG and ultrasound; do not give methotrexate on a single nondiagnostic scan is correct. An empty uterus at an hCG above the discriminatory zone is concerning for ectopic pregnancy but is not by itself a diagnosis. A stable patient gets a repeat quantitative hCG and a repeat scan, with precautions, rather than immediate methotrexate. Incorrect alternatives: Denying the pregnancy, immediate curettage as the only path, and sending her out with no plan miss a rupture.',
  '["pance","PANCE-2025","reproductive","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'ac3a2409577bfa877b1abc572e12aa98f6a5850ee7b4308d715076ddb167987a',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'reproductive',
  5,
  'reproductive',
  'reproductive',
  'pharmacotherapy',
  'Methotrexate eligibility',
  'vignette',
  'A 31-year-old woman has a confirmed tubal ectopic pregnancy. hCG is 2,200 mIU/mL. She has no fetal cardiac activity, no significant pain, and a normal hemoglobin. She can return for labs.',
  'Which of the following is appropriate?',
  '{"options":["Methotrexate is reasonable","She must have surgery because every ectopic is ruptured","Misoprostol","Expectant management with no follow-up","Mifepristone alone"],"blueprintSystem":"reproductive","taskCategory":"pharmacotherapy","blueprintTopic":"Methotrexate eligibility","kind":"vignette"}',
  'Methotrexate is reasonable',
  'Methotrexate is reasonable is correct. A small, unruptured ectopic pregnancy in a reliable patient with a modest hCG can be treated with methotrexate and serial hCG. Surgery is for rupture, instability, or a contraindication to the drug. Incorrect alternatives: Mandatory surgery, misoprostol, unsupervised waiting, and mifepristone alone are not the regimen.',
  '["pance","PANCE-2025","reproductive","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '69c6d5d514bdffd1dd9edc26e5cf2892641ac2580500ba35538769921464489c',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
