  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'reproductive',
  4,
  'reproductive',
  'reproductive',
  'diagnosis',
  'Preeclampsia with severe features',
  'vignette',
  'A 32-year-old woman at 34 weeks has blood pressure 168/110 mm Hg, a headache, and proteinuria. Platelets are 90,000/mm3. She has no vaginal bleeding.',
  'Which of the following is the most appropriate immediate drug for seizure prevention?',
  '{"options":["Lisinopril","Magnesium sulfate","Furosemide","A thiazide","Losartan"],"blueprintSystem":"reproductive","taskCategory":"diagnosis","blueprintTopic":"Preeclampsia with severe features","kind":"vignette"}',
  'Magnesium sulfate',
  'Magnesium sulfate is correct. Severe-range pressures with headache and thrombocytopenia are preeclampsia with severe features. Magnesium prevents seizures. Delivery planning is obstetric. ACE inhibitors and ARBs are contraindicated. Incorrect alternatives: Lisinopril, losartan, and diuretics are not the seizure-prevention drug and several are fetotoxic.',
  '["pance","PANCE-2025","reproductive","pance-200-20261108-v1"]',
  '[{"label":"Jones DW et al. 2025 AHA/ACC Guideline for the Management of High Blood Pressure in Adults. J Am Coll Cardiol 2025","url":"https://pubmed.ncbi.nlm.nih.gov/40815242/"}]'::jsonb,
  'generated',
  '43134af00491fdbe157f6de7228447ec5df16d17aa5f110a0625ac8e05a8896f',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
