) VALUES (
  gen_random_uuid()::text,
  'pance',
  'reproductive',
  3,
  'reproductive',
  'reproductive',
  'pharmacotherapy',
  'Postpartum hemorrhage uterotonic',
  'vignette',
  'A 29-year-old woman just delivered and is bleeding heavily. The uterus is boggy. She has no hypertension. Oxytocin is running.',
  'Which of the following is an appropriate additional uterotonic if oxytocin is not enough?',
  '{"options":["Terbutaline","Methylergonovine, if blood pressure allows, or misoprostol","Magnesium","Labetalol","Nifedipine"],"blueprintSystem":"reproductive","taskCategory":"pharmacotherapy","blueprintTopic":"Postpartum hemorrhage uterotonic","kind":"vignette"}',
  'Methylergonovine, if blood pressure allows, or misoprostol',
  'Methylergonovine, if blood pressure allows, or misoprostol is correct. Atony is treated by emptying the bladder, uterine massage, oxytocin, and then another uterotonic. Methylergonovine is avoided in hypertension. Misoprostol is an alternative. Tocolytics such as terbutaline and magnesium relax the uterus. Incorrect alternatives: Terbutaline, magnesium, labetalol, and nifedipine do not contract the uterus.',
  '["pance","PANCE-2025","reproductive","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'd410621e9a843daca6ab696bc0c4122ab92ea52045c2e9abd3628dfa9f8780b7',
  'pance-200-20261108-v1',
  'pending',
