) VALUES (
  gen_random_uuid()::text,
  'pance',
  'reproductive',
  3,
  'reproductive',
  'reproductive',
  'diagnosis',
  'Endometrial biopsy age',
  'vignette',
  'A 62-year-old woman has postmenopausal bleeding. She is not on hormone therapy. The cervix looks normal. Pregnancy is impossible.',
  'Which of the following is the most appropriate next evaluation?',
  '{"options":["Reassurance that one episode is always benign","Endometrial sampling, usually with ultrasound","Oral contraceptives","A Pap test as the only study","Antibiotics"],"blueprintSystem":"reproductive","taskCategory":"diagnosis","blueprintTopic":"Endometrial biopsy age","kind":"vignette"}',
  'Endometrial sampling, usually with ultrasound',
  'Endometrial sampling, usually with ultrasound is correct. Any postmenopausal bleeding is endometrial cancer until sampling or a thin stripe and a clear plan say otherwise. A Pap test does not evaluate the endometrium. Incorrect alternatives: Reassurance, contraceptives, a Pap alone, and antibiotics miss cancer.',
  '["pance","PANCE-2025","reproductive","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '99e46069b8c7cd67d95b79ee1cc87272ecad2deb59f6db8b359e996618828438',
  'pance-200-20261108-v1',
  'pending',
  false,
