) VALUES (
  gen_random_uuid()::text,
  'pance',
  'reproductive',
  4,
  'reproductive',
  'reproductive',
  'pharmacotherapy',
  'Combined oral contraceptive contraindications',
  'vignette',
  'A 36-year-old woman who smokes a pack a day wants a combined oral contraceptive. Blood pressure is 128/78 mm Hg. She has migraine without aura.',
  'Which of the following is the most appropriate counseling?',
  '{"options":["A combined pill is preferred because she is under 40","Avoid estrogen; age 35 or older plus smoking is a contraindication to combined hormonal contraception","The pill will help her quit smoking so it should be started","A combined pill is required before any progestin method","No method is safe"],"blueprintSystem":"reproductive","taskCategory":"pharmacotherapy","blueprintTopic":"Combined oral contraceptive contraindications","kind":"vignette"}',
  'Avoid estrogen; age 35 or older plus smoking is a contraindication to combined hormonal contraception',
  'Avoid estrogen; age 35 or older plus smoking is a contraindication to combined hormonal contraception is correct. Estrogen plus smoking at age 35 or older raises thrombosis and cardiovascular risk. A progestin-only method or nonhormonal method is discussed instead. Incorrect alternatives: Preferring a combined pill, using it as a quit aid, requiring it, and saying nothing is safe are incorrect.',
  '["pance","PANCE-2025","reproductive","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'cc05877759439012b8c9d65dc5d62344ba7374da609d813db8a1ff4e4841252d',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
