) VALUES (
  gen_random_uuid()::text,
  'pance',
  'reproductive',
  3,
  'reproductive',
  'reproductive',
  'diagnosis',
  'PID outpatient criteria',
  'vignette',
  'A 23-year-old woman has lower abdominal pain, cervical motion tenderness, and a fever of 38.0 C. She is not pregnant. She can tolerate oral medication and has no abscess on exam.',
  'Which of the following is appropriate outpatient therapy?',
  '{"options":["Metronidazole only","Ceftriaxone plus doxycycline, with metronidazole","Ciprofloxacin alone","Azithromycin once","No antibiotics until a culture grows"],"blueprintSystem":"reproductive","taskCategory":"diagnosis","blueprintTopic":"PID outpatient criteria","kind":"vignette"}',
  'Ceftriaxone plus doxycycline, with metronidazole',
  'Ceftriaxone plus doxycycline, with metronidazole is correct. Pelvic inflammatory disease is a clinical diagnosis. Outpatient treatment covers gonorrhea, chlamydia, and anaerobes when she is well enough to go home. Pregnancy, vomiting, or an abscess would admit her. Incorrect alternatives: Metronidazole alone, ciprofloxacin, one dose of azithromycin, and waiting on culture under-treat.',
  '["pance","PANCE-2025","reproductive","pance-200-20261108-v1"]',
  '[{"label":"Workowski KA et al. Sexually Transmitted Infections Treatment Guidelines, 2021. MMWR Recomm Rep 2021","url":"https://www.cdc.gov/std/treatment-guidelines/epididymitis.htm"}]'::jsonb,
  'generated',
  '1ec0595b1c0a8bc0c8deb21e37f77ab813a855623952f33a755617ae5cecc2fc',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
