  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'reproductive',
  3,
  'reproductive',
  'reproductive',
  'prevention',
  'Rh immunoglobulin timing',
  'vignette',
  'A 28-year-old Rh-negative woman at 28 weeks has a negative antibody screen. The father is Rh positive. She has not received Rh immunoglobulin this pregnancy.',
  'Which of the following is the most appropriate plan?',
  '{"options":["No Rh immunoglobulin until delivery, and only if the baby is Rh negative","Give Rh immunoglobulin at 28 weeks and again after delivery if the newborn is Rh positive","Give it only if she is already alloimmunized","Methotrexate","A blood transfusion"],"blueprintSystem":"reproductive","taskCategory":"prevention","blueprintTopic":"Rh immunoglobulin timing","kind":"vignette"}',
  'Give Rh immunoglobulin at 28 weeks and again after delivery if the newborn is Rh positive',
  'Give Rh immunoglobulin at 28 weeks and again after delivery if the newborn is Rh positive is correct. Antepartum Rh immunoglobulin at about 28 weeks, and postpartum if the infant is Rh positive, prevents sensitization. It is not withheld until she is already immunized, and it is not skipped because the baby might be negative until that is known. Incorrect alternatives: Waiting for a negative infant, treating existing alloimmunization with the same logic, methotrexate, and transfusion are wrong.',
  '["pance","PANCE-2025","reproductive","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'ac3ded9c2250584cbd290a94bfb27f4b081b2090f2ffe9850553777dc4d229db',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
