  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'psychiatry',
  5,
  'psychiatry',
  'psychiatry',
  'pharmacotherapy',
  'Serotonin syndrome versus NMS',
  'vignette',
  'A 30-year-old man started an SSRI and tramadol a day ago. He is agitated, febrile, shivering, and hyperreflexive with clonus. Creatine kinase is mildly up. He is not rigid.',
  'Which of the following is the most likely diagnosis?',
  '{"options":["Neuroleptic malignant syndrome","Serotonin syndrome","Malignant hyperthermia from no anesthetic","Sepsis as the only possibility","Catatonia"],"blueprintSystem":"psychiatry","taskCategory":"pharmacotherapy","blueprintTopic":"Serotonin syndrome versus NMS","kind":"vignette"}',
  'Serotonin syndrome',
  'Serotonin syndrome is correct. Clonus, hyperreflexia, shivering, and a rapid onset after two serotonergic drugs are serotonin syndrome. Neuroleptic malignant syndrome is lead-pipe rigidity, slower onset, and after a dopamine blocker. Incorrect alternatives: Malignant hyperthermia needs a triggering anesthetic. Sepsis is possible but does not produce clonus as the core sign. Catatonia is a different motor picture.',
  '["pance","PANCE-2025","psychiatry","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '246782e8efe83b4dde24a960d61b8821995c3ea7a13fc7a4e565be0bc359fc88',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
