  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'psychiatry',
  5,
  'psychiatry',
  'psychiatry',
  'pharmacotherapy',
  'Lithium toxicity and a thiazide',
  'vignette',
  'A 45-year-old woman on lithium starts hydrochlorothiazide for blood pressure. A week later she is ataxic and confused. A lithium level is pending.',
  'Which of the following best explains the interaction?',
  '{"options":["Thiazides lower lithium levels","Thiazides raise lithium levels by increasing reabsorption","The combination is required","Lithium toxicity presents only as a rash","No lab is needed"],"blueprintSystem":"psychiatry","taskCategory":"pharmacotherapy","blueprintTopic":"Lithium toxicity and a thiazide","kind":"vignette"}',
  'Thiazides raise lithium levels by increasing reabsorption',
  'Thiazides raise lithium levels by increasing reabsorption is correct. Volume contraction from a thiazide increases proximal lithium reabsorption and can cause toxicity. NSAIDs and ACE inhibitors do the same. The diuretic is stopped and the level is checked; severe toxicity may need dialysis. Incorrect alternatives: Thiazides do not lower the level. Toxicity is neurologic, not a rash, and a level is required.',
  '["pance","PANCE-2025","psychiatry","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'ee11b92c27a1f0aec59bd6c58011e2df0353ad34ce7218254fbd397d5b18cbc0',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
