) VALUES (
  gen_random_uuid()::text,
  'pance',
  'psychiatry',
  4,
  'psychiatry',
  'psychiatry',
  'pharmacotherapy',
  'Bupropion and seizures and eating disorders',
  'vignette',
  'A 22-year-old woman with bulimia and an active seizure disorder wants bupropion for depression. She purges daily.',
  'Which of the following is the most appropriate advice?',
  '{"options":["Bupropion is preferred in bulimia and epilepsy","Choose a different antidepressant; bupropion is contraindicated in bulimia and seizure disorders","Double the usual dose","Combine it with tramadol","No antidepressant is allowed"],"blueprintSystem":"psychiatry","taskCategory":"pharmacotherapy","blueprintTopic":"Bupropion and seizures and eating disorders","kind":"vignette"}',
  'Choose a different antidepressant; bupropion is contraindicated in bulimia and seizure disorders',
  'Choose a different antidepressant; bupropion is contraindicated in bulimia and seizure disorders is correct. Bupropion lowers the seizure threshold and is contraindicated in current or prior bulimia or anorexia and in seizure disorders. Incorrect alternatives: Preferring it, raising the dose, adding tramadol, and refusing all antidepressants are incorrect.',
  '["pance","PANCE-2025","psychiatry","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'df6f42969a391b8e04cdf47a03ab19a985e2e1fbf30f86d2d08937647a995790',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
