  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'psychiatry',
  4,
  'psychiatry',
  'psychiatry',
  'diagnosis',
  'Suicide risk means ask, not a contract',
  'vignette',
  'A 19-year-old man says he has a plan to shoot himself tonight and access to a firearm. He is not intoxicated. He asks you not to tell anyone.',
  'Which of the following is the most appropriate action?',
  '{"options":["A no-harm contract and discharge","Emergency psychiatric evaluation and do not leave him alone with the firearm plan","Promise confidentiality and send him home","An antidepressant started in the parking lot as the only step","Tell him plans are not clinically meaningful"],"blueprintSystem":"psychiatry","taskCategory":"diagnosis","blueprintTopic":"Suicide risk means ask, not a contract","kind":"vignette"}',
  'Emergency psychiatric evaluation and do not leave him alone with the firearm plan',
  'Emergency psychiatric evaluation and do not leave him alone with the firearm plan is correct. A specific plan, intent, and access are high risk. Safety overrides confidentiality. He needs emergency evaluation, means restriction, and not a paper contract. Incorrect alternatives: A contract, a secrecy promise, a prescription alone, and dismissing the plan are unsafe.',
  '["pance","PANCE-2025","psychiatry","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'f1599276f5b84833496917bcb5150ba5b4f1cd544d4df32dacd623c1939dd322',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
