  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'psychiatry',
  3,
  'psychiatry',
  'psychiatry',
  'pharmacotherapy',
  'Alcohol withdrawal benzodiazepine',
  'vignette',
  'A 55-year-old man with daily heavy alcohol use has a tremor, heart rate 120/min, and diaphoresis 18 hours after his last drink. He is oriented. CIWA score is high.',
  'Which of the following is the most appropriate first drug class?',
  '{"options":["Haloperidol alone","A benzodiazepine, tapered to symptoms","Bupropion","A beta blocker as monotherapy","Disulfiram during acute withdrawal"],"blueprintSystem":"psychiatry","taskCategory":"pharmacotherapy","blueprintTopic":"Alcohol withdrawal benzodiazepine","kind":"vignette"}',
  'A benzodiazepine, tapered to symptoms',
  'A benzodiazepine, tapered to symptoms is correct. Alcohol withdrawal is treated with benzodiazepines. Antipsychotics alone lower the seizure threshold. Disulfiram is not used in acute withdrawal. Incorrect alternatives: Haloperidol monotherapy, bupropion, a beta blocker alone, and disulfiram do not prevent seizures and delirium.',
  '["pance","PANCE-2025","psychiatry","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'cb7ff19b98f3e82eebd5e6508d096569b0fa421290b17b09a2e876458a2e6f89',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
