  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'psychiatry',
  4,
  'psychiatry',
  'psychiatry',
  'pharmacotherapy',
  'Adolescent depression and an SSRI',
  'vignette',
  'A 16-year-old has moderate major depression. Therapy is being arranged. There is no bipolar history. The family asks about medication and about suicidal thinking.',
  'Which of the following is appropriate counseling?',
  '{"options":["SSRIs are forbidden under 18","Fluoxetine has evidence in adolescents, and suicidal thoughts are monitored especially in the first weeks","A tricyclic is first line","Benzodiazepine monotherapy","No follow-up is needed after the first pill"],"blueprintSystem":"psychiatry","taskCategory":"pharmacotherapy","blueprintTopic":"Adolescent depression and an SSRI","kind":"vignette"}',
  'Fluoxetine has evidence in adolescents, and suicidal thoughts are monitored especially in the first weeks',
  'Fluoxetine has evidence in adolescents, and suicidal thoughts are monitored especially in the first weeks is correct. Fluoxetine is the SSRI with the best adolescent evidence. The boxed warning means close follow-up for emerging suicidal thoughts, not a ban. Incorrect alternatives: A tricyclic, a benzodiazepine alone, and no follow-up are poor choices.',
  '["pance","PANCE-2025","psychiatry","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '12ac3f4a2e69c81afdafc8743dc26f29f7071dc8baf7e292ef6b12380a632a8d',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
