  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'psychiatry',
  3,
  'psychiatry',
  'psychiatry',
  'diagnosis',
  'Delirium is not dementia',
  'vignette',
  'An 80-year-old man is suddenly inattentive and hallucinating on postoperative day 2. He was sharp yesterday. The family says his memory has been normal.',
  'Which of the following is the most likely diagnosis?',
  '{"options":["Alzheimer disease starting today","Delirium","Schizophrenia","Autism","A conversion disorder"],"blueprintSystem":"psychiatry","taskCategory":"diagnosis","blueprintTopic":"Delirium is not dementia","kind":"vignette"}',
  'Delirium',
  'Delirium is correct. Acute inattention and a fluctuating course in a hospitalized older adult are delirium. The cause, including drugs, infection, and metabolic change, is sought. Dementia is chronic. Incorrect alternatives: A one-day onset is not Alzheimer disease, schizophrenia, autism, or conversion.',
  '["pance","PANCE-2025","psychiatry","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '62046f8c039686217887b57b24937aa556250b252e91ed8b94039aa74d8561b5',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
