) VALUES (
  gen_random_uuid()::text,
  'pance',
  'psychiatry',
  3,
  'psychiatry',
  'psychiatry',
  'pharmacotherapy',
  'MAO inhibitor food interaction',
  'vignette',
  'A 50-year-old man on phenelzine eats aged cheese and develops a severe headache and blood pressure of 210/120 mm Hg.',
  'Which of the following is the mechanism?',
  '{"options":["Cheese deficiency of sodium","Tyramine provokes a hypertensive reaction when monoamine oxidase is inhibited","An expected benefit of the diet","Serotonin syndrome from cheese alone","Hypotension from tyramine"],"blueprintSystem":"psychiatry","taskCategory":"pharmacotherapy","blueprintTopic":"MAO inhibitor food interaction","kind":"vignette"}',
  'Tyramine provokes a hypertensive reaction when monoamine oxidase is inhibited',
  'Tyramine provokes a hypertensive reaction when monoamine oxidase is inhibited is correct. MAO inhibitors plus tyramine-rich food cause hypertensive crisis. He needs blood-pressure treatment and education, not more cheese. Incorrect alternatives: This is not sodium deficiency, a desired effect, serotonin syndrome, or hypotension.',
  '["pance","PANCE-2025","psychiatry","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '8f7126ccc234c8e614795fca32df70b4546ba909b2b2d9198dd60e5461b77bb7',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'professional-practice',
  4,
  'professional-practice',
  'professional-practice',
  'professional',
  'Capacity is decision-specific',
  'vignette',
  'A 70-year-old man with mild dementia refuses a recommended amputation for a gangrenous foot. He can describe the infection, the risk of death, and his reason for refusing. He is not delirious.',
  'Which of the following is the most appropriate conclusion?',
  '{"options":["Dementia always removes capacity","He has capacity for this decision and the refusal stands","The family signs consent over his objection","Operate under implied consent because the disease is serious","Capacity requires agreement with the clinician"],"blueprintSystem":"professional-practice","taskCategory":"professional","blueprintTopic":"Capacity is decision-specific","kind":"vignette"}',
  'He has capacity for this decision and the refusal stands',
  'He has capacity for this decision and the refusal stands is correct. Capacity is specific to the decision. If he understands, appreciates, reasons, and communicates a choice, a dementia label does not erase the refusal. Incorrect alternatives: Automatic incapacity, family override, implied consent, and equating capacity with compliance are incorrect.',
  '["pance","PANCE-2025","professional-practice","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'a03b14f68dc59e24367c66948fc681f770d2625a87d6c434425bcf27c3fab72a',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
