) VALUES (
  gen_random_uuid()::text,
  'pance',
  'professional-practice',
  3,
  'professional-practice',
  'professional-practice',
  'professional',
  'Error disclosure',
  'vignette',
  'A physician assistant gave the wrong dose of insulin. The patient became hypoglycemic and recovered. The error is clear.',
  'Which of the following is the most appropriate communication?',
  '{"options":["Do not mention it unless the patient asks","Tell the patient what happened, the consequences, and what will change","Blame the nurse in the note and say nothing to the patient","Alter the record","Wait a year"],"blueprintSystem":"professional-practice","taskCategory":"professional","blueprintTopic":"Error disclosure","kind":"vignette"}',
  'Tell the patient what happened, the consequences, and what will change',
  'Tell the patient what happened, the consequences, and what will change is correct. Patients are told about errors that affect them. Disclosure includes the fact, the effect, and the plan to prevent a repeat. The record is not altered. Incorrect alternatives: Silence, blame without disclosure, altering the chart, and a long delay fail that duty.',
  '["pance","PANCE-2025","professional-practice","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'f15294a36859a1555bd0eaf8eeba0082e627b2945b73e405eb0fa174e38ea35e',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
