) VALUES (
  gen_random_uuid()::text,
  'pance',
  'professional-practice',
  3,
  'professional-practice',
  'professional-practice',
  'professional',
  'Impaired colleague',
  'vignette',
  'You smell alcohol on a colleague who is about to start a procedure list. Two other staff noticed slurred speech. The colleague says it is mouthwash.',
  'Which of the following is the most appropriate action?',
  '{"options":["Ignore it to preserve the friendship","Remove the colleague from patient care and notify the supervisor","Post it on social media","Wait until a patient is harmed","Trade shifts and say nothing"],"blueprintSystem":"professional-practice","taskCategory":"professional","blueprintTopic":"Impaired colleague","kind":"vignette"}',
  'Remove the colleague from patient care and notify the supervisor',
  'Remove the colleague from patient care and notify the supervisor is correct. An impaired clinician is removed from care immediately. The report goes through the institution, not through public shaming, and it does not wait for an injury. Incorrect alternatives: Silence, social media, and waiting for harm leave patients exposed.',
  '["pance","PANCE-2025","professional-practice","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '969e39455df52498d6d561e4b83c7561c93fc977f106cceb334b5d70efbd37a7',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
