  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'professional-practice',
  3,
  'professional-practice',
  'professional-practice',
  'professional',
  'Minor and confidential contraception',
  'vignette',
  'A 16-year-old requests contraception and asks that her parents not be told. She is not in danger. State law allows minors to consent to contraceptive care.',
  'Which of the following is the most appropriate action?',
  '{"options":["Refuse until a parent signs","Provide the care confidentially, consistent with the law","Call the parents before the visit ends","Document the request and do nothing","Require a court order"],"blueprintSystem":"professional-practice","taskCategory":"professional","blueprintTopic":"Minor and confidential contraception","kind":"vignette"}',
  'Provide the care confidentially, consistent with the law',
  'Provide the care confidentially, consistent with the law is correct. Where minors may consent to contraception, the visit is confidential. Safety concerns such as abuse are a separate duty and are not described here. Incorrect alternatives: A parental signature, a phone call home, inaction, and a court order contradict that statute.',
  '["pance","PANCE-2025","professional-practice","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'ad7c9e7f6129127f810e522d54f2afec81d2d0c9fd7d4fb2b7f26b1666f23c86',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
