  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'professional-practice',
  3,
  'professional-practice',
  'professional-practice',
  'professional',
  'Interpreter, not the child',
  'vignette',
  'A 45-year-old woman speaks little English. Her 10-year-old son offers to interpret a new cancer diagnosis.',
  'Which of the following is the most appropriate interpreter?',
  '{"options":["The son, because he is present","A qualified medical interpreter","No interpreter, using gestures for consent","A bilingual janitor who happened to walk by, with no training","Delay the news indefinitely"],"blueprintSystem":"professional-practice","taskCategory":"professional","blueprintTopic":"Interpreter, not the child","kind":"vignette"}',
  'A qualified medical interpreter',
  'A qualified medical interpreter is correct. Children should not interpret serious medical information. A qualified interpreter protects accuracy and the child''s role in the family. Incorrect alternatives: The son, gestures, an untrained bystander, and an indefinite delay are inadequate.',
  '["pance","PANCE-2025","professional-practice","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'e4d7177cb1da2df81ec442a3fb27adc65ab6b83107ac5c0b29459b9b449579ac',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
