) VALUES (
  gen_random_uuid()::text,
  'pance',
  'professional-practice',
  3,
  'professional-practice',
  'professional-practice',
  'professional',
  'Gift from a device company',
  'vignette',
  'A device representative offers you a paid weekend trip unrelated to any educational program, in exchange for using their product.',
  'Which of the following is the most appropriate response?',
  '{"options":["Accept if you disclose it to patients later","Decline; a personal trip is not a legitimate educational support","Accept and hide it","Accept only if the trip is first class","Ask the representative to pay your mortgage instead"],"blueprintSystem":"professional-practice","taskCategory":"professional","blueprintTopic":"Gift from a device company","kind":"vignette"}',
  'Decline; a personal trip is not a legitimate educational support',
  'Decline; a personal trip is not a legitimate educational support is correct. Gifts that are really payment for product choice are declined. Modest educational support with transparency is a different category from a vacation. Incorrect alternatives: Accepting, hiding, upgrading, or substituting another personal payment keeps the conflict.',
  '["pance","PANCE-2025","professional-practice","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '5ef343369b6636ee2c0aa9a030a7c999bd9950237caa6c0e8a2bbea826a673d4',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
