  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'professional-practice',
  3,
  'professional-practice',
  'professional-practice',
  'professional',
  'Just culture near miss',
  'vignette',
  'A look-alike vial was stocked next to a neuromuscular blocker. A nurse caught the error before administration. No one was harmed.',
  'Which of the following is the most useful response?',
  '{"options":["Punish the nurse who caught it","Fix the storage and labeling, and thank the person who reported the near miss","Ignore near misses","Fire the unit","Stop reporting so the numbers look better"],"blueprintSystem":"professional-practice","taskCategory":"professional","blueprintTopic":"Just culture near miss","kind":"vignette"}',
  'Fix the storage and labeling, and thank the person who reported the near miss',
  'Fix the storage and labeling, and thank the person who reported the near miss is correct. A just culture treats a system trap as a system problem. Near misses are reported because they show the hazard before a patient is hurt. Incorrect alternatives: Punishing the reporter, ignoring the miss, collective firing, and suppressing reports hide the next event.',
  '["pance","PANCE-2025","professional-practice","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  '6ab71d26d7f23ed54e7cb7d564a7aec02186fd9eed37c21eb6dea82210198981',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "taskCategory", "blueprintTopic", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
