  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'pance',
  'professional-practice',
  3,
  'professional-practice',
  'professional-practice',
  'professional',
  'Against medical advice and capacity',
  'vignette',
  'A capacitated adult with pneumonia wants to leave. You have explained the risk of death. He repeats the risk and still wants to go. He is not suicidal.',
  'Which of the following is the most appropriate action?',
  '{"options":["Restrain him","Document the discussion, offer prescriptions and return precautions, and let him leave","Call security to force antibiotics","Refuse to document","Tell him leaving makes him ineligible for any future care"],"blueprintSystem":"professional-practice","taskCategory":"professional","blueprintTopic":"Against medical advice and capacity","kind":"vignette"}',
  'Document the discussion, offer prescriptions and return precautions, and let him leave',
  'Document the discussion, offer prescriptions and return precautions, and let him leave is correct. A capacitated refusal is honored. The conversation, the risks, and what you offered are documented. Treatment to go and a door back are part of safe discharge. Incorrect alternatives: Restraints, forced drugs, a missing note, and a ban on future care are wrong.',
  '["pance","PANCE-2025","professional-practice","pance-200-20261108-v1"]',
  '[{"label":"NCCPA. Content Blueprint for the PANCE, effective January 2025. NCCPA 2025","url":"https://www.nccpa.net/wp-content/uploads/PANCE-Blueprint.pdf"}]'::jsonb,
  'generated',
  'fb0f5a2b7863af8cf9d6dcfc28c82afb50f55c2852c5fa8fbf583f75b1eb94ae',
  'pance-200-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
